insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','2sm',1,1,'E sucedeu que, depois da morte de Saul, voltando Davi da derrota dos amalequitas, ficou dois dias em Ziclague;'),
('acf','2sm',1,2,'Ao terceiro dia um homem veio do arraial de Saul, com as vestes rotas e com terra sobre a cabeça; e, chegando ele a Davi, se lançou no chão, e se inclinou.'),
('acf','2sm',1,3,'E Davi lhe disse: Donde vens? E ele lhe disse: Escapei do arraial de Israel.'),
('acf','2sm',1,4,'E disse-lhe Davi: Como foi lá isso? peço-te, dize-mo. E ele lhe respondeu: O povo fugiu da batalha, e muitos do povo caíram, e morreram; assim como também Saul e Jônatas, seu filho, foram mortos.'),
('acf','2sm',1,5,'E disse Davi ao moço que lhe trazia as novas: Como sabes tu que Saul e Jônatas, seu filho, foram mortos?'),
('acf','2sm',1,6,'Então disse o moço que lhe dava a notícia: Cheguei por acaso à montanha de Gilboa, e eis que Saul estava encostado sobre a sua lança, e eis que os carros e a cavalaria apertavam-no.'),
('acf','2sm',1,7,'E, olhando ele para trás de si, viu-me, e chamou-me; e eu disse: Eis-me aqui.'),
('acf','2sm',1,8,'E ele me disse: Quem és tu? E eu lhe disse: Sou amalequita.'),
('acf','2sm',1,9,'Então ele me disse: Peço-te, arremessa-te sobre mim, e mata-me, porque angústias me têm cercado, pois toda a minha vida está ainda em mim.'),
('acf','2sm',1,10,'Arremessei-me, pois, sobre ele, e o matei, porque bem sabia eu que não viveria depois da sua queda, e tomei a coroa que tinha na cabeça, e o bracelete que trazia no braço, e os trouxe aqui a meu senhor.'),
('acf','2sm',1,11,'Então apanhou Davi as suas vestes, e as rasgou; assim fizeram todos os homens que estavam com ele.'),
('acf','2sm',1,12,'E prantearam, e choraram, e jejuaram até à tarde por Saul, e por Jônatas, seu filho, e pelo povo do Senhor, e pela casa de Israel, porque tinham caído à espada.'),
('acf','2sm',1,13,'Disse então Davi ao moço que lhe trouxera a nova: Donde és tu? E disse ele: Sou filho de um estrangeiro, amalequita.'),
('acf','2sm',1,14,'E Davi lhe disse: Como não temeste tu estender a mão para matares ao ungido do Senhor?'),
('acf','2sm',1,15,'Então chamou Davi a um dos moços, e disse: Chega, e lança-te sobre ele. E ele o feriu, e morreu.'),
('acf','2sm',1,16,'Pois Davi lhe dissera: O teu sangue seja sobre a tua cabeça, porque a tua própria boca testificou contra ti, dizendo: Eu matei o ungido do Senhor.'),
('acf','2sm',1,17,'E lamentou Davi a Saul e a Jônatas, seu filho, com esta lamentação'),
('acf','2sm',1,18,'(Dizendo ele que ensinassem aos filhos de Judá o uso do arco. Eis que está escrito no livro de Jasher):'),
('acf','2sm',1,19,'Ah, ornamento de Israel! Nos teus altos foi ferido, como caíram os poderosos!'),
('acf','2sm',1,20,'Não o noticieis em Gate, não o publiqueis nas ruas de Ascalom, para que não se alegrem as filhas dos filisteus, para que não saltem de contentamento as filhas dos incircuncisos.'),
('acf','2sm',1,21,'Vós, montes de Gilboa, nem orvalho, nem chuva caia sobre vós, nem haja campos de ofertas alçadas, pois aí desprezivelmente foi arrojado o escudo dos poderosos, o escudo de Saul, como se não fora ungido com óleo.'),
('acf','2sm',1,22,'Do sangue dos feridos, da gordura dos valentes, nunca se retirou para trás o arco de Jônatas, nem voltou vazia a espada de Saul.'),
('acf','2sm',1,23,'Saul e Jônatas, tão amados e queridos na sua vida, também na sua morte não se separaram; eram mais ligeiros do que as águias, mais fortes do que os leões.'),
('acf','2sm',1,24,'Vós, filhas de Israel, chorai por Saul, que vos vestia de escarlata em delícias, que vos fazia trazer ornamentos de ouro sobre as vossas vestes.'),
('acf','2sm',1,25,'Como caíram os poderosos, no meio da peleja! Jônatas nos teus altos foi morto.'),
('acf','2sm',1,26,'Angustiado estou por ti, meu irmão Jônatas; quão amabilíssimo me eras! Mais maravilhoso me era o teu amor do que o amor das mulheres.'),
('acf','2sm',1,27,'Como caíram os poderosos, e pereceram as armas de guerra!'),
('acf','2sm',2,1,'E sucedeu depois disto que Davi consultou ao SENHOR, dizendo: Subirei a alguma das cidades de Judá? E disse-lhe o SENHOR: Sobe. E falou Davi: Para onde subirei? E disse: Para Hebrom.'),
('acf','2sm',2,2,'E subiu Davi para lá, e também as suas duas mulheres, Ainoã, a jizreelita, e Abigail, a mulher de Nabal, o carmelita.'),
('acf','2sm',2,3,'Fez também Davi subir os homens que estavam com ele, cada um com a sua família; e habitaram nas cidades de Hebrom.'),
('acf','2sm',2,4,'Então vieram os homens de Judá, e ungiram ali a Davi rei sobre a casa de Judá. E deram avisos a Davi, dizendo: Os homens de Jabes-Gileade foram os que sepultaram a Saul.'),
('acf','2sm',2,5,'Então enviou Davi mensageiros aos homens de Jabes-Gileade, para dizer-lhes: Benditos sejais vós do SENHOR, que fizestes tal beneficência a vosso senhor, a Saul, e o sepultastes!'),
('acf','2sm',2,6,'Agora, pois, o Senhor use convosco de beneficência e fidelidade; e também eu vos farei este bem, porquanto fizestes isto.'),
('acf','2sm',2,7,'Esforcem-se, pois, agora as vossas mãos, e sede homens valentes, pois Saul, vosso senhor, é morto, mas também os da casa de Judá já me ungiram a mim por seu rei.'),
('acf','2sm',2,8,'Porém Abner, filho de Ner, capitão do exército de Saul, tomou a Is-Bosete, filho de Saul, e o fez passar a Maanaim,'),
('acf','2sm',2,9,'E o constituiu rei sobre Gileade, e sobre os assuritas, e sobre Jizreel, e sobre Efraim, e sobre Benjamim, e sobre todo o Israel.'),
('acf','2sm',2,10,'Da idade de quarenta anos era Is-Bosete, filho de Saul, quando começou a reinar sobre Israel, e reinou dois anos; mas os da casa de Judá seguiam a Davi.'),
('acf','2sm',2,11,'E foi o número dos dias que Davi reinou em Hebrom, sobre a casa de Judá, sete anos e seis meses.'),
('acf','2sm',2,12,'Então saiu Abner, filho de Ner, com os servos de Is-Bosete, filho de Saul, de Maanaim a Gibeom.'),
('acf','2sm',2,13,'Saíram também Joabe, filho de Zeruia, e os servos de Davi, e se encontraram uns com os outros perto do tanque de Gibeom; e pararam estes deste lado do tanque, e os outros do outro lado do tanque.'),
('acf','2sm',2,14,'E disse Abner a Joabe: Deixa levantar os moços, e joguem diante de nós. E disse Joabe: Levantem-se.'),
('acf','2sm',2,15,'Então se levantaram, e passaram, em número de doze de Benjamim, da parte de Is-Bosete, filho de Saul, e doze dos servos de Davi.'),
('acf','2sm',2,16,'E cada um lançou mão da cabeça do outro, cravou-lhe a espada no lado, e caíram juntos, por isso se chamou àquele lugar Helcate-Hazurim, que está junto a Gibeom.'),
('acf','2sm',2,17,'E seguiu-se naquele dia uma crua peleja; porém Abner e os homens de Israel foram feridos diante dos servos de Davi.'),
('acf','2sm',2,18,'E estavam ali os três filhos de Zeruia, Joabe, Abisai, e Asael; e Asael era ligeiro de pés, como as gazelas do campo.'),
('acf','2sm',2,19,'E Asael perseguiu a Abner; e não se desviou de detrás de Abner, nem para a direita nem para a esquerda.'),
('acf','2sm',2,20,'E Abner, olhando para trás, perguntou: És tu Asael? E ele falou: Eu sou.'),
('acf','2sm',2,21,'Então lhe disse Abner: Desvia-te para a direita, ou para a esquerda, e lança mão de um dos moços, e toma os seus despojos. Porém Asael não quis desviar-se de detrás dele.'),
('acf','2sm',2,22,'Então Abner tornou a dizer a Asael: Desvia-te de detrás de mim; por que hei de eu ferir-te e dar contigo em terra? E como levantaria eu o meu rosto diante de Joabe, teu irmão?'),
('acf','2sm',2,23,'Porém, não querendo ele se desviar, Abner o feriu com a ponta da lança pela quinta costela, e a lança lhe saiu por detrás, e caiu ali, e morreu naquele mesmo lugar; e sucedeu que, todos os que chegavam ao lugar onde Asael caiu e morreu, paravam.'),
('acf','2sm',2,24,'Porém Joabe e Abisai perseguiram a Abner; e pôs-se o sol, chegando eles ao outeiro de Amá, que está diante de Gia, junto ao caminho do deserto de Gibeão.'),
('acf','2sm',2,25,'E os filhos de Benjamim se ajuntaram atrás de Abner, e fizeram um batalhão, e puseram-se no cume de um outeiro.'),
('acf','2sm',2,26,'Então Abner gritou a Joabe, e disse: Consumirá a espada para sempre? Não sabes tu que por fim haverá amargura? E até quando não hás de dizer ao povo que deixe de perseguir a seus irmãos?'),
('acf','2sm',2,27,'E disse Joabe: Vive Deus, que, se não tivesses falado, só pela manhã o povo teria cessado, cada um, de perseguir a seu irmão.'),
('acf','2sm',2,28,'Então Joabe tocou a buzina, e todo o povo parou, e não perseguiram mais a Israel; e tampouco pelejaram mais.'),
('acf','2sm',2,29,'E caminharam Abner e os seus homens toda aquela noite pela planície; e, passando o Jordão, caminharam por todo o Bitrom, e chegaram a Maanaim.'),
('acf','2sm',2,30,'Também Joabe voltou de perseguir a Abner, e ajuntou todo o povo; e dos servos de Davi faltaram dezenove homens, e Asael.'),
('acf','2sm',2,31,'Porém os servos de Davi feriram dentre os de Benjamim, e dentre os homens de Abner, a trezentos e sessenta homens, que ali ficaram mortos.'),
('acf','2sm',2,32,'E levantaram a Asael, e sepultaram-no na sepultura de seu pai, que estava em Belém; e Joabe e seus homens caminharam toda aquela noite, e amanheceu-lhes o dia em Hebrom.'),
('acf','2sm',3,1,'E houve uma longa guerra entre a casa de Saul e a casa de Davi; porém Davi ia se fortalecendo, mas os da casa de Saul se iam enfraquecendo.'),
('acf','2sm',3,2,'E a Davi nasceram filhos em Hebrom; e foi o seu primogênito Amnom, de Ainoã a jizreelita;'),
('acf','2sm',3,3,'E seu segundo, Quileabe, de Abigail, mulher de Nabal, o carmelita; e o terceiro Absalão, filho de Maaca, filha de Talmai, rei de Gesur;'),
('acf','2sm',3,4,'E o quarto, Adonias, filho de Hagite; e o quinto, Sefatias, filho de Abital;'),
('acf','2sm',3,5,'E o sexto, Itreão, de Eglá, também mulher de Davi; estes nasceram a Davi em Hebrom.'),
('acf','2sm',3,6,'E, havendo guerra entre a casa de Saul e a casa de Davi, sucedeu que Abner se fez poderoso na casa de Saul.'),
('acf','2sm',3,7,'E tinha tido Saul uma concubina, cujo nome era Rispa, filha de Aiá; e disse Is-Bosete a Abner: Por que possuíste a concubina de meu pai?'),
('acf','2sm',3,8,'Então se irou muito Abner pelas palavras de Is-Bosete, e disse: Sou eu cabeça de cão, que pertença a Judá? Ainda hoje faço beneficência à casa de Saul, teu pai, a seus irmãos, e a seus amigos, e não te entreguei nas mãos de Davi, e tu hoje buscas motivo para me argüires por causa da maldade de uma mulher.'),
('acf','2sm',3,9,'Assim faça Deus a Abner, e outro tanto, se, como o Senhor jurou a Davi, assim eu não lhe fizer,'),
('acf','2sm',3,10,'Transferindo o reino da casa de Saul, e confirmando o trono de Davi sobre Israel, e sobre Judá, desde Dã até Berseba.'),
('acf','2sm',3,11,'E nenhuma palavra podia ele responder a Abner, porque o temia.'),
('acf','2sm',3,12,'Então enviou Abner da sua parte mensageiros a Davi, dizendo: De quem é a terra? E disse mais: Comigo faze o teu acordo, e eis que a minha mão será contigo, para tornar a ti todo o Israel.'),
('acf','2sm',3,13,'E disse Davi: Bem, eu farei contigo acordo, porém uma coisa te peço: não verás a minha face, se primeiro não me trouxeres a Mical, filha de Saul, quando vieres ver a minha face.'),
('acf','2sm',3,14,'Também enviou Davi mensageiros a Is-Bosete, filho de Saul, dizendo: Dá-me minha mulher Mical, que eu desposei por cem prepúcios de filisteus.'),
('acf','2sm',3,15,'E enviou Is-Bosete, e tirou-a de seu marido, a Paltiel, filho de Laís.'),
('acf','2sm',3,16,'E ia com ela seu marido, caminhando, e chorando atrás dela, até Baurim. Então lhe disse Abner: Vai-te, agora volta. E ele voltou.'),
('acf','2sm',3,17,'E falou Abner com os anciãos de Israel, dizendo: Já há muito tempo que procuráveis que Davi reinasse sobre vós.'),
('acf','2sm',3,18,'Fazei-o, pois, agora, porque o Senhor falou a Davi, dizendo: Pela mão de Davi meu servo livrarei o meu povo das mãos dos filisteus e das mãos de todos os seus inimigos.'),
('acf','2sm',3,19,'E falou também Abner aos de Benjamim; e foi também Abner dizer aos de Davi, em Hebrom, tudo o que era bom aos olhos de Israel e aos olhos de toda a casa de Benjamim.'),
('acf','2sm',3,20,'E foi Abner a Davi, em Hebrom, e vinte homens com ele; e Davi fez um banquete a Abner e aos homens que com ele estavam.'),
('acf','2sm',3,21,'Então disse Abner a Davi: Eu me levantarei, e irei, e ajuntarei ao rei meu senhor todo o Israel, para fazer acordo contigo; e tu reinarás sobre tudo o que desejar a tua alma. Assim despediu Davi a Abner, e ele foi em paz.'),
('acf','2sm',3,22,'E eis que os servos de Davi e Joabe vieram de uma batalha, e traziam consigo grande despojo; e já Abner não estava com Davi em Hebrom, porque o tinha despedido, e se tinha ido em paz.'),
('acf','2sm',3,23,'Chegando, pois, Joabe, e todo o exército que vinha com ele, deram aviso a Joabe, dizendo: Abner, filho de Ner, veio ao rei, e o despediu, e foi em paz.'),
('acf','2sm',3,24,'Então Joabe foi ao rei, e disse: Que fizeste? Eis que Abner veio ter contigo; por que pois o despediste, de maneira que se fosse assim livremente?'),
('acf','2sm',3,25,'Bem conheces a Abner, filho de Ner, que te veio enganar, e saber a tua saída e a tua entrada, e entender tudo quanto fazes.'),
('acf','2sm',3,26,'E Joabe, retirando-se de Davi, enviou mensageiros atrás de Abner, e o fizeram voltar desde o poço de Sirá, sem que Davi o soubesse.'),
('acf','2sm',3,27,'Voltando, pois, Abner a Hebrom, Joabe o levou à parte, à entrada da porta, para lhe falar em segredo; e feriu-o ali pela quinta costela, e morreu, por causa do sangue de Asael seu irmão.'),
('acf','2sm',3,28,'O que Davi depois ouvindo, disse: Inocente sou eu, e o meu reino, para com o Senhor, para sempre, do sangue de Abner, filho de Ner.'),
('acf','2sm',3,29,'Caia sobre a cabeça de Joabe e sobre toda a casa de seu pai, e nunca na casa de Joabe falte quem tenha fluxo, ou quem seja leproso, ou quem se atenha a bordão, ou quem caia à espada, ou quem necessite de pão.'),
('acf','2sm',3,30,'Joabe, pois, e Abisai, seu irmão, mataram a Abner, por ter morto a Asael, seu irmão, na peleja em Gibeão.'),
('acf','2sm',3,31,'Disse, pois, Davi a Joabe, e a todo o povo que com ele estava: Rasgai as vossas vestes; e cingi-vos de sacos e ide pranteando diante de Abner. E o rei Davi ia seguindo o féretro.'),
('acf','2sm',3,32,'E, sepultando a Abner em Hebrom, o rei levantou a sua voz, e chorou junto da sepultura de Abner; e chorou todo o povo.'),
('acf','2sm',3,33,'E o rei, pranteando Abner, disse: Havia de morrer Abner como morre o vilão?'),
('acf','2sm',3,34,'As tuas mãos não estavam atadas, nem os teus pés carregados de grilhões, mas caíste como os que caem diante dos filhos da maldade! Então todo o povo chorou muito mais por ele.'),
('acf','2sm',3,35,'Depois todo o povo veio fazer com que Davi comesse pão, sendo ainda dia; porém Davi jurou, dizendo: Assim Deus me faça, e outro tanto, se, antes que o sol se ponha, eu provar pão ou alguma coisa.'),
('acf','2sm',3,36,'O que todo o povo entendendo, pareceu bem aos seus olhos; assim como tudo quanto o rei fez pareceu bem aos olhos de todo o povo.'),
('acf','2sm',3,37,'E todo o povo e todo o Israel entenderam naquele mesmo dia que não procedera do rei que matasse a Abner, filho de Ner.'),
('acf','2sm',3,38,'Então disse o rei aos seus servos: Não sabeis que hoje caiu em Israel um príncipe e um grande?'),
('acf','2sm',3,39,'Que eu hoje estou fraco, ainda que ungido rei; estes homens, filhos de Zeruia, são mais duros do que eu; o Senhor pagará ao malfeitor, conforme a sua maldade.'),
('acf','2sm',4,1,'Ouvindo, pois, o filho de Saul, que Abner morrera em Hebrom, as mãos se lhe afrouxaram; e todo o Israel pasmou.'),
('acf','2sm',4,2,'E tinha o filho de Saul dois homens capitães de tropas; e era o nome de um Baaná, e o nome do outro Recabe, filhos de Rimom, o beerotita, dos filhos de Benjamim, porque também Beerote se reputava de Benjamim.'),
('acf','2sm',4,3,'E tinham fugido os beerotitas para Gitaim, e ali têm peregrinado até ao dia de hoje.'),
('acf','2sm',4,4,'E Jônatas, filho de Saul, tinha um filho aleijado de ambos os pés; era da idade de cinco anos quando as novas de Saul e Jônatas vieram de Jizreel, e sua ama o tomou, e fugiu; e sucedeu que, apressando-se ela a fugir, ele caiu, e ficou coxo; e o seu nome era Mefibosete.'),
('acf','2sm',4,5,'E foram os filhos de Rimom, o beerotita, Recabe e Baaná, e entraram em casa de Is-Bosete no maior calor do dia, estando ele deitado a dormir, ao meio-dia.'),
('acf','2sm',4,6,'E ali entraram até ao meio da casa, como que vindo buscar trigo, e o feriram na quinta costela; e Recabe e Baaná, seu irmão, escaparam.'),
('acf','2sm',4,7,'Porque entraram na sua casa, estando ele na cama deitado, no seu quarto, e o feriram, e o mataram, e lhe cortaram a cabeça; e, tomando a sua cabeça, andaram toda a noite caminhando pela planície.'),
('acf','2sm',4,8,'E trouxeram a cabeça de Is-Bosete a Davi, a Hebrom, e disseram ao rei: Eis aqui a cabeça de Is-Bosete, filho de Saul, teu inimigo, que procurava a tua morte; assim o SENHOR vingou hoje ao rei meu senhor, de Saul e da sua descendência.'),
('acf','2sm',4,9,'Porém Davi, respondendo a Recabe e a Baaná, seu irmão, filhos de Rimom, o beerotita, disse-lhes: Vive o Senhor, que remiu a minha alma de toda a angústia,'),
('acf','2sm',4,10,'Se aquele que me trouxe novas, dizendo: Eis que Saul é morto, parecendo-lhe, porém, aos olhos que era como quem trazia boas novas, eu logo lancei mão dele, e o matei em Ziclague, cuidando ele que eu por isso lhe desse recompensa.'),
('acf','2sm',4,11,'Quanto mais a ímpios homens, que mataram um homem justo em sua casa, sobre a sua cama; agora, pois, não requereria eu o seu sangue de vossas mãos, e não vos exterminaria da terra?'),
('acf','2sm',4,12,'E deu Davi ordem aos seus moços que os matassem; e cortaram-lhes os pés e as mãos, e os penduraram sobre o tanque de Hebrom; tomaram, porém, a cabeça de Is-Bosete, e a sepultaram na sepultura de Abner, em Hebrom.'),
('acf','2sm',5,1,'Então todas as tribos de Israel vieram a Davi, em Hebrom, e falaram, dizendo: Eis-nos aqui, somos teus ossos e tua carne.'),
('acf','2sm',5,2,'E também outrora, sendo Saul ainda rei sobre nós, eras tu o que saías e entravas com Israel; e também o Senhor te disse: Tu apascentarás o meu povo de Israel, e tu serás príncipe sobre Israel.'),
('acf','2sm',5,3,'Assim, pois, todos os anciãos de Israel vieram ao rei, em Hebrom; e o rei Davi fez com eles acordo em Hebrom, perante o Senhor; e ungiram a Davi rei sobre Israel.'),
('acf','2sm',5,4,'Da idade de trinta anos era Davi quando começou a reinar; quarenta anos reinou.'),
('acf','2sm',5,5,'Em Hebrom reinou sobre Judá sete anos e seis meses, e em Jerusalém reinou trinta e três anos sobre todo o Israel e Judá.'),
('acf','2sm',5,6,'E partiu o rei com os seus homens a Jerusalém, contra os jebuseus que habitavam naquela terra; e falaram a Davi, dizendo: Não entrarás aqui, pois os cegos e os coxos te repelirão, querendo dizer: Não entrará Davi aqui.'),
('acf','2sm',5,7,'Porém Davi tomou a fortaleza de Sião; esta é a cidade de Davi.'),
('acf','2sm',5,8,'Porque Davi disse naquele dia: Qualquer que ferir aos jebuseus, suba ao canal e fira aos coxos e aos cegos, a quem a alma de Davi odeia. Por isso se diz: Nem cego nem coxo entrará nesta casa.'),
('acf','2sm',5,9,'Assim habitou Davi na fortaleza, e a chamou a cidade de Davi; e Davi foi edificando em redor, desde Milo para dentro.'),
('acf','2sm',5,10,'E Davi ia, cada vez mais, aumentando e crescendo, porque o Senhor Deus dos Exércitos era com ele.'),
('acf','2sm',5,11,'E Hirão, rei de Tiro, enviou mensageiros a Davi, e madeira de cedro, e carpinteiros, e pedreiros que edificaram a Davi uma casa.'),
('acf','2sm',5,12,'E entendeu Davi que o Senhor o confirmara rei sobre Israel, e que exaltara o seu reino por amor do seu povo.'),
('acf','2sm',5,13,'E tomou Davi mais concubinas e mulheres de Jerusalém, depois que viera de Hebrom; e nasceram a Davi mais filhos e filhas.'),
('acf','2sm',5,14,'E estes são os nomes dos que lhe nasceram em Jerusalém: Samua, e Sobabe, e Natã, e Salomão,'),
('acf','2sm',5,15,'E Ibar, e Elisua, e Nefegue, e Jafia,'),
('acf','2sm',5,16,'E Elisama, e Eliada, e Elifelete.'),
('acf','2sm',5,17,'Ouvindo, pois, os filisteus que haviam ungido a Davi rei sobre Israel, todos os filisteus subiram em busca de Davi; o que ouvindo Davi, desceu à fortaleza.'),
('acf','2sm',5,18,'E os filisteus vieram, e se estenderam pelo vale de Refaim.'),
('acf','2sm',5,19,'E Davi consultou ao Senhor, dizendo: Subirei contra os filisteus? Entregar-mos-ás nas minhas mãos? E disse o Senhor a Davi: Sobe, porque certamente entregarei os filisteus nas tuas mãos.'),
('acf','2sm',5,20,'Então foi Davi a Baal-Perazim; e feriu-os ali Davi, e disse: Rompeu o Senhor a meus inimigos diante de mim, como quem rompe águas. Por isso chamou o nome daquele lugar Baal-Perazim.'),
('acf','2sm',5,21,'E deixaram ali os seus ídolos; e Davi e os seus homens os tomaram.'),
('acf','2sm',5,22,'E os filisteus tornaram a subir, e se estenderam pelo vale de Refaim.'),
('acf','2sm',5,23,'E Davi consultou ao Senhor, o qual disse: Não subirás; mas rodeia por detrás deles, e virás a eles por defronte das amoreiras.'),
('acf','2sm',5,24,'E há de ser que, ouvindo tu um estrondo de marcha pelas copas das amoreiras, então te apressarás; porque o Senhor saiu então diante de ti, a ferir o arraial dos filisteus.'),
('acf','2sm',5,25,'E fez Davi assim como o Senhor lhe tinha ordenado; e feriu os filisteus desde Geba, até chegar a Gezer.'),
('acf','2sm',6,1,'E tornou Davi a ajuntar todos os escolhidos de Israel, em número de trinta mil.'),
('acf','2sm',6,2,'E levantou-se Davi, e partiu, com todo o povo que tinha consigo, para Baalim de Judá, para levarem dali para cima a arca de Deus, sobre a qual se invoca o nome, o nome do Senhor dos Exércitos, que se assenta entre os querubins.'),
('acf','2sm',6,3,'E puseram a arca de Deus em um carro novo, e a levaram da casa de Abinadabe, que está em Gibeá; e Uzá e Aiô, filhos de Abinadabe, guiavam o carro novo.'),
('acf','2sm',6,4,'E levando-o da casa de Abinadabe, que está em Gibeá, com a arca de Deus, Aiô ia adiante da arca.'),
('acf','2sm',6,5,'E Davi, e toda a casa de Israel, festejavam perante o Senhor, com toda a sorte de instrumentos de pau de faia, como também com harpas, e com saltérios, e com tamboris, e com pandeiros, e com címbalos.'),
('acf','2sm',6,6,'E, chegando à eira de Nacom, estendeu Uzá a mão à arca de Deus, e pegou nela; porque os bois a deixavam pender.'),
('acf','2sm',6,7,'Então a ira do Senhor se acendeu contra Uzá, e Deus o feriu ali por esta imprudência; e morreu ali junto à arca de Deus.'),
('acf','2sm',6,8,'E Davi se contristou, porque o Senhor abrira rotura em Uzá; e chamou àquele lugar Perez-Uzá, até ao dia de hoje.'),
('acf','2sm',6,9,'E temeu Davi ao Senhor naquele dia; e disse: Como virá a mim a arca do Senhor?'),
('acf','2sm',6,10,'E não quis Davi retirar para junto de si a arca do Senhor, à cidade de Davi; mas Davi a fez levar à casa de Obede-Edom, o giteu.'),
('acf','2sm',6,11,'E ficou a arca do Senhor em casa de Obede-Edom, o giteu, três meses; e abençoou o Senhor a Obede-Edom, e a toda a sua casa.'),
('acf','2sm',6,12,'Então avisaram a Davi, dizendo: Abençoou o Senhor a casa de Obede-Edom, e tudo quanto tem, por causa da arca de Deus; foi pois Davi, e trouxe a arca de Deus para cima, da casa de Obede-Edom, à cidade de Davi, com alegria.'),
('acf','2sm',6,13,'E sucedeu que, quando os que levavam a arca do Senhor tinham dado seis passos, sacrificava bois e carneiros cevados.'),
('acf','2sm',6,14,'E Davi saltava com todas as suas forças diante do Senhor; e estava Davi cingido de um éfode de linho.'),
('acf','2sm',6,15,'Assim subindo, levavam Davi e todo o Israel a arca do Senhor, com júbilo, e ao som das trombetas.'),
('acf','2sm',6,16,'E sucedeu que, entrando a arca do Senhor na cidade de Davi, Mical, a filha de Saul, estava olhando pela janela; e, vendo ao rei Davi, que ia bailando e saltando diante do Senhor, o desprezou no seu coração.'),
('acf','2sm',6,17,'E introduzindo a arca do Senhor, a puseram no seu lugar, na tenda que Davi lhe armara; e ofereceu Davi holocaustos e ofertas pacíficas perante o Senhor.'),
('acf','2sm',6,18,'E acabando Davi de oferecer os holocaustos e ofertas pacíficas, abençoou o povo em nome do Senhor dos Exércitos.'),
('acf','2sm',6,19,'E repartiu a todo o povo, e a toda a multidão de Israel, desde os homens até às mulheres, a cada um, um bolo de pão, e um bom pedaço de carne, e um frasco de vinho; então retirou-se todo o povo, cada um para sua casa,'),
('acf','2sm',6,20,'E, voltando Davi para abençoar a sua casa, Mical, a filha de Saul, saiu a encontrar-se com Davi, e disse: Quão honrado foi o rei de Israel, descobrindo-se hoje aos olhos das servas de seus servos, como sem pejo se descobre qualquer dos vadios.'),
('acf','2sm',6,21,'Disse, porém, Davi a Mical: Perante o Senhor, que me escolheu preferindo-me a teu pai, e a toda a sua casa, mandando-me que fosse soberano sobre o povo do Senhor, sobre Israel, perante o Senhor tenho me alegrado.'),
('acf','2sm',6,22,'E ainda mais do que isto me envilecerei, e me humilharei aos meus olhos; mas das servas, de quem falaste, delas serei honrado.'),
('acf','2sm',6,23,'E Mical, a filha de Saul, não teve filhos, até o dia da sua morte.'),
('acf','2sm',7,1,'E sucedeu que, estando o rei Davi em sua casa, e tendo o SENHOR lhe dado descanso de todos os seus inimigos em redor,'),
('acf','2sm',7,2,'Disse o rei ao profeta Natã: Eis que eu moro em casa de cedro, e a arca de Deus mora dentro de cortinas.'),
('acf','2sm',7,3,'E disse Natã ao rei: Vai, e faze tudo quanto está no teu coração; porque o Senhor é contigo.'),
('acf','2sm',7,4,'Porém sucedeu naquela mesma noite, que a palavra do Senhor veio a Natã, dizendo:'),
('acf','2sm',7,5,'Vai, e dize a meu servo Davi: Assim diz o Senhor: Edificar-me-ás tu uma casa para minha habitação?'),
('acf','2sm',7,6,'Porque em casa nenhuma habitei desde o dia em que fiz subir os filhos de Israel do Egito até ao dia de hoje; mas andei em tenda e em tabernáculo.'),
('acf','2sm',7,7,'E em todo o lugar em que andei com todos os filhos de Israel, falei porventura alguma palavra a alguma das tribos de Israel, a quem mandei apascentar o meu povo de Israel, dizendo: Por que não me edificais uma casa de cedro?'),
('acf','2sm',7,8,'Agora, pois, assim dirás ao meu servo Davi: Assim diz o Senhor dos Exércitos: Eu te tomei da malhada, de detrás das ovelhas, para que fosses o soberano sobre o meu povo, sobre Israel.'),
('acf','2sm',7,9,'E fui contigo, por onde quer que foste, e destruí a teus inimigos diante de ti; e fiz grande o teu nome, como o nome dos grandes que há na terra.'),
('acf','2sm',7,10,'E prepararei lugar para o meu povo, para Israel, e o plantarei, para que habite no seu lugar, e não mais seja removido, e nunca mais os filhos da perversidade o aflijam, como dantes,'),
('acf','2sm',7,11,'E desde o dia em que mandei que houvesse juízes sobre o meu povo Israel; a ti, porém, te dei descanso de todos os teus inimigos; também o Senhor te faz saber que te fará casa.'),
('acf','2sm',7,12,'Quando teus dias forem completos, e vieres a dormir com teus pais, então farei levantar depois de ti um dentre a tua descendência, o qual sairá das tuas entranhas, e estabelecerei o seu reino.'),
('acf','2sm',7,13,'Este edificará uma casa ao meu nome, e confirmarei o trono do seu reino para sempre.'),
('acf','2sm',7,14,'Eu lhe serei por pai, e ele me será por filho; e, se vier a transgredir, castigá-lo-ei com vara de homens, e com açoites de filhos de homens.'),
('acf','2sm',7,15,'Mas a minha benignidade não se apartará dele; como a tirei de Saul, a quem tirei de diante de ti.'),
('acf','2sm',7,16,'Porém a tua casa e o teu reino serão firmados para sempre diante de ti; teu trono será firme para sempre.'),
('acf','2sm',7,17,'Conforme a todas estas palavras, e conforme a toda esta visão, assim falou Natã a Davi.'),
('acf','2sm',7,18,'Então entrou o rei Davi, e ficou perante o SENHOR, e disse: Quem sou eu, Senhor DEUS, e qual é a minha casa, para que me tenhas trazido até aqui?'),
('acf','2sm',7,19,'E ainda foi isto pouco aos teus olhos, Senhor DEUS, senão que também falaste da casa de teu servo para tempos distantes; é este o procedimento dos homens, ó Senhor DEUS?'),
('acf','2sm',7,20,'E que mais te pode dizer ainda Davi? Pois tu conheces bem a teu servo, ó Senhor DEUS.'),
('acf','2sm',7,21,'Por causa da tua palavra, e segundo o teu coração, fizeste toda esta grandeza; fazendo-a saber a teu servo.'),
('acf','2sm',7,22,'Portanto, grandioso és, ó Senhor Deus, porque não há semelhante a ti, e não há outro Deus senão tu só, segundo tudo o que temos ouvido com os nossos ouvidos.'),
('acf','2sm',7,23,'E quem há como o teu povo, como Israel, gente única na terra, a quem Deus foi resgatar para seu povo, para fazer-te nome, e para fazer-vos estas grandes e terríveis coisas à tua terra, diante do teu povo, que tu resgataste do Egito, desterrando as nações e a seus deuses?'),
('acf','2sm',7,24,'E confirmaste a teu povo Israel por teu povo para sempre, e tu, Senhor, te fizeste o seu Deus.'),
('acf','2sm',7,25,'Agora, pois, ó Senhor Deus, esta palavra que falaste acerca de teu servo e acerca da sua casa, confirma-a para sempre, e faze como tens falado.'),
('acf','2sm',7,26,'E engrandeça-se o teu nome para sempre, para que se diga: O Senhor dos Exércitos é Deus sobre Israel; e a casa de teu servo será confirmada diante de ti.'),
('acf','2sm',7,27,'Pois tu, Senhor dos Exércitos, Deus de Israel, revelaste aos ouvidos de teu servo, dizendo: Edificar-te-ei uma casa. Portanto o teu servo se animou para fazer-te esta oração.'),
('acf','2sm',7,28,'Agora, pois, Senhor DEUS, tu és o mesmo Deus, e as tuas palavras são verdade, e tens falado a teu servo este bem.'),
('acf','2sm',7,29,'Sê, pois, agora servido de abençoar a casa de teu servo, para permanecer para sempre diante de ti, pois tu, ó Senhor DEUS, o disseste; e com a tua bênção será para sempre bendita a casa de teu servo.'),
('acf','2sm',8,1,'E sucedeu depois disto que Davi feriu os filisteus, e os sujeitou; e Davi tomou a Metegue-Ama das mãos dos filisteus.'),
('acf','2sm',8,2,'Também derrotou os moabitas, e os mediu com cordel, fazendo-os deitar por terra; e os mediu com dois cordéis para os matar, e com um cordel inteiro para os deixar com vida. Ficaram assim os moabitas por servos de Davi, pagando-lhe tributos.'),
('acf','2sm',8,3,'Feriu também Davi a Hadadezer, filho de Reobe, rei de Zobá, quando ele ia recuperar o seu domínio sobre o rio Eufrates.'),
('acf','2sm',8,4,'E tomou-lhe Davi mil carros e setecentos cavaleiros e vinte mil homens de pé; e Davi jarretou a todos os cavalos dos carros, e reservou deles cem carros.'),
('acf','2sm',8,5,'E vieram os sírios de Damasco a socorrer a Hadadezer, rei de Zobá; porém Davi feriu dos sírios vinte e dois mil homens.'),
('acf','2sm',8,6,'E Davi pôs guarnições na Síria de Damasco, e os sírios ficaram por servos de Davi, pagando-lhe tributos; e o Senhor guardou a Davi por onde quer que ia.'),
('acf','2sm',8,7,'E Davi tomou os escudos de ouro que havia com os servos de Hadadezer, e os trouxe a Jerusalém.'),
('acf','2sm',8,8,'Tomou mais o rei Davi uma quantidade muito grande de bronze de Betá e de Berotai, cidades de Hadadezer.'),
('acf','2sm',8,9,'Então ouvindo Toí, rei de Hamate, que Davi ferira a todo o exército de Hadadezer,'),
('acf','2sm',8,10,'Mandou Toí, seu filho Jorão, ao rei Davi, para lhe perguntar como estava, e para lhe dar os parabéns por haver pelejado contra Hadadezer, e por o haver ferido (porque Hadadezer de contínuo fazia guerra a Toí); e na sua mão trazia vasos de prata, e vasos de ouro, e vasos de bronze,'),
('acf','2sm',8,11,'Os quais também o rei Davi consagrou ao Senhor, juntamente com a prata e ouro que já havia consagrado de todas as nações que sujeitara.'),
('acf','2sm',8,12,'Da Síria, e de Moabe, e dos filhos de Amom, e dos filisteus, e de Amaleque, e dos despojos de Hadadezer, filho de Reobe, rei de Zobá.'),
('acf','2sm',8,13,'Também Davi ganhou nome, voltando ele de ferir os sírios no vale do Sal, a saber, a dezoito mil.'),
('acf','2sm',8,14,'E pôs guarnições, em Edom, em todo o Edom pôs guarnições, e todos os edomeus ficaram por servos de Davi; e o Senhor ajudava a Davi por onde quer que ia.'),
('acf','2sm',8,15,'Reinou, pois, Davi sobre todo o Israel; e Davi fazia direito e justiça a todo o seu povo.'),
('acf','2sm',8,16,'E Joabe, filho de Zeruia, era sobre o exército; e Jeosafá, filho de Ailude, era cronista.'),
('acf','2sm',8,17,'E Zadoque, filho de Aitube, e Aimeleque, filho de Abiatar, eram sacerdotes, e Seraías escrivão.'),
('acf','2sm',8,18,'Também Benaia, filho de Jeoiada, estava sobre os quereteus e peleteus; porém os filhos de Davi eram ministros.'),
('acf','2sm',9,1,'E disse Davi: Há ainda alguém que tenha ficado da casa de Saul, para que lhe faça benevolência por amor de Jônatas?'),
('acf','2sm',9,2,'E havia um servo na casa de Saul cujo nome era Ziba; e o chamaram à presença de Davi. Disse-lhe o rei: És tu Ziba? E ele disse: Servo teu.'),
('acf','2sm',9,3,'E disse o rei: Não há ainda alguém da casa de Saul para que eu use com ele da benevolência de Deus? Então disse Ziba ao rei: Ainda há um filho de Jônatas, aleijado de ambos os pés.'),
('acf','2sm',9,4,'E disse-lhe o rei: Onde está? E disse Ziba ao rei: Eis que está em casa de Maquir, filho de Amiel, em Lo-Debar.'),
('acf','2sm',9,5,'Então mandou o rei Davi, e o tomou da casa de Maquir, filho de Amiel, de Lo-Debar.'),
('acf','2sm',9,6,'E Mefibosete, filho de Jônatas, o filho de Saul, veio a Davi, e se prostrou com o rosto por terra e inclinou-se; e disse Davi: Mefibosete! E ele disse: Eis aqui teu servo.'),
('acf','2sm',9,7,'E disse-lhe Davi: Não temas, porque decerto usarei contigo de benevolência por amor de Jônatas, teu pai, e te restituirei todas as terras de Saul, teu pai, e tu sempre comerás pão à minha mesa.'),
('acf','2sm',9,8,'Então se inclinou, e disse: Quem é teu servo, para teres olhado para um cão morto tal como eu?'),
('acf','2sm',9,9,'Então chamou Davi a Ziba, moço de Saul, e disse-lhe: Tudo o que pertencia a Saul, e a toda a sua casa, tenho dado ao filho de teu senhor.'),
('acf','2sm',9,10,'Trabalhar-lhe-ás, pois, a terra, tu e teus filhos, e teus servos, e recolherás os frutos, para que o filho de teu senhor tenha pão para comer; mas Mefibosete, filho de teu senhor, sempre comerá pão à minha mesa. E tinha Ziba quinze filhos e vinte servos.'),
('acf','2sm',9,11,'E disse Ziba ao rei: Conforme a tudo quanto meu senhor, o rei, manda a seu servo, assim fará teu servo. Quanto a Mefibosete, disse o rei, comerá à minha mesa como um dos filhos do rei.'),
('acf','2sm',9,12,'E tinha Mefibosete um filho pequeno, cujo nome era Mica; e todos quantos moravam em casa de Ziba eram servos de Mefibosete.'),
('acf','2sm',9,13,'Morava, pois, Mefibosete em Jerusalém, porquanto sempre comia à mesa do rei, e era coxo de ambos os pés.'),
('acf','2sm',10,1,'E aconteceu depois disto que morreu o rei dos filhos de Amom, e seu filho Hanum reinou em seu lugar.'),
('acf','2sm',10,2,'Então disse Davi: Usarei de benevolência com Hanum, filho de Naás, como seu pai usou de benevolência comigo. E enviou Davi os seus servos para consolá-lo acerca de seu pai; e foram os servos de Davi à terra dos filhos de Amom.'),
('acf','2sm',10,3,'Então disseram os príncipes dos filhos de Amom a seu senhor, Hanum: Porventura honra Davi a teu pai aos teus olhos, porque te enviou consoladores? Não te enviou antes Davi os seus servos para reconhecerem esta cidade, e para espiá-la, e para transtorná-la?'),
('acf','2sm',10,4,'Então tomou Hanum os servos de Davi, e lhes raspou metade da barba, e lhes cortou metade das vestes, até às nádegas, e os despediu.'),
('acf','2sm',10,5,'Quando isso foi informado a Davi, enviou ele mensageiros a encontrá-los, porque estavam aqueles homens sobremaneira envergonhados. Mandou o rei dizer-lhes: Deixai-vos estar em Jericó, até que vos torne a crescer a barba, e então voltai.'),
('acf','2sm',10,6,'Vendo, pois, os filhos de Amom que se tinham feito abomináveis para com Davi, enviaram os filhos de Amom, e alugaram dos sírios de Bete-Reobe e dos sírios de Zobá vinte mil homens de pé, e do rei de Maaca mil homens e dos homens de Tobe doze mil homens.'),
('acf','2sm',10,7,'E ouvindo Davi, enviou a Joabe e a todo o exército dos valentes.'),
('acf','2sm',10,8,'E saíram os filhos de Amom, e ordenaram a batalha à entrada da porta; mas os sírios de Zobá e Reobe, e os homens de Tobe e Maaca estavam à parte no campo.'),
('acf','2sm',10,9,'Vendo, pois, Joabe que a batalha estava preparada contra ele pela frente e pela retaguarda, escolheu dentre todos os homens de Israel, e formou-os em linha contra os sírios.'),
('acf','2sm',10,10,'E o restante do povo entregou na mão de Abisai seu irmão, o qual formou em linha contra os filhos de Amom.'),
('acf','2sm',10,11,'E disse: Se os sírios forem mais fortes do que eu, tu me virás em socorro; e, se os filhos de Amom forem mais fortes do que tu, irei a socorrer-te.'),
('acf','2sm',10,12,'Esforça-te, pois, e esforcemo-nos pelo nosso povo, e pelas cidades de nosso Deus; e faça o Senhor o que bem parecer aos seus olhos.'),
('acf','2sm',10,13,'Então se achegou Joabe, e o povo que estava com ele, à peleja contra os sírios; e fugiram de diante dele.'),
('acf','2sm',10,14,'E, vendo os filhos de Amom que os sírios fugiam, também eles fugiram de diante de Abisai, e entraram na cidade; e voltou Joabe dos filhos de Amom, e veio para Jerusalém.'),
('acf','2sm',10,15,'Vendo, pois, os sírios que foram feridos diante de Israel, tornaram a refazer-se.'),
('acf','2sm',10,16,'E mandou Hadadezer, e fez sair os sírios que estavam do outro lado do rio, e vieram a Helã; e Sobaque, capitão do exército de Hadadezer, marchava diante deles.'),
('acf','2sm',10,17,'Do que informado Davi, ajuntou a todo o Israel, e passou o Jordão, e foi a Helã; e os sírios se puseram em ordem contra Davi, e pelejaram com ele.'),
('acf','2sm',10,18,'Porém os sírios fugiram de diante de Israel, e Davi feriu dentre os sírios aos homens de setecentos carros, e quarenta mil homens de cavalaria; feriu também a Sobaque, capitão do exército, que morreu ali.'),
('acf','2sm',10,19,'Vendo, pois, todos os reis, servos de Hadadezer, que foram feridos diante de Israel, fizeram paz com Israel, e o serviram; e temeram os sírios de socorrer aos filhos de Amom.'),
('acf','2sm',11,1,'E aconteceu que, tendo decorrido um ano, no tempo em que os reis saem à guerra, enviou Davi a Joabe, e com ele os seus servos, e a todo o Israel; e eles destruíram os filhos de Amom, e cercaram a Rabá; porém Davi ficou em Jerusalém.'),
('acf','2sm',11,2,'E aconteceu que numa tarde Davi se levantou do seu leito, e andava passeando no terraço da casa real, e viu do terraço a uma mulher que se estava lavando; e era esta mulher mui formosa à vista.'),
('acf','2sm',11,3,'E mandou Davi indagar quem era aquela mulher; e disseram: Porventura não é esta Bate-Seba, filha de Eliã, mulher de Urias, o heteu?'),
('acf','2sm',11,4,'Então enviou Davi mensageiros, e mandou trazê-la; e ela veio, e ele se deitou com ela (pois já estava purificada da sua imundícia); então voltou ela para sua casa.'),
('acf','2sm',11,5,'E a mulher concebeu; e mandou dizer a Davi: Estou grávida.'),
('acf','2sm',11,6,'Então Davi mandou dizer a Joabe: Envia-me Urias, o heteu. E Joabe enviou Urias a Davi.'),
('acf','2sm',11,7,'Vindo, pois, Urias a ele, perguntou Davi como passava Joabe, e como estava o povo, e como ia a guerra.'),
('acf','2sm',11,8,'Depois disse Davi a Urias: Desce à tua casa, e lava os teus pés. E, saindo Urias da casa real, logo lhe foi mandado um presente da mesa do rei.'),
('acf','2sm',11,9,'Porém Urias se deitou à porta da casa real, com todos os servos do seu senhor; e não desceu à sua casa.'),
('acf','2sm',11,10,'E fizeram saber isto a Davi, dizendo: Urias não desceu a sua casa. Então disse Davi à Urias: Não vens tu duma jornada? Por que não desceste à tua casa?'),
('acf','2sm',11,11,'E disse Urias a Davi: A arca, e Israel, e Judá ficaram em tendas; e Joabe, meu senhor, e os servos de meu senhor estão acampados no campo; e hei de eu entrar na minha casa, para comer e beber, e para me deitar com minha mulher? Pela tua vida, e pela vida da tua alma, não farei tal coisa.'),
('acf','2sm',11,12,'Então disse Davi a Urias: Demora-te aqui ainda hoje, e amanhã te despedirei. Urias, pois, ficou em Jerusalém aquele dia e o seguinte.'),
('acf','2sm',11,13,'E Davi o convidou, e comeu e bebeu diante dele, e o embebedou; e à tarde saiu a deitar-se na sua cama com os servos de seu senhor; porém não desceu à sua casa.'),
('acf','2sm',11,14,'E sucedeu que pela manhã Davi escreveu uma carta a Joabe; e mandou-lha por mão de Urias.'),
('acf','2sm',11,15,'Escreveu na carta, dizendo: Ponde a Urias na frente da maior força da peleja; e retirai-vos de detrás dele, para que seja ferido e morra.'),
('acf','2sm',11,16,'Aconteceu, pois, que, tendo Joabe observado bem a cidade, pôs a Urias no lugar onde sabia que havia homens valentes.'),
('acf','2sm',11,17,'E, saindo os homens da cidade, e pelejando com Joabe, caíram alguns do povo, dos servos de Davi; e morreu também Urias, o heteu.'),
('acf','2sm',11,18,'Então enviou Joabe, e fez saber a Davi todo o sucesso daquela peleja.'),
('acf','2sm',11,19,'E deu ordem ao mensageiro, dizendo: Acabando tu de contar ao rei todo o sucesso desta peleja,'),
('acf','2sm',11,20,'E sucedendo que o rei se encolerize, e te diga: Por que vos chegastes tão perto da cidade a pelejar? Não sabíeis vós que haviam de atirar do muro?'),
('acf','2sm',11,21,'Quem feriu a Abimeleque, filho de Jerubesete? Não lançou uma mulher sobre ele do muro um pedaço de uma mó corredora, de que morreu em Tebes? Por que vos chegastes ao muro? Então dirás: Também morreu teu servo Urias, o heteu.'),
('acf','2sm',11,22,'E foi o mensageiro, e entrou, e fez saber a Davi tudo o que Joabe o enviara a dizer.'),
('acf','2sm',11,23,'E disse o mensageiro a Davi: Na verdade que mais poderosos foram aqueles homens do que nós, e saíram a nós ao campo; porém nós fomos contra eles, até à entrada da porta.'),
('acf','2sm',11,24,'Então os flecheiros atiraram contra os teus servos desde o alto do muro, e morreram alguns dos servos do rei; e também morreu o teu servo Urias, o heteu.'),
('acf','2sm',11,25,'E disse Davi ao mensageiro: Assim dirás a Joabe: Não te pareça isto mal aos teus olhos; pois a espada tanto consome este como aquele; esforça a tua peleja contra a cidade, e a derrota; esforça-o tu assim.'),
('acf','2sm',11,26,'Ouvindo, pois, a mulher de Urias que seu marido era morto, lamentou a seu senhor.'),
('acf','2sm',11,27,'E, passado o luto, enviou Davi, e a recolheu em sua casa, e lhe foi por mulher, e deu-lhe à luz um filho. Porém esta coisa que Davi fez pareceu mal aos olhos do Senhor.'),
('acf','2sm',12,1,'E o SENHOR enviou Natã a Davi; e, apresentando-se ele a Davi, disse-lhe: Havia numa cidade dois homens, um rico e outro pobre.'),
('acf','2sm',12,2,'O rico possuía muitíssimas ovelhas e vacas.'),
('acf','2sm',12,3,'Mas o pobre não tinha coisa nenhuma, senão uma pequena cordeira que comprara e criara; e ela tinha crescido com ele e com seus filhos; do seu bocado comia, e do seu copo bebia, e dormia em seu regaço, e a tinha como filha.'),
('acf','2sm',12,4,'E, vindo um viajante ao homem rico, deixou este de tomar das suas ovelhas e das suas vacas para assar para o viajante que viera a ele; e tomou a cordeira do homem pobre, e a preparou para o homem que viera a ele.'),
('acf','2sm',12,5,'Então o furor de Davi se acendeu em grande maneira contra aquele homem, e disse a Natã: Vive o Senhor, que digno de morte é o homem que fez isso.'),
('acf','2sm',12,6,'E pela cordeira tornará a dar o quadruplicado, porque fez tal coisa, e porque não se compadeceu.'),
('acf','2sm',12,7,'Então disse Natã a Davi: Tu és este homem. Assim diz o Senhor Deus de Israel: Eu te ungi rei sobre Israel, e eu te livrei das mãos de Saul;'),
('acf','2sm',12,8,'E te dei a casa de teu senhor, e as mulheres de teu senhor em teu seio, e também te dei a casa de Israel e de Judá, e, se isto é pouco, mais te acrescentaria tais e tais coisas.'),
('acf','2sm',12,9,'Por que, pois, desprezaste a palavra do Senhor, fazendo o mal diante de seus olhos? A Urias, o heteu, feriste à espada, e a sua mulher tomaste por tua mulher; e a ele mataste com a espada dos filhos de Amom.'),
('acf','2sm',12,10,'Agora, pois, não se apartará a espada jamais da tua casa, porquanto me desprezaste, e tomaste a mulher de Urias, o heteu, para ser tua mulher.'),
('acf','2sm',12,11,'Assim diz o Senhor: Eis que suscitarei da tua própria casa o mal sobre ti, e tomarei tuas mulheres perante os teus olhos, e as darei a teu próximo, o qual se deitará com tuas mulheres perante este sol.'),
('acf','2sm',12,12,'Porque tu o fizeste em oculto, mas eu farei este negócio perante todo o Israel e perante o sol.'),
('acf','2sm',12,13,'Então disse Davi a Natã: Pequei contra o Senhor. E disse Natã a Davi: Também o Senhor perdoou o teu pecado; não morrerás.'),
('acf','2sm',12,14,'Todavia, porquanto com este feito deste lugar sobremaneira a que os inimigos do Senhor blasfemem, também o filho que te nasceu certamente morrerá.'),
('acf','2sm',12,15,'Então Natã foi para sua casa; e o Senhor feriu a criança que a mulher de Urias dera a Davi, e adoeceu gravemente.'),
('acf','2sm',12,16,'E buscou Davi a Deus pela criança; e jejuou Davi, e entrou, e passou a noite prostrado sobre a terra.'),
('acf','2sm',12,17,'Então os anciãos da sua casa se levantaram e foram a ele, para o levantar da terra; porém ele não quis, e não comeu pão com eles.'),
('acf','2sm',12,18,'E sucedeu que ao sétimo dia morreu a criança; e temiam os servos de Davi dizer-lhe que a criança estava morta, porque diziam: Eis que, sendo a criança ainda viva, lhe falávamos, porém não dava ouvidos à nossa voz; como, pois, lhe diremos que a criança está morta? Porque mais lhe afligiria.'),
('acf','2sm',12,19,'Viu, porém, Davi que seus servos falavam baixo, e entendeu Davi que a criança estava morta, pelo que disse Davi a seus servos: Está morta a criança? E eles disseram: Está morta.'),
('acf','2sm',12,20,'Então Davi se levantou da terra, e se lavou, e se ungiu, e mudou de roupas, e entrou na casa do Senhor, e adorou. Então foi à sua casa, e pediu pão; e lhe puseram pão, e comeu.'),
('acf','2sm',12,21,'E disseram-lhe seus servos: Que é isto que fizeste? Pela criança viva jejuaste e choraste; porém depois que morreu a criança te levantaste e comeste pão.'),
('acf','2sm',12,22,'E disse ele: Vivendo ainda a criança, jejuei e chorei, porque dizia: Quem sabe se DEUS se compadecerá de mim, e viverá a criança?'),
('acf','2sm',12,23,'Porém, agora que está morta, por que jejuaria eu? Poderei eu fazê-la voltar? Eu irei a ela, porém ela não voltará para mim.'),
('acf','2sm',12,24,'Então consolou Davi a Bate-Seba, sua mulher, e entrou a ela, e se deitou com ela, e ela deu à luz um filho, e deu-lhe o nome de Salomão; e o Senhor o amou.'),
('acf','2sm',12,25,'E enviou pela mão do profeta Natã, dando-lhe o nome de Jedidias, por amor ao Senhor.'),
('acf','2sm',12,26,'Ora pelejou Joabe contra Rabá, dos filhos de Amom, e tomou a cidade real.'),
('acf','2sm',12,27,'Então mandou Joabe mensageiros a Davi, e disse: Pelejei contra Rabá, e também tomei a cidade das águas.'),
('acf','2sm',12,28,'Ajunta, pois, agora o restante do povo, e cerca a cidade, e toma-a, para que tomando eu a cidade, não se aclame sobre ela o meu nome.'),
('acf','2sm',12,29,'Então ajuntou Davi a todo o povo, e marchou para Rabá, e pelejou contra ela, e a tomou.'),
('acf','2sm',12,30,'E tirou a coroa da cabeça do seu rei, cujo peso era de um talento de ouro, e havia nela pedras preciosas, e foi posta sobre a cabeça de Davi; e da cidade levou mui grande despojo.'),
('acf','2sm',12,31,'E, trazendo o povo que havia nela, o pôs às serras, e às talhadeiras de ferro, e aos machados de ferro, e os fez passar por forno de tijolos; e assim fez a todas as cidades dos filhos de Amom; e voltou Davi e todo o povo para Jerusalém.'),
('acf','2sm',13,1,'E aconteceu depois disto que, tendo Absalão, filho de Davi, uma irmã formosa, cujo nome era Tamar, Amnom, filho de Davi, amou-a.'),
('acf','2sm',13,2,'E angustiou-se Amnom, até adoecer, por Tamar, sua irmã, porque era virgem; e parecia aos olhos de Amnom dificultoso fazer-lhe coisa alguma.'),
('acf','2sm',13,3,'Tinha, porém, Amnom um amigo, cujo nome era Jonadabe, filho de Siméia, irmão de Davi; e era Jonadabe homem mui sagaz.'),
('acf','2sm',13,4,'O qual lhe disse: Por que tu de dia em dia tanto emagreces, sendo filho do rei? Não mo farás saber a mim? Então lhe disse Amnom: Amo a Tamar, irmã de Absalão, meu irmão.'),
('acf','2sm',13,5,'E Jonadabe lhe disse: Deita-te na tua cama, e finge-te doente; e, quando teu pai te vier visitar, dize-lhe: Peço-te que minha irmã Tamar venha, e me dê de comer pão, e prepare a comida diante dos meus olhos, para que eu a veja e coma da sua mão.'),
('acf','2sm',13,6,'Deitou-se, pois, Amnom, e fingiu-se doente; e, vindo o rei visitá-lo, disse Amnom, ao rei: Peço-te que minha irmã Tamar venha, e prepare dois bolos diante dos meus olhos, para que eu coma de sua mão.'),
('acf','2sm',13,7,'Mandou então Davi à casa, a Tamar, dizendo: Vai à casa de Amnom, teu irmão, e faze-lhe alguma comida.'),
('acf','2sm',13,8,'E foi Tamar à casa de Amnom, seu irmão (ele porém estava deitado), e tomou massa, e a amassou, e fez bolos diante dos seus olhos, e cozeu os bolos.'),
('acf','2sm',13,9,'E tomou a frigideira, e os tirou diante dele; porém ele recusou comer. E disse Amnom: Fazei retirar a todos da minha presença. E todos se retiraram dele.'),
('acf','2sm',13,10,'Então disse Amnom a Tamar: Traze a comida ao quarto, e comerei da tua mão. E tomou Tamar os bolos que fizera, e levou-os a Amnom, seu irmão, no quarto.'),
('acf','2sm',13,11,'E chegando-lhos, para que comesse, pegou dela, e disse-lhe: Vem, deita-te comigo, minha irmã.'),
('acf','2sm',13,12,'Porém ela lhe disse: Não, meu irmão, não me forces, porque não se faz assim em Israel; não faças tal loucura.'),
('acf','2sm',13,13,'Porque, aonde iria eu com a minha vergonha? E tu serias como um dos loucos de Israel. Agora, pois, peço-te que fales ao rei, porque não me negará a ti.'),
('acf','2sm',13,14,'Porém ele não quis dar ouvidos à sua voz; antes, sendo mais forte do que ela, a forçou, e se deitou com ela.'),
('acf','2sm',13,15,'Depois Amnom sentiu grande aversão por ela, pois maior era o ódio que sentiu por ela do que o amor com que a amara. E disse-lhe Amnom: Levanta-te, e vai-te.'),
('acf','2sm',13,16,'Então ela lhe disse: Não há razão de me despedires assim; maior seria este mal do que o outro que já me tens feito. Porém não lhe quis dar ouvidos.'),
('acf','2sm',13,17,'E chamou a seu moço que o servia, e disse: Ponha fora a esta, e fecha a porta após ela.'),
('acf','2sm',13,18,'E trazia ela uma roupa de muitas cores (porque assim se vestiam as filhas virgens dos reis); e seu servo a pôs para fora, e fechou a porta após ela.'),
('acf','2sm',13,19,'Então Tamar tomou cinza sobre a sua cabeça, e a roupa de muitas cores que trazia rasgou; e pôs as mãos sobre a cabeça, e foi andando e clamando.'),
('acf','2sm',13,20,'E Absalão, seu irmão, lhe disse: Esteve Amnom, teu irmão, contigo? Ora, pois, minha irmã, cala-te; é teu irmão. Não se angustie o teu coração por isto. Assim ficou Tamar, e esteve solitária em casa de Absalão seu irmão.'),
('acf','2sm',13,21,'E, ouvindo o rei Davi todas estas coisas, muito se lhe acendeu a ira.'),
('acf','2sm',13,22,'Porém Absalão não falou com Amnom, nem mal nem bem; porque Absalão odiava a Amnom, por ter forçado a Tamar sua irmã.'),
('acf','2sm',13,23,'E aconteceu que, passados dois anos inteiros, Absalão tinha tosquiadores em Baal-Hazor, que está junto a Efraim; e convidou Absalão a todos os filhos do rei.'),
('acf','2sm',13,24,'E foi Absalão ao rei, e disse: Eis que teu servo tem tosquiadores; peço que o rei e os seus servos venham com o teu servo.'),
('acf','2sm',13,25,'O rei, porém, disse a Absalão: Não, filho meu, não vamos todos juntos, para não te sermos pesados. E instou com ele; porém não quis ir, mas o abençoou.'),
('acf','2sm',13,26,'Então disse Absalão: Quando não, deixa ir conosco Amnom, meu irmão. Porém o rei disse: Para que iria contigo?'),
('acf','2sm',13,27,'E, instando Absalão com ele, deixou ir com ele a Amnom, e a todos os filhos do rei.'),
('acf','2sm',13,28,'E Absalão deu ordem aos seus servos, dizendo: Tomai sentido; quando o coração de Amnom estiver alegre do vinho, e eu vos disser: Feri a Amnom, então o matareis; não temais: porque porventura não sou eu quem vo-lo ordenei? Esforçai-vos, e sede valentes.'),
('acf','2sm',13,29,'E os servos de Absalão fizeram a Amnom como Absalão lho havia ordenado. Então todos os filhos do rei se levantaram, e montaram cada um no seu mulo, e fugiram.'),
('acf','2sm',13,30,'E aconteceu que, estando eles ainda no caminho, chegou a nova a Davi, dizendo-se: Absalão feriu a todos os filhos do rei, e nenhum deles ficou.'),
('acf','2sm',13,31,'Então o rei se levantou, e rasgou as suas vestes, e se lançou por terra; da mesma maneira todos os seus servos estavam com vestes rotas.'),
('acf','2sm',13,32,'Mas Jonadabe, filho de Siméia, irmão de Davi, respondeu, e disse: Não diga o meu senhor que mataram a todos os moços filhos do rei, porque só morreu Amnom; porque assim tinha resolvido fazer Absalão, desde o dia em que forçou a Tamar sua irmã.'),
('acf','2sm',13,33,'Não se lhe ponha, pois, agora no coração do rei meu senhor tal coisa, dizendo: Morreram todos os filhos do rei; porque só morreu Amnom.'),
('acf','2sm',13,34,'E Absalão fugiu; e o moço que estava de guarda, levantou os seus olhos, e olhou; e eis que muito povo vinha pelo caminho por detrás dele, pelo lado do monte.'),
('acf','2sm',13,35,'Então disse Jonadabe ao rei: Eis aqui vêm os filhos do rei; conforme à palavra de teu servo, assim sucedeu.'),
('acf','2sm',13,36,'E aconteceu que, como acabou de falar, os filhos do rei vieram, e levantaram a sua voz, e choraram; e também o rei e todos os seus servos choraram amargamente.'),
('acf','2sm',13,37,'Assim Absalão fugiu, e foi a Talmai, filho de Amiur, rei de Gesur. E Davi pranteava por seu filho todos aqueles dias.'),
('acf','2sm',13,38,'Assim Absalão fugiu, e foi para Gesur; esteve ali três anos.'),
('acf','2sm',13,39,'Então tinha o rei Davi saudades de Absalão; porque já se tinha consolado acerca da morte de Amnom.'),
('acf','2sm',14,1,'Conhecendo, pois, Joabe, filho de Zeruia, que o coração do rei estava inclinado para Absalão,'),
('acf','2sm',14,2,'Enviou Joabe a Tecoa, e tomou de lá uma mulher e disse-lhe: Ora, finge que estás de luto; veste roupas de luto, e não te unjas com óleo, e sê como uma mulher que há já muitos dias está de luto por algum morto.'),
('acf','2sm',14,3,'E vai ao rei, e fala-lhe conforme a esta palavra. E Joabe lhe pôs as palavras na boca.'),
('acf','2sm',14,4,'E a mulher tecoíta falou ao rei, e, deitando-se com o rosto em terra, se prostrou e disse: Salva-me, ó rei.'),
('acf','2sm',14,5,'E disse-lhe o rei: Que tens? E disse ela: Na verdade sou mulher viúva; morreu meu marido.'),
('acf','2sm',14,6,'Tinha, pois, a tua serva dois filhos, e estes brigaram entre si no campo, e não houve quem os apartasse; assim um feriu ao outro, e o matou.'),
('acf','2sm',14,7,'E eis que toda a linhagem se levantou contra a tua serva, e disseram: Dá-nos aquele que feriu a seu irmão, para que o matemos, por causa da vida de seu irmão, a quem matou, e para que destruamos também ao herdeiro. Assim apagarão a brasa que me ficou, de sorte que não deixam a meu marido nome, nem remanescente sobre a terra.'),
('acf','2sm',14,8,'E disse o rei à mulher: Vai para tua casa; e eu mandarei ordem acerca de ti.'),
('acf','2sm',14,9,'E disse a mulher tecoíta ao rei: A injustiça, rei meu senhor, venha sobre mim e sobre a casa de meu pai; e o rei e o seu trono fique inculpável.'),
('acf','2sm',14,10,'E disse o rei: Quem falar contra ti, traze-mo a mim; e nunca mais te tocará.'),
('acf','2sm',14,11,'E disse ela: Ora, lembre-se o rei do Senhor seu Deus, para que os vingadores do sangue não prossigam na destruição, e não exterminem a meu filho. Então disse ele: Vive o Senhor, que não há de cair no chão nem um dos cabelos de teu filho.'),
('acf','2sm',14,12,'Então disse a mulher: Peço-te que a tua serva fale uma palavra ao rei meu senhor. E disse ele: Fala.'),
('acf','2sm',14,13,'E disse a mulher: Por que, pois, pensaste tu uma tal coisa contra o povo de Deus? Porque, falando o rei tal palavra, fica como culpado; visto que o rei não torna a trazer o seu desterrado.'),
('acf','2sm',14,14,'Porque certamente morreremos, e seremos como águas derramadas na terra que não se ajuntam mais; Deus, pois, lhe não tirará a vida, mas cogita meios, para que não fique banido dele o seu desterrado.'),
('acf','2sm',14,15,'E se eu agora vim falar esta palavra ao rei, meu senhor, é porque o povo me atemorizou; dizia, pois, a tua serva: Falarei, pois, ao rei; porventura fará o rei segundo a palavra da sua serva.'),
('acf','2sm',14,16,'Porque o rei ouvirá, para livrar a sua serva da mão do homem que intenta destruir juntamente a mim e a meu filho da herança de Deus.'),
('acf','2sm',14,17,'Dizia mais a tua serva: Seja agora a palavra do rei meu senhor para descanso; porque como um anjo de Deus, assim é o rei, meu senhor, para ouvir o bem e o mal; e o SENHOR teu Deus será contigo.'),
('acf','2sm',14,18,'Então respondeu o rei, e disse à mulher: Peço-te que não me encubras o que eu te perguntar. E disse a mulher: Ora fale o rei, meu senhor.'),
('acf','2sm',14,19,'E disse o rei: Não é verdade que a mão de Joabe anda contigo em tudo isto? E respondeu a mulher, e disse: Vive a tua alma, ó rei meu senhor, que ninguém se poderá desviar, nem para a direita nem para a esquerda, de tudo quanto o rei, meu senhor, tem falado: Porque Joabe, teu servo, é quem me deu ordem, e foi ele que pôs na boca da tua serva todas estas palavras:'),
('acf','2sm',14,20,'Para mudar o aspecto deste caso foi que o teu servo Joabe fez isto; porém sábio é meu senhor, conforme à sabedoria de um anjo de Deus, para entender tudo o que há na terra.'),
('acf','2sm',14,21,'Então o rei disse a Joabe: Eis que fiz isto; vai, pois, e torna a trazer o jovem Absalão.'),
('acf','2sm',14,22,'Então Joabe se prostrou sobre o seu rosto em terra, e se inclinou, e agradeceu ao rei; e disse Joabe: Hoje conhece o teu servo que achei graça aos teus olhos, ó rei meu senhor, porque o rei fez segundo a palavra do teu servo.'),
('acf','2sm',14,23,'Levantou-se, pois, Joabe, e foi a Gesur, e trouxe Absalão a Jerusalém.'),
('acf','2sm',14,24,'E disse o rei: Torne para a sua casa, e não veja a minha face. Tornou, pois, Absalão para sua casa, e não viu a face do rei.'),
('acf','2sm',14,25,'Não havia, porém, em todo o Israel homem tão belo e tão aprazível como Absalão; desde a planta do pé até à cabeça não havia nele defeito algum.'),
('acf','2sm',14,26,'E, quando tosquiava a sua cabeça (e sucedia que no fim de cada ano a tosquiava, porquanto muito lhe pesava, e por isso a tosquiava), pesava o cabelo da sua cabeça duzentos siclos, segundo o peso real.'),
('acf','2sm',14,27,'Também nasceram a Absalão três filhos e uma filha, cujo nome era Tamar; e esta era mulher formosa à vista.'),
('acf','2sm',14,28,'Assim ficou Absalão dois anos inteiros em Jerusalém, e não viu a face do rei.'),
('acf','2sm',14,29,'Mandou, pois, Absalão chamar a Joabe, para o enviar ao rei; porém não quis vir a ele; e enviou ainda segunda vez e, contudo, não quis vir.'),
('acf','2sm',14,30,'Então disse aos seus servos: Vedes ali o pedaço de campo de Joabe pegado ao meu, e tem cevada nele; ide, e ponde-lhe fogo. E os servos de Absalão puseram fogo ao pedaço de campo.'),
('acf','2sm',14,31,'Então Joabe se levantou, e veio a Absalão, em casa, e disse-lhe: Por que puseram os teus servos fogo ao pedaço de campo que é meu?'),
('acf','2sm',14,32,'E disse Absalão a Joabe: Eis que enviei a ti, dizendo: Vem cá, para que te envie ao rei, a dizer-lhe: Para que vim de Gesur? Melhor me fora estar ainda lá. Agora, pois, veja eu a face do rei; e, se há ainda em mim alguma culpa, que me mate.'),
('acf','2sm',14,33,'Então foi Joabe ao rei, e assim lho disse. Então chamou a Absalão, e ele se apresentou ao rei, e se inclinou sobre o seu rosto em terra diante do rei; e o rei beijou a Absalão.'),
('acf','2sm',15,1,'E aconteceu depois disto que Absalão fez aparelhar carros e cavalos, e cinqüenta homens que corressem adiante dele.'),
('acf','2sm',15,2,'Também Absalão se levantou pela manhã, e parava a um lado do caminho da porta. E sucedia que a todo o homem que tinha alguma demanda para vir ao rei a juízo, o chamava Absalão a si, e lhe dizia: De que cidade és tu? E, dizendo ele: De uma das tribos de Israel é teu servo;'),
('acf','2sm',15,3,'Então Absalão lhe dizia: Olha, os teus negócios são bons e retos, porém não tens quem te ouça da parte do rei.'),
('acf','2sm',15,4,'Dizia mais Absalão: Ah, quem me dera ser juiz na terra, para que viesse a mim todo o homem que tivesse demanda ou questão, para que lhe fizesse justiça!'),
('acf','2sm',15,5,'Sucedia também que, quando alguém se chegava a ele para se inclinar diante dele, ele estendia a sua mão, e pegava dele, e o beijava.'),
('acf','2sm',15,6,'E desta maneira fazia Absalão a todo o Israel que vinha ao rei para juízo; assim furtava Absalão o coração dos homens de Israel.'),
('acf','2sm',15,7,'Aconteceu, pois, ao cabo de quarenta anos, que Absalão disse ao rei: Deixa-me ir pagar em Hebrom o meu voto que fiz ao Senhor.'),
('acf','2sm',15,8,'Porque, morando eu em Gesur, na Síria, fez o teu servo um voto, dizendo: Se o Senhor outra vez me fizer tornar a Jerusalém, servirei ao Senhor.'),
('acf','2sm',15,9,'Então lhe disse o rei: Vai em paz. Levantou-se, pois, e foi para Hebrom.'),
('acf','2sm',15,10,'E enviou Absalão espias por todas as tribos de Israel, dizendo: Quando ouvirdes o som das trombetas, direis: Absalão reina em Hebrom.'),
('acf','2sm',15,11,'E de Jerusalém foram com Absalão duzentos homens convidados, porém iam na sua simplicidade, porque nada sabiam daquele negócio.'),
('acf','2sm',15,12,'Também Absalão mandou vir Aitofel, o gilonita, do conselho de Davi, à sua cidade de Giló, estando ele oferecendo os seus sacrifícios; e a conjuração se fortificava, e vinha o povo, e ia crescendo com Absalão.'),
('acf','2sm',15,13,'Então veio um mensageiro a Davi, dizendo: O coração de cada um em Israel segue a Absalão.'),
('acf','2sm',15,14,'Disse, pois, Davi a todos os seus servos que estavam com ele em Jerusalém: Levantai-vos, e fujamos, porque não poderíamos escapar diante de Absalão. Dai-vos pressa a caminhar, para que porventura não se apresse ele, e nos alcance, e lance sobre nós algum mal, e fira a cidade a fio de espada.'),
('acf','2sm',15,15,'Então os servos do rei disseram ao rei: Eis aqui os teus servos, para tudo quanto determinar o rei, nosso senhor.'),
('acf','2sm',15,16,'E saiu o rei, com toda a sua casa, a pé; deixou, porém, o rei dez mulheres concubinas, para guardarem a casa.'),
('acf','2sm',15,17,'Tendo, pois, saído o rei com todo o povo a pé, pararam num lugar distante.'),
('acf','2sm',15,18,'E todos os seus servos iam a seu lado, como também todos os quereteus e todos os peleteus; e todos os giteus, seiscentos homens que vieram de Gate a pé, caminhavam diante do rei.'),
('acf','2sm',15,19,'Disse, pois, o rei a Itai, o giteu: Por que irias tu também conosco? Volta-te, e fica-te com o rei, porque és estrangeiro, e também desterrado de teu lugar.'),
('acf','2sm',15,20,'Ontem vieste, e te levaria eu hoje conosco a caminhar? Pois eu vou para onde puder ir; volta, pois, e torna a levar teus irmãos contigo, com beneficência e fidelidade.'),
('acf','2sm',15,21,'Respondeu, porém, Itai ao rei, e disse: Vive o SENHOR, e vive o rei meu senhor, que no lugar em que estiver o rei meu senhor, seja para morte seja para vida, aí certamente estará também o teu servidor.'),
('acf','2sm',15,22,'Então Davi disse a Itai: Vem, pois, e passa adiante. Assim passou Itai, o giteu, e todos os seus homens, e todas as crianças que havia com ele.'),
('acf','2sm',15,23,'E toda a terra chorava a grandes vozes, passando todo o povo; também o rei passou o ribeiro de Cedrom, e passou todo o povo na direção do caminho do deserto.'),
('acf','2sm',15,24,'Eis que também Zadoque ali estava, e com ele todos os levitas que levavam a arca da aliança de Deus; e puseram ali a arca de Deus, e subiu Abiatar, até que todo o povo acabou de passar da cidade.'),
('acf','2sm',15,25,'Então disse o rei a Zadoque: Torna a levar a arca de Deus à cidade; que, se achar graça nos olhos do Senhor, ele me tornará a trazer para lá e me deixará ver a ela e a sua habitação.'),
('acf','2sm',15,26,'Se, porém, disser assim: Não tenho prazer em ti; eis-me aqui, faça de mim como parecer bem aos seus olhos.'),
('acf','2sm',15,27,'Disse mais o rei a Zadoque, o sacerdote: Não és tu porventura vidente? Torna, pois, em paz para a cidade, e convosco também vossos dois filhos, Aimaás, teu filho, e Jônatas, filho de Abiatar.'),
('acf','2sm',15,28,'Olhai que me demorarei nas campinas do deserto até que tenha notícias vossas.'),
('acf','2sm',15,29,'Zadoque, pois, e Abiatar, tornaram a levar para Jerusalém a arca de Deus; e ficaram ali.'),
('acf','2sm',15,30,'E seguiu Davi pela encosta do monte das Oliveiras, subindo e chorando, e com a cabeça coberta; e caminhava com os pés descalços; e todo o povo que ia com ele cobria cada um a sua cabeça, e subiam chorando sem cessar.'),
('acf','2sm',15,31,'Então fizeram saber a Davi, dizendo: Também Aitofel está entre os que se conjuraram com Absalão. Pelo que disse Davi: Ó Senhor, peço-te que torne em loucura o conselho de Aitofel.'),
('acf','2sm',15,32,'E aconteceu que, chegando Davi ao cume, para adorar ali a Deus, eis que Husai, o arquita, veio encontrar-se com ele com a roupa rasgada e terra sobre a cabeça.'),
('acf','2sm',15,33,'E disse-lhe Davi: Se passares comigo, ser-me-ás pesado.'),
('acf','2sm',15,34,'Porém se voltares para a cidade, e disseres a Absalão: Eu serei, ó rei, teu servo; bem fui antes servo de teu pai, mas agora serei teu servo; dissipar-me-ás então o conselho de Aitofel.'),
('acf','2sm',15,35,'E não estão ali contigo Zadoque e Abiatar, sacerdotes? E será que todas as coisas que ouvires da casa do rei, farás saber a Zadoque, e a Abiatar, sacerdotes.'),
('acf','2sm',15,36,'Eis que estão também ali com eles seus dois filhos, Aimaás filho de Zadoque, e Jônatas filho de Abiatar; pela mão deles aviso me mandareis, de todas as coisas que ouvirdes.'),
('acf','2sm',15,37,'Husai, pois, amigo de Davi, veio para a cidade; e Absalão entrou em Jerusalém.'),
('acf','2sm',16,1,'E passando Davi um pouco mais adiante do cume, eis que Ziba, o servo de Mefibosete, veio encontrar-se com ele, com um par de jumentos albardados, e sobre eles duzentos pães, com cem cachos de passas, e cem de frutas de verão e um odre de vinho.'),
('acf','2sm',16,2,'E disse o rei a Ziba: Que pretendes com isto? E disse Ziba: Os jumentos são para a casa do rei, para se montarem neles; e o pão e as frutas de verão para comerem os moços; e o vinho para beberem os cansados no deserto.'),
('acf','2sm',16,3,'Então disse o rei: Ora, onde está o filho de teu senhor? E disse Ziba ao rei: Eis que ficou em Jerusalém; porque disse: Hoje me restituirá a casa de Israel o reino de meu pai.'),
('acf','2sm',16,4,'Então disse o rei a Ziba: Eis que teu é tudo quanto tem Mefibosete. E disse Ziba: Eu me inclino, que eu ache graça em teus olhos, ó rei meu senhor.'),
('acf','2sm',16,5,'E, chegando o rei Davi a Baurim, eis que dali saiu um homem da linhagem da casa de Saul, cujo nome era Simei, filho de Gera, e, saindo, ia amaldiçoando.'),
('acf','2sm',16,6,'E atirava pedras contra Davi, e contra todos os servos do rei Davi; ainda que todo o povo e todos os valentes iam à sua direita e à sua esquerda.'),
('acf','2sm',16,7,'E, amaldiçoando-o Simei, assim dizia: Sai, sai, homem de sangue, e homem de Belial.'),
('acf','2sm',16,8,'O Senhor te deu agora a paga de todo o sangue da casa de Saul, em cujo lugar tens reinado; já deu o Senhor o reino na mão de Absalão teu filho; e eis-te agora na tua desgraça, porque és um homem de sangue.'),
('acf','2sm',16,9,'Então disse Abisai, filho de Zeruia, ao rei: Por que amaldiçoaria este cão morto ao rei meu senhor? Deixa-me passar, e lhe tirarei a cabeça.'),
('acf','2sm',16,10,'Disse, porém, o rei: Que tenho eu convosco, filhos de Zeruia? Ora deixai-o amaldiçoar; pois o Senhor lhe disse: Amaldiçoa a Davi; quem pois diria: Por que assim fizeste?'),
('acf','2sm',16,11,'Disse mais Davi a Abisai, e a todos os seus servos: Eis que meu filho, que saiu das minhas entranhas, procura a minha morte; quanto mais ainda este benjamita? Deixai-o, que amaldiçoe; porque o Senhor lho disse.'),
('acf','2sm',16,12,'Porventura o Senhor olhará para a minha miséria; e o Senhor me pagará com bem a sua maldição deste dia.'),
('acf','2sm',16,13,'Prosseguiram, pois, o seu caminho, Davi e os seus homens; e também Simei ia ao longo do monte, defronte dele, caminhando e amaldiçoando, e atirava pedras contra ele, e levantava poeira.'),
('acf','2sm',16,14,'E o rei e todo o povo que ia com ele chegaram cansados, e refrescaram-se ali.'),
('acf','2sm',16,15,'Absalão, pois, e todo o povo, os homens de Israel, vieram a Jerusalém; e Aitofel com ele.'),
('acf','2sm',16,16,'E sucedeu que, chegando Husai, o arquita, amigo de Davi, a Absalão, disse Husai a Absalão: Viva o rei, viva o rei!'),
('acf','2sm',16,17,'Porém Absalão disse a Husai: É esta a tua beneficência para com o teu amigo? Por que não foste com o teu amigo?'),
('acf','2sm',16,18,'E disse Husai a Absalão: Não, porém daquele que eleger o Senhor, e todo este povo, e todos os homens de Israel, dele serei e com ele ficarei.'),
('acf','2sm',16,19,'E, demais disto, a quem serviria eu? Porventura não seria diante de seu filho? Como servi diante de teu pai, assim serei diante de ti.'),
('acf','2sm',16,20,'Então disse Absalão a Aitofel: Dai conselho entre vós sobre o que devemos fazer.'),
('acf','2sm',16,21,'E disse Aitofel a Absalão: Possue as concubinas de teu pai, que deixou para guardarem a casa; e assim todo o Israel ouvirá que te fizeste aborrecível para com teu pai; e se fortalecerão as mãos de todos os que estão contigo.'),
('acf','2sm',16,22,'Estenderam, pois, para Absalão uma tenda no terraço; e Absalão possuiu as concubinas de seu pai, perante os olhos de todo o Israel.'),
('acf','2sm',16,23,'E era o conselho de Aitofel, que aconselhava naqueles dias, como se a palavra de Deus se consultara; tal era todo o conselho de Aitofel, assim para com Davi como para com Absalão.'),
('acf','2sm',17,1,'Disse mais Aitofel a Absalão: Deixa-me escolher doze mil homens, e me levantarei, e perseguirei a Davi esta noite.'),
('acf','2sm',17,2,'E irei sobre ele, pois está cansado e frouxo de mãos; e o espantarei, e fugirá todo o povo que está com ele; e então ferirei somente o rei.'),
('acf','2sm',17,3,'E farei tornar a ti todo o povo; pois o homem a quem tu buscas é como se tornassem todos; assim todo o povo estará em paz.'),
('acf','2sm',17,4,'E esta palavra pareceu boa aos olhos de Absalão, e aos olhos de todos os anciãos de Israel.'),
('acf','2sm',17,5,'Disse, porém, Absalão: Chamai agora também a Husai o arquita; e ouçamos também o que ele dirá.'),
('acf','2sm',17,6,'E, chegando Husai a Absalão, lhe falou Absalão, dizendo: Desta maneira falou Aitofel; faremos conforme à sua palavra? Se não, fala tu.'),
('acf','2sm',17,7,'Então disse Husai a Absalão: O conselho que Aitofel deu desta vez não é bom.'),
('acf','2sm',17,8,'Disse mais Husai: Bem conheces tu a teu pai, e a seus homens, que são valorosos, e que estão com o espírito amargurado, como a ursa no campo, roubada dos cachorros; e também teu pai é homem de guerra, e não passará a noite com o povo.'),
('acf','2sm',17,9,'Eis que agora estará escondido nalguma cova, ou em qualquer outro lugar; e será que, caindo no princípio alguns dentre eles, cada um que o ouvir então dirá: Houve derrota no povo que segue a Absalão.'),
('acf','2sm',17,10,'Então até o homem valente, cujo coração é como coração de leão, sem dúvida desmaiará; porque todo o Israel sabe que teu pai é valoroso, e homens valentes os que estão com ele.'),
('acf','2sm',17,11,'Eu, porém, aconselho que com toda a pressa se ajunte a ti todo o Israel desde Dã até Berseba, em multidão como a areia do mar; e tu em pessoa vás com eles à peleja.'),
('acf','2sm',17,12,'Então iremos a ele, em qualquer lugar que se achar, facilmente cairemos sobre ele, como o orvalho cai sobre a terra; e não ficará dele e de todos os homens que estão com ele nem ainda um só.'),
('acf','2sm',17,13,'E, se ele se retirar para alguma cidade, todo o Israel levará cordas àquela cidade; e arrastá-la-emos até ao ribeiro, até que não se ache ali nem uma só pedrinha.'),
('acf','2sm',17,14,'Então disse Absalão e todos os homens de Israel: Melhor é o conselho de Husai, o arquita, do que o conselho de Aitofel (porém assim o Senhor o ordenara, para aniquilar o bom conselho de Aitofel, para que o Senhor trouxesse o mal sobre Absalão).'),
('acf','2sm',17,15,'E disse Husai a Zadoque e a Abiatar, sacerdotes: assim e assim aconselhou Aitofel a Absalão e aos anciãos de Israel; porém assim e assim aconselhei eu.'),
('acf','2sm',17,16,'Agora, pois, enviai apressadamente, e avisai a Davi, dizendo: Não passes esta noite nas campinas do deserto; logo também passa ao outro lado, para que o rei e todo o povo que com ele está não seja devorado.'),
('acf','2sm',17,17,'Estavam, pois, Jônatas e Aimaás junto à fonte de Rogel; e foi uma criada, e lho disse, e eles foram e o disseram ao rei Davi, porque não podiam ser vistos entrar na cidade.'),
('acf','2sm',17,18,'Mas viu-os todavia um moço, e avisou a Absalão; porém ambos logo partiram apressadamente, e entraram em casa de um homem, em Baurim, o qual tinha um poço no seu pátio, e ali dentro desceram.'),
('acf','2sm',17,19,'E tomou a mulher a tampa, e a estendeu sobre a boca do poço, e espalhou grão descascado sobre ela; assim nada se soube.'),
('acf','2sm',17,20,'Chegando, pois, os servos de Absalão à mulher, àquela casa, disseram: Onde estão Aimaás e Jônatas? E a mulher lhes disse: Já passaram o vau das águas. E havendo-os buscado, e não os achando, voltaram para Jerusalém.'),
('acf','2sm',17,21,'E sucedeu que, depois que se retiraram, Aimaás e Jônatas saíram do poço, e foram, e anunciaram a Davi; e disseram a Davi: Levantai-vos, e passai depressa as águas, porque assim aconselhou contra vós Aitofel.'),
('acf','2sm',17,22,'Então Davi e todo o povo que com ele estava se levantou, e passaram o Jordão; e já pela luz da manhã nem ainda faltava um só que não tivesse passado o Jordão.'),
('acf','2sm',17,23,'Vendo, pois, Aitofel que se não tinha seguido o seu conselho, albardou o jumento, e levantou-se, e foi para sua casa e para a sua cidade, e deu ordem à sua casa, e se enforcou e morreu, e foi sepultado na sepultura de seu pai.'),
('acf','2sm',17,24,'E Davi foi a Maanaim; e Absalão passou o Jordão, ele e todo o homem de Israel com ele.'),
('acf','2sm',17,25,'E Absalão constituiu a Amasa em lugar de Joabe sobre o arraial; e era Amasa filho de um homem cujo nome era Itra, o israelita, o qual possuíra a Abigail, filha de Naás, irmã de Zeruia, mãe de Joabe.'),
('acf','2sm',17,26,'Israel, pois, e Absalão acamparam na terra de Gileade.'),
('acf','2sm',17,27,'E sucedeu que, chegando Davi a Maanaim, Sobi, filho de Naás, de Rabá, dos filhos de Amom, e Maquir, filho de Amiel, de Lo-Debar, e Barzilai, o gileadita, de Rogelim,'),
('acf','2sm',17,28,'Tomaram camas e bacias, e vasilhas de barro, e trigo, e cevada, e farinha, e grão torrado, e favas, e lentilhas, também torradas,'),
('acf','2sm',17,29,'E mel, e manteiga, e ovelhas, e queijos de vacas, e os trouxeram a Davi e ao povo que com ele estava, para comerem, porque disseram: Este povo no deserto está faminto, cansado e sedento.'),
('acf','2sm',18,1,'E Davi contou o povo que tinha consigo, e pôs sobre eles capitães de mil e capitães de cem.'),
('acf','2sm',18,2,'E Davi enviou o povo, um terço sob o mando de Joabe, e outro terço sob o mando de Abisai, filho de Zeruia, irmão de Joabe, e outro terço sob o mando de Itai, o giteu; e disse o rei ao povo: Eu também sairei convosco.'),
('acf','2sm',18,3,'Porém o povo disse: Não sairás, porque, se formos obrigados a fugir, não se importarão conosco; e, ainda que metade de nós morra, não farão caso de nós, porque ainda, tais como nós somos, ajuntarás dez mil; melhor será, pois, que da cidade nos sirvas de socorro.'),
('acf','2sm',18,4,'Então disse-lhe Davi: O que bem parecer aos vossos olhos, farei. E o rei se pôs do lado da porta, e todo o povo saiu em centenas e em milhares.'),
('acf','2sm',18,5,'E o rei deu ordem a Joabe, e a Abisai, e a Itai, dizendo: Brandamente tratai, por amor de mim, ao jovem Absalão. E todo o povo ouviu quando o rei deu ordem a todos os capitães acerca de Absalão.'),
('acf','2sm',18,6,'Saiu, pois, o povo ao campo, a encontrar-se com Israel, e deu-se a batalha no bosque de Efraim.'),
('acf','2sm',18,7,'E ali foi ferido o povo de Israel, diante dos servos de Davi; e naquele mesmo dia houve ali uma grande derrota de vinte mil.'),
('acf','2sm',18,8,'Porque ali se derramou a batalha sobre a face de toda aquela terra; e foram mais os do povo que o bosque consumiu do que os que a espada consumiu naquele dia.'),
('acf','2sm',18,9,'E Absalão se encontrou com os servos de Davi; e Absalão ia montado num mulo; e, entrando o mulo debaixo dos espessos ramos de um grande carvalho, pegou-se-lhe a cabeça no carvalho, e ficou pendurado entre o céu e a terra; e o mulo, que estava debaixo dele, passou adiante.'),
('acf','2sm',18,10,'O que vendo um homem, fez saber a Joabe, e disse: Eis que vi a Absalão pendurado num carvalho.'),
('acf','2sm',18,11,'Então disse Joabe ao homem que lho fizera saber: Pois que o viste, por que o não feriste logo ali em terra? E forçoso seria o eu dar-te dez moedas de prata e um cinto.'),
('acf','2sm',18,12,'Disse, porém, aquele homem a Joabe: Ainda que eu pudesse pesar nas minhas mãos mil moedas de prata, não estenderia a minha mão contra o filho do rei, pois bem ouvimos que o rei te deu ordem a ti, e a Abisai, e a Itai, dizendo: Guardai-vos, cada um de vós, de tocar no jovem Absalão.'),
('acf','2sm',18,13,'Ainda que cometesse mentira a risco da minha vida, nem por isso coisa nenhuma se esconderia ao rei; e tu mesmo te oporias.'),
('acf','2sm',18,14,'Então disse Joabe: Não me demorarei assim contigo aqui. E tomou três dardos, e traspassou com eles o coração de Absalão, estando ele ainda vivo no meio do carvalho.'),
('acf','2sm',18,15,'E o cercavam dez moços, que levaram as armas de Joabe. E feriram a Absalão, e o mataram.'),
('acf','2sm',18,16,'Então tocou Joabe a buzina, e voltou o povo de perseguir a Israel, porque Joabe deteve o povo.'),
('acf','2sm',18,17,'E tomaram a Absalão, e o lançaram no bosque, numa grande cova, e levantaram sobre ele um mui grande montão de pedras; e todo o Israel fugiu, cada um para a sua tenda.'),
('acf','2sm',18,18,'Ora, Absalão, quando ainda vivia, tinha tomado e levantado para si uma coluna, que está no vale do rei, porque dizia: Filho nenhum tenho para conservar a memória do meu nome. E chamou aquela coluna pelo seu próprio nome; por isso até ao dia de hoje se chama o Pilar de Absalão.'),
('acf','2sm',18,19,'Então disse Aimaás, filho de Zadoque: Deixa-me correr, e denunciarei ao rei que já o Senhor o vingou da mão de seus inimigos.'),
('acf','2sm',18,20,'Mas Joabe lhe disse: Tu não serás hoje o portador de novas, porém outro dia as levarás; mas hoje não darás a nova, porque é morto o filho do rei.'),
('acf','2sm',18,21,'E disse Joabe a Cusi: Vai tu, e dize ao rei o que viste. E Cusi se inclinou a Joabe, e correu.'),
('acf','2sm',18,22,'E prosseguiu Aimaás, filho de Zadoque, e disse a Joabe: Seja o que for deixa-me também correr após Cusi. E disse Joabe: Para que agora correrias tu, meu filho, pois não tens mensagem conveniente?'),
('acf','2sm',18,23,'Seja o que for, disse Aimaás, correrei. E Joabe lhe disse: Corre. E Aimaás correu pelo caminho da planície, e passou a Cusi.'),
('acf','2sm',18,24,'E Davi estava assentado entre as duas portas; e a sentinela subiu ao terraço da porta junto ao muro; e levantou os olhos, e olhou, e eis que um homem corria só.'),
('acf','2sm',18,25,'Gritou, pois, a sentinela, e o disse ao rei: Se vem só, há novas em sua boca. E vinha andando e chegando.'),
('acf','2sm',18,26,'Então viu a sentinela outro homem que corria, e a sentinela gritou ao porteiro, e disse: Eis que lá vem outro homem correndo só. Então disse o rei: Também traz este novas.'),
('acf','2sm',18,27,'Disse mais a sentinela: Vejo o correr do primeiro, que parece ser o correr de Aimaás, filho de Zadoque. Então disse o rei: Este é homem de bem, e virá com boas novas.'),
('acf','2sm',18,28,'Gritou, pois, Aimaás, e disse ao rei: Paz. E inclinou-se ao rei com o rosto em terra, e disse: Bendito seja o SENHOR, que entregou os homens que levantaram a mão contra o rei meu senhor.'),
('acf','2sm',18,29,'Então disse o rei: Vai bem com o jovem, com Absalão? E disse Aimaás: Vi um grande alvoroço, quando Joabe mandou o servo do rei, e a mim teu servo; porém não sei o que era.'),
('acf','2sm',18,30,'E disse o rei: Vira-te, e põe-te aqui. E virou-se, e parou.'),
('acf','2sm',18,31,'E eis que vinha Cusi; e disse Cusi: Anunciar-se-á ao rei meu senhor que hoje o SENHOR te vingou da mão de todos os que se levantaram contra ti.'),
('acf','2sm',18,32,'Então disse o rei a Cusi: Vai bem com o jovem, com Absalão? E disse Cusi: Sejam como aquele jovem os inimigos do rei meu senhor, e todos os que se levantam contra ti para mal.'),
('acf','2sm',18,33,'Então o rei se perturbou, e subiu à sala que estava por cima da porta, e chorou; e andando, dizia assim: Meu filho Absalão, meu filho, meu filho, Absalão! Quem me dera que eu morrera por ti, Absalão, meu filho, meu filho!'),
('acf','2sm',19,1,'E disseram a Joabe: Eis que o rei anda chorando, e lastima-se por Absalão.'),
('acf','2sm',19,2,'Então a vitória se tornou naquele mesmo dia em tristeza por todo o povo; porque naquele mesmo dia o povo ouvira dizer: Mui triste está o rei por causa de seu filho.'),
('acf','2sm',19,3,'E naquele mesmo dia o povo entrou às furtadelas na cidade, como o faz quando, envergonhado, foge da peleja.'),
('acf','2sm',19,4,'Estava, pois, o rei com o rosto coberto; e o rei gritava a alta voz: Meu filho Absalão, Absalão meu filho, meu filho!'),
('acf','2sm',19,5,'Então entrou Joabe na casa do rei, e disse: Hoje envergonhaste o rosto de todos os teus servos, que livraram hoje a tua vida, e a vida de teus filhos, e de tuas filhas, e a vida de tuas mulheres, e a vida de tuas concubinas;'),
('acf','2sm',19,6,'Amando tu aos teus inimigos, e odiando aos teus amigos. Porque hoje dás a entender que nada valem para contigo príncipes e servos; porque entendo hoje que se Absalão vivesse, e todos nós hoje fôssemos mortos, estarias bem contente.'),
('acf','2sm',19,7,'Levanta-te, pois, agora; sai, e fala conforme ao coração de teus servos; porque pelo Senhor te juro que, se não saíres, nem um só homem ficará contigo esta noite; e maior mal te será isto do que todo o mal que tem vindo sobre ti desde a tua mocidade até agora.'),
('acf','2sm',19,8,'Então o rei se levantou, e se assentou à porta; e fizeram saber a todo o povo dizendo: Eis que o rei está assentado à porta. Então todo o povo veio apresentar-se diante do rei; porém Israel havia fugido cada um para a sua tenda.'),
('acf','2sm',19,9,'E todo o povo, em todas as tribos de Israel, andava porfiando entre si, dizendo: O rei nos tirou das mãos de nossos inimigos, e ele nos livrou das mãos dos filisteus; e agora fugiu da terra por causa de Absalão.'),
('acf','2sm',19,10,'E Absalão, a quem ungimos sobre nós, já morreu na peleja; agora, pois, por que vos calais, e não fazeis voltar o rei?'),
('acf','2sm',19,11,'Então o rei Davi mandou dizer a Zadoque e a Abiatar, sacerdotes: Falai aos anciãos de Judá, dizendo: Por que seríeis vós os últimos em tornar a trazer o rei para a sua casa? Porque as palavras de todo o Israel chegaram ao rei, até à sua casa.'),
('acf','2sm',19,12,'Vós sois meus irmãos, meus ossos e minha carne sois vós; por que, pois, seríeis os últimos em tornar a trazer o rei?'),
('acf','2sm',19,13,'E a Amasa direis: Porventura não és tu meu osso e minha carne? Assim me faça Deus, e outro tanto, se não fores capitão do arraial diante de mim para sempre, em lugar de Joabe.'),
('acf','2sm',19,14,'Assim moveu ele o coração de todos os homens de Judá, como o de um só homem; e enviaram ao rei, dizendo: Volta tu com todos os teus servos.'),
('acf','2sm',19,15,'Então o rei voltou, e chegou até ao Jordão; e Judá veio a Gilgal, para ir encontrar-se com o rei, ao outro lado do Jordão.'),
('acf','2sm',19,16,'E apressou-se Simei, filho de Gera, benjamita, que era de Baurim; e desceu com os homens de Judá a encontrar-se com o rei Davi.'),
('acf','2sm',19,17,'E com ele mil homens de Benjamim, como também Ziba, servo da casa de Saul, e seus quinze filhos, e seus vinte servos com ele; e prontamente passaram o Jordão adiante do rei.'),
('acf','2sm',19,18,'E, atravessando a barca, para fazer passar a casa do rei e para fazer o que bem parecesse aos seus olhos, então Simei, filho de Gera, se prostrou diante do rei, quando ele passava o Jordão.'),
('acf','2sm',19,19,'E disse ao rei: Não me impute meu senhor a minha culpa, e não te lembres do que tão perversamente fez teu servo, no dia em que o rei meu senhor saiu de Jerusalém; não conserve o rei isso no coração.'),
('acf','2sm',19,20,'Porque teu servo deveras confessa que pecou; porém eis que eu sou o primeiro que de toda a casa de José desci a encontrar-me com o rei meu senhor.'),
('acf','2sm',19,21,'Então respondeu Abisai, filho de Zeruia, e disse: Não morreria, pois, Simei por isto, havendo amaldiçoado ao ungido do Senhor?'),
('acf','2sm',19,22,'Porém Davi disse: Que tenho eu convosco, filhos de Zeruia, para que hoje me sejais adversários? Morreria alguém hoje em Israel? Pois porventura não sei que hoje fui feito rei sobre Israel?'),
('acf','2sm',19,23,'E disse o rei a Simei: Não morrerás. E o rei lho jurou.'),
('acf','2sm',19,24,'Também Mefibosete, filho de Saul, desceu a encontrar-se com o rei, e não tinha lavado os pés, nem tinha feito a barba, nem tinha lavado as suas vestes desde o dia em que o rei tinha saído até ao dia em que voltou em paz.'),
('acf','2sm',19,25,'E sucedeu que, vindo ele a Jerusalém a encontrar-se com o rei, disse-lhe o rei: Por que não foste comigo, Mefibosete?'),
('acf','2sm',19,26,'E disse ele: Ó rei meu senhor, o meu servo me enganou; porque o teu servo dizia: Albardarei um jumento, e nele montarei, e irei com o rei; pois o teu servo é coxo.'),
('acf','2sm',19,27,'Demais disto, falsamente acusou a teu servo diante do rei meu senhor; porém o rei meu senhor é como um anjo de Deus; faze, pois, o que parecer bem aos teus olhos.'),
('acf','2sm',19,28,'Porque toda a casa de meu pai não era senão de homens dignos de morte diante do rei meu senhor; e contudo puseste a teu servo entre os que comem à tua mesa; e que mais direito tenho eu de clamar ao rei?'),
('acf','2sm',19,29,'E disse-lhe o rei: Por que ainda mais falas de teus negócios? Já disse eu: Tu e Ziba reparti as terras.'),
('acf','2sm',19,30,'E disse Mefibosete ao rei: Tome ele também tudo; pois já veio o rei meu senhor em paz à sua casa.'),
('acf','2sm',19,31,'Também Barzilai, o gileadita, desceu de Rogelim, e passou com o rei o Jordão, para o acompanhar ao outro lado do Jordão.'),
('acf','2sm',19,32,'E era Barzilai muito velho, da idade de oitenta anos; e ele tinha sustentado o rei, quando tinha a sua morada em Maanaim, porque era grande homem.'),
('acf','2sm',19,33,'E disse o rei a Barzilai: Passa tu comigo, e sustentar-te-ei comigo em Jerusalém.'),
('acf','2sm',19,34,'Porém Barzilai disse ao rei: Quantos serão os dias dos anos da minha vida, para que suba com o rei a Jerusalém?'),
('acf','2sm',19,35,'Da idade de oitenta anos sou eu hoje; poderia eu discernir entre o bom e o mau? Poderia o teu servo ter gosto no que comer e beber? Poderia eu mais ouvir a voz dos cantores e cantoras? E por que será o teu servo ainda pesado ao rei meu senhor?'),
('acf','2sm',19,36,'Com o rei passará teu servo ainda um pouco mais além do Jordão; e por que me recompensará o rei com tal recompensa?'),
('acf','2sm',19,37,'Deixa voltar o teu servo, e morrerei na minha cidade, junto à sepultura de meu pai e de minha mãe; mas eis aí está o teu servo Quimã; passe ele com o rei meu senhor, e faze-lhe o que bem parecer aos teus olhos.'),
('acf','2sm',19,38,'Então disse o rei: Quimã passará comigo, e eu lhe farei como bem parecer aos teus olhos, e tudo quanto me pedires te farei.'),
('acf','2sm',19,39,'Havendo, pois, todo o povo passado o Jordão, e passando também o rei, beijou o rei a Barzilai, e o abençoou; e ele voltou para o seu lugar.'),
('acf','2sm',19,40,'E dali passou o rei a Gilgal, e Quimã passou com ele; e todo o povo de Judá conduziu o rei, como também a metade do povo de Israel.'),
('acf','2sm',19,41,'E eis que todos os homens de Israel vieram ao rei, e disseram ao rei: Por que te furtaram nossos irmãos, os homens de Judá, e conduziram o rei e a sua casa dalém do Jordão, e todos os homens de Davi com eles?'),
('acf','2sm',19,42,'Então responderam todos os homens de Judá aos homens de Israel: Porquanto o rei é nosso parente; e por que vos irais por isso? Porventura comemos às custas do rei, ou nos deu algum presente?'),
('acf','2sm',19,43,'E responderam os homens de Israel aos homens de Judá, e disseram: Dez partes temos no rei, e até em Davi mais temos nós do que vós; por que, pois, não fizestes conta de nós, para que a nossa palavra não fosse a primeira, para tornar a trazer o nosso rei? Porém a palavra dos homens de Judá foi mais forte do que a palavra dos homens de Israel.'),
('acf','2sm',20,1,'Então se achou ali por acaso um homem de Belial, cujo nome era Seba, filho de Bicri, homem de Benjamim, o qual tocou a buzina, e disse: Não temos parte em Davi, nem herança no filho de Jessé; cada um às suas tendas, ó Israel.'),
('acf','2sm',20,2,'Então todos os homens de Israel se separaram de Davi, e seguiram Seba, filho de Bicri; porém os homens de Judá se uniram ao seu rei desde o Jordão até Jerusalém.'),
('acf','2sm',20,3,'Vindo, pois, Davi para sua casa, em Jerusalém, tomou o rei as dez mulheres, suas concubinas, que deixara para guardarem a casa, e as pôs numa casa sob guarda, e as sustentava; porém não as possuiu; e estiveram encerradas até ao dia da sua morte, vivendo como viúvas.'),
('acf','2sm',20,4,'Disse mais o rei a Amasa: Convoca-me os homens de Judá para o terceiro dia; e tu então apresenta-te aqui.'),
('acf','2sm',20,5,'E foi Amasa para convocar a Judá; porém demorou-se além do tempo que lhe tinha sido designado.'),
('acf','2sm',20,6,'Então disse Davi a Abisai: Mais mal agora nos fará Seba, o filho de Bicri, do que Absalão; por isso toma tu os servos de teu senhor, e persegue-o, para que não ache para si cidades fortes, e escape dos nossos olhos.'),
('acf','2sm',20,7,'Então saíram atrás dele os homens de Joabe, e os quereteus, e os peleteus, e todos os valentes; estes saíram de Jerusalém para irem atrás de Seba, filho de Bicri.'),
('acf','2sm',20,8,'Chegando eles, pois, à pedra grande, que está junto a Gibeom, Amasa veio diante deles; e estava Joabe cingido da sua roupa que vestira, e sobre ela um cinto, ao qual estava presa a espada a seus lombos, na sua bainha; e, adiantando-se ele, lhe caiu a espada.'),
('acf','2sm',20,9,'E disse Joabe a Amasa: Vai bem, meu irmão? E Joabe, com a mão direita, pegou da barba de Amasa, para o beijar.'),
('acf','2sm',20,10,'E Amasa não se resguardou da espada que estava na mão de Joabe, de sorte que este o feriu com ela na quinta costela, e lhe derramou por terra as entranhas, e não o feriu segunda vez, e morreu; então Joabe e Abisai, seu irmão, foram atrás de Seba, filho de Bicri.'),
('acf','2sm',20,11,'Mas um dentre os homens de Joabe parou junto a ele, e disse: Quem há que queira bem a Joabe, e quem seja por Davi, siga Joabe.'),
('acf','2sm',20,12,'E Amasa estava envolto no seu sangue no meio do caminho; e, vendo aquele homem, que todo o povo parava, removeu a Amasa do caminho para o campo, e lançou sobre ele um manto; porque via que todo aquele que chegava a ele parava.'),
('acf','2sm',20,13,'E, como estava removido do caminho, todos os homens seguiram a Joabe, para perseguirem a Seba, filho de Bicri.'),
('acf','2sm',20,14,'E ele passou por todas as tribos de Israel até Abel, e Bete-Maaca e a todos os beritas; e ajuntaram-se, e também o seguiram.'),
('acf','2sm',20,15,'E vieram, e o cercaram em Abel de Bete-Maaca, e levantaram uma barragem contra a cidade, e isto colocado na trincheira; e todo o povo que estava com Joabe batia no muro, para derrubá-lo.'),
('acf','2sm',20,16,'Então uma mulher sábia gritou de dentro da cidade: Ouvi, ouvi, peço-vos que digais a Joabe: Chega-te aqui, para que eu te fale.'),
('acf','2sm',20,17,'Chegando-se a ela, a mulher lhe disse: Tu és Joabe? E disse ele: Eu sou. E ela lhe disse: Ouve as palavras da tua serva. E disse ele: Ouço.'),
('acf','2sm',20,18,'Então falou ela, dizendo: Antigamente costumava-se dizer: Certamente pediram conselho a Abel; e assim resolveram.'),
('acf','2sm',20,19,'Sou eu uma das pacíficas e das fiéis em Israel; e tu procuras matar uma cidade que é mãe em Israel; por que, pois, devorarias a herança do Senhor?'),
('acf','2sm',20,20,'Então respondeu Joabe, e disse: Longe, longe de mim que eu tal faça, que eu devore ou arruíne!'),
('acf','2sm',20,21,'A coisa não é assim; porém um só homem do monte de Efraim, cujo nome é Seba, filho de Bicri, levantou a mão contra o rei, contra Davi; entregai-me só este, e retirar-me-ei da cidade. Então disse a mulher a Joabe: Eis que te será lançada a sua cabeça pelo muro.'),
('acf','2sm',20,22,'E a mulher, na sua sabedoria, foi a todo o povo, e cortaram a cabeça de Seba, filho de Bicri, e a lançaram a Joabe; então este tocou a buzina, e se retiraram da cidade, cada um para a sua tenda, e Joabe voltou a Jerusalém, ao rei.'),
('acf','2sm',20,23,'E Joabe estava sobre todo o exército de Israel; e Benaia, filho de Joiada, sobre os quereteus e sobre os peleteus;'),
('acf','2sm',20,24,'E Adorão sobre os tributos; e Jeosafá, filho de Ailude, era o cronista;'),
('acf','2sm',20,25,'E Seva, o escrivão; e Zadoque e Abiatar, os sacerdotes;'),
('acf','2sm',20,26,'E também Ira, o jairita, era o oficial-mor de Davi.'),
('acf','2sm',21,1,'E houve nos dias de Davi uma fome de três anos consecutivos; e Davi consultou ao SENHOR, e o SENHOR lhe disse: É por causa de Saul e da sua casa sanguinária, porque matou os gibeonitas.'),
('acf','2sm',21,2,'Então chamou o rei aos gibeonitas, e lhes falou (ora os gibeonitas não eram dos filhos de Israel, mas do restante dos amorreus, e os filhos de Israel lhes tinham jurado, porém Saul, no seu zelo à causa dos filhos de Israel e de Judá, procurou feri-los).'),
('acf','2sm',21,3,'Disse, pois, Davi aos gibeonitas: Que quereis que eu vos faça? E que satisfação vos darei, para que abençoeis a herança do Senhor?'),
('acf','2sm',21,4,'Então os gibeonitas lhe disseram: Não é por prata nem ouro que temos questão com Saul e com sua casa; nem tampouco pretendemos matar pessoa alguma em Israel. E disse ele: Que é, pois, que quereis que vos faça?'),
('acf','2sm',21,5,'E disseram ao rei: O homem que nos destruiu, e intentou contra nós de modo que fôssemos assolados, sem que pudéssemos subsistir em termo algum de Israel,'),
('acf','2sm',21,6,'De seus filhos se nos dêem sete homens, para que os enforquemos ao Senhor em Gibeá de Saul, o eleito do Senhor. E disse o rei: Eu os darei.'),
('acf','2sm',21,7,'Porém o rei poupou a Mefibosete, filho de Jônatas, filho de Saul, por causa do juramento do Senhor, que entre eles houvera, entre Davi e Jônatas, filho de Saul.'),
('acf','2sm',21,8,'Mas tomou o rei os dois filhos de Rispa, filha da Aiá, que tinha tido de Saul, a Armoni e a Mefibosete; como também os cinco filhos da irmã de Mical, filha de Saul, que tivera de Adriel, filho de Barzilai, meolatita,'),
('acf','2sm',21,9,'E os entregou na mão dos gibeonitas, os quais os enforcaram no monte, perante o Senhor; e caíram estes sete juntamente; e foram mortos nos dias da sega, nos dias primeiros, no princípio da sega das cevadas.'),
('acf','2sm',21,10,'Então Rispa, filha de Aiá, tomou um pano de cilício, e estendeu-lho sobre uma penha, desde o princípio da sega até que a água do céu caiu sobre eles; e não deixou as aves do céu pousar sobre eles de dia, nem os animais do campo de noite.'),
('acf','2sm',21,11,'E foi contado a Davi o que fizera Rispa, filha de Aiá, concubina de Saul.'),
('acf','2sm',21,12,'Então foi Davi, e tomou os ossos de Saul, e os ossos de Jônatas seu filho, dos moradores de Jabes-Gileade, os quais os furtaram da rua de Bete-Sã, onde os filisteus os tinham pendurado, quando feriram a Saul em Gilboa.'),
('acf','2sm',21,13,'E fez subir dali os ossos de Saul, e os ossos de Jônatas seu filho; e ajuntaram também os ossos dos enforcados.'),
('acf','2sm',21,14,'Enterraram os ossos de Saul, e de Jônatas seu filho na terra de Benjamim, em Zela, na sepultura de seu pai Quis, e fizeram tudo o que o rei ordenara; e depois disto Deus se aplacou com a terra.'),
('acf','2sm',21,15,'Tiveram mais os filisteus uma peleja contra Israel; e desceu Davi, e com ele os seus servos; e tanto pelejaram contra os filisteus, que Davi se cansou.'),
('acf','2sm',21,16,'E Isbi-Benobe, que era dos filhos do gigante, cuja lança pesava trezentos siclos de cobre, e que cingia uma espada nova, intentou ferir a Davi.'),
('acf','2sm',21,17,'Porém, Abisai, filho de Zeruia, o socorreu, e feriu o filisteu, e o matou. Então os homens de Davi lhe juraram, dizendo: Nunca mais sairás conosco à peleja, para que não apagues a lâmpada de Israel.'),
('acf','2sm',21,18,'E aconteceu depois disto que houve em Gobe ainda outra peleja contra os filisteus; então Sibecai, o husatita, feriu a Safe, que era dos filhos do gigante.'),
('acf','2sm',21,19,'Houve mais outra peleja contra os filisteus em Gobe; e El-Hanã, filho de Jaaré-Oregim, o belemita, feriu Golias, o giteu, de cuja lança era a haste como órgão de tecelão.'),
('acf','2sm',21,20,'Houve ainda também outra peleja em Gate, onde estava um homem de alta estatura, que tinha em cada mão seis dedos, e em cada pé outros seis, vinte e quatro ao todo, e também este nascera do gigante.'),
('acf','2sm',21,21,'E injuriava a Israel; porém Jônatas, filho de Simei, irmão de Davi, o feriu.'),
('acf','2sm',21,22,'Estes quatro nasceram ao gigante em Gate; e caíram pela mão de Davi e pela mão de seus servos.'),
('acf','2sm',22,1,'E Falou Davi ao SENHOR as palavras deste cântico, no dia em que o SENHOR o livrou das mãos de todos os seus inimigos e das mãos de Saul.'),
('acf','2sm',22,2,'Disse pois: O Senhor é o meu rochedo, e o meu lugar forte, e o meu libertador.'),
('acf','2sm',22,3,'Deus é o meu rochedo, nele confiarei; o meu escudo, e a força da minha salvação, o meu alto retiro, e o meu refúgio. Ó meu Salvador, da violência me salvas.'),
('acf','2sm',22,4,'O Senhor, digno de louvor, invocarei, e de meus inimigos ficarei livre,'),
('acf','2sm',22,5,'Porque me cercaram as ondas de morte; as torrentes dos homens ímpios me assombraram.'),
('acf','2sm',22,6,'Cordas do inferno me cingiram; encontraram-me laços de morte.'),
('acf','2sm',22,7,'Estando em angústia, invoquei ao Senhor, e a meu Deus clamei; do seu templo ouviu ele a minha voz, e o meu clamor chegou aos seus ouvidos.'),
('acf','2sm',22,8,'Então se abalou e tremeu a terra, os fundamentos dos céus se moveram e abalaram, porque ele se irou.'),
('acf','2sm',22,9,'Subiu fumaça de suas narinas, e da sua boca um fogo devorador; carvões se incenderam dele.'),
('acf','2sm',22,10,'E abaixou os céus, e desceu; e uma escuridão havia debaixo de seus pés.'),
('acf','2sm',22,11,'E subiu sobre um querubim, e voou; e foi visto sobre as asas do vento.'),
('acf','2sm',22,12,'E por tendas pôs as trevas ao redor de si; ajuntamento de águas, nuvens dos céus.'),
('acf','2sm',22,13,'Pelo resplendor da sua presença brasas de fogo se acenderam.'),
('acf','2sm',22,14,'Trovejou desde os céus o Senhor; e o Altíssimo fez soar a sua voz.'),
('acf','2sm',22,15,'E disparou flechas, e os dissipou; raios, e os perturbou.'),
('acf','2sm',22,16,'E apareceram as profundezas do mar, e os fundamentos do mundo se descobriram; pela repreensão do Senhor, pelo sopro do vento das suas narinas.'),
('acf','2sm',22,17,'Desde o alto enviou, e me tomou; tirou-me das muitas águas.'),
('acf','2sm',22,18,'Livrou-me do meu poderoso inimigo, e daqueles que me tinham ódio, porque eram mais fortes do que eu.'),
('acf','2sm',22,19,'Encontraram-me no dia da minha calamidade; porém o Senhor se fez o meu amparo.'),
('acf','2sm',22,20,'E tirou-me para um lugar espaçoso, e livrou-me, porque tinha prazer em mim.'),
('acf','2sm',22,21,'Recompensou-me o Senhor conforme a minha justiça; conforme a pureza de minhas mãos me retribuiu.'),
('acf','2sm',22,22,'Porque guardei os caminhos do Senhor; e não me apartei impiamente do meu Deus.'),
('acf','2sm',22,23,'Porque todos os seus juízos estavam diante de mim; e de seus estatutos não me desviei.'),
('acf','2sm',22,24,'Porém fui sincero perante ele; e guardei-me da minha iniqüidade.'),
('acf','2sm',22,25,'E me retribuiu o Senhor conforme a minha justiça, conforme a minha pureza diante dos seus olhos.'),
('acf','2sm',22,26,'Com o benigno te mostras benigno; com o homem íntegro te mostras perfeito.'),
('acf','2sm',22,27,'Com o puro te mostras puro; mas com o perverso te mostras rígido.'),
('acf','2sm',22,28,'E o povo aflito livras; mas teus olhos são contra os altivos, e tu os abaterás.'),
('acf','2sm',22,29,'Porque tu, Senhor, és a minha lâmpada; e o Senhor ilumina as minhas trevas.'),
('acf','2sm',22,30,'Porque contigo passo pelo meio de um esquadrão; pelo meu Deus salto um muro.'),
('acf','2sm',22,31,'O caminho de Deus é perfeito, e a palavra do Senhor refinada; e é o escudo de todos os que nele confiam.'),
('acf','2sm',22,32,'Por que, quem é Deus, senão o Senhor? E quem é rochedo, senão o nosso Deus?'),
('acf','2sm',22,33,'Deus é a minha fortaleza e a minha força, e ele perfeitamente desembaraça o meu caminho.'),
('acf','2sm',22,34,'Faz ele os meus pés como os das cervas, e me põe sobre as minhas alturas.'),
('acf','2sm',22,35,'Instrui as minhas mãos para a peleja, de maneira que um arco de cobre se quebra pelos meus braços.'),
('acf','2sm',22,36,'Também me deste o escudo da tua salvação, e pela tua brandura me vieste a engrandecer.'),
('acf','2sm',22,37,'Alargaste os meus passos debaixo de mim, e não vacilaram os meus artelhos.'),
('acf','2sm',22,38,'Persegui os meus inimigos, e os derrotei, e nunca me tornei até que os consumisse.'),
('acf','2sm',22,39,'E os consumi, e os atravessei, de modo que nunca mais se levantaram, mas caíram debaixo dos meus pés.'),
('acf','2sm',22,40,'Porque me cingiste de força para a peleja; fizeste abater-se debaixo de mim os que se levantaram contra mim,'),
('acf','2sm',22,41,'E deste-me o pescoço de meus inimigos, daqueles que me tinham ódio, e os destruí.'),
('acf','2sm',22,42,'Olharam, porém não houve libertador; sim, para o Senhor, porém não lhes respondeu.'),
('acf','2sm',22,43,'Então os moí como o pó da terra; como a lama das ruas os trilhei e dissipei.'),
('acf','2sm',22,44,'Também me livraste das contendas do meu povo; guardaste-me para cabeça das nações; o povo que não conhecia me servirá.'),
('acf','2sm',22,45,'Os filhos de estranhos se me sujeitaram; ouvindo a minha voz, me obedeceram.'),
('acf','2sm',22,46,'Os filhos de estranhos desfaleceram; e, cingindo-se, saíram dos seus esconderijos.'),
('acf','2sm',22,47,'Vive o Senhor, e bendito seja o meu rochedo; e exaltado seja Deus, a rocha da minha salvação,'),
('acf','2sm',22,48,'O Deus que me dá inteira vingança, e sujeita os povos debaixo de mim.'),
('acf','2sm',22,49,'E o que me tira dentre os meus inimigos; e tu me exaltas sobre os que contra mim se levantam; do homem violento me livras.'),
('acf','2sm',22,50,'Por isso, ó Senhor, te louvarei entre os gentios, e entoarei louvores ao teu nome.'),
('acf','2sm',22,51,'Ele é a torre das salvações do seu rei, e usa de benignidade com o seu ungido, com Davi, e com a sua descendência para sempre.'),
('acf','2sm',23,1,'E estas são as últimas palavras de Davi: Diz Davi, filho de Jessé, e diz o homem que foi levantado em altura, o ungido do Deus de Jacó, e o suave em salmos de Israel.'),
('acf','2sm',23,2,'O Espírito do Senhor falou por mim, e a sua palavra está na minha boca.'),
('acf','2sm',23,3,'Disse o Deus de Israel, a Rocha de Israel a mim me falou: Haverá um justo que domine sobre os homens, que domine no temor de Deus.'),
('acf','2sm',23,4,'E será como a luz da manhã, quando sai o sol, da manhã sem nuvens, quando pelo seu resplendor e pela chuva a erva brota da terra.'),
('acf','2sm',23,5,'Ainda que a minha casa não seja tal para com Deus, contudo estabeleceu comigo uma aliança eterna, que em tudo será bem ordenado e guardado, pois toda a minha salvação e todo o meu prazer está nele, apesar de que ainda não o faz brotar.'),
('acf','2sm',23,6,'Porém os filhos de Belial todos serão como os espinhos que se lançam fora, porque não podem ser tocados com a mão.'),
('acf','2sm',23,7,'Mas qualquer que os tocar se armará de ferro e da haste de uma lança; e a fogo serão totalmente queimados no mesmo lugar.'),
('acf','2sm',23,8,'Estes são os nomes dos poderosos que Davi teve: Josebe-Bassebete, filho de Taquemoni, o principal dos capitães; este era Adino, o eznita, que se opusera a oitocentos, e os feriu de uma vez.'),
('acf','2sm',23,9,'E depois dele Eleazar, filho de Dodó, filho de Aoí, entre os três valentes que estavam com Davi quando provocaram os filisteus que ali se ajuntaram à peleja, e quando se retiraram os homens de Israel.'),
('acf','2sm',23,10,'Este se levantou, e feriu os filisteus, até lhe cansar a mão e ficar a mão pegada à espada; e naquele dia o Senhor efetuou um grande livramento; e o povo voltou junto dele, somente a tomar o despojo.'),
('acf','2sm',23,11,'E depois dele Samá, filho de Agé, o hararita, quando os filisteus se ajuntaram numa multidão, onde havia um pedaço de terra cheio de lentilhas, e o povo fugira de diante dos filisteus.'),
('acf','2sm',23,12,'Este, pois, se pôs no meio daquele pedaço de terra, e o defendeu, e feriu os filisteus; e o Senhor efetuou um grande livramento.'),
('acf','2sm',23,13,'Também três dos trinta chefes desceram, e no tempo da sega foram a Davi, à caverna de Adulão; e a multidão dos filisteus acampara no vale de Refaim.'),
('acf','2sm',23,14,'Davi estava então num lugar forte, e a guarnição dos filisteus em Belém.'),
('acf','2sm',23,15,'E teve Davi desejo, e disse: Quem me dera beber da água da cisterna de Belém, que está junto à porta!'),
('acf','2sm',23,16,'Então aqueles três poderosos romperam pelo arraial dos filisteus, e tiraram água da cisterna de Belém, que está junto à porta, e a tomaram, e a trouxeram a Davi; porém ele não a quis beber, mas derramou-a perante o Senhor.'),
('acf','2sm',23,17,'E disse: Guarda-me, ó Senhor, de que tal faça; beberia eu o sangue dos homens que foram com risco da sua vida? De maneira que não a quis beber; isto fizeram aqueles três poderosos.'),
('acf','2sm',23,18,'Também Abisai, irmão de Joabe, filho de Zeruia, era chefe de três; e este alçou a sua lança contra trezentos e os feriu; e tinha nome entre os três.'),
('acf','2sm',23,19,'Porventura este não era o mais nobre dentre estes três? Pois era o primeiro deles; porém aos primeiros três não chegou.'),
('acf','2sm',23,20,'Também Benaia, filho de Joiada, filho de um homem valoroso de Cabzeel, grande em obras, este feriu dois fortes heróis de Moabe; e desceu ele, e feriu um leão no meio duma cova, no tempo da neve.'),
('acf','2sm',23,21,'Também este feriu um egípcio, homem de respeito; e na mão do egípcio havia uma lança, porém ele desceu a ele com um cajado, e arrancou a lança da mão do egípcio, e com ela o matou.'),
('acf','2sm',23,22,'Estas coisas fez Benaia, filho de Joiada, pelo que teve nome entre três poderosos.'),
('acf','2sm',23,23,'Dentre os trinta ele era o mais nobre, porém aos três primeiros não chegou; e Davi o pôs sobre os seus guardas.'),
('acf','2sm',23,24,'Asael, irmão de Joabe, estava entre os trinta; El-Hanã, filho de Dodó, de Belém;'),
('acf','2sm',23,25,'Samá, harodita; Elica, harodita;'),
('acf','2sm',23,26,'Helez, paltita; Ira, filho de Iques, tecoíta;'),
('acf','2sm',23,27,'Abiezer, anatotita; Mebunai, husatita;'),
('acf','2sm',23,28,'Zalmom, aoíta; Maarai, netofatita;'),
('acf','2sm',23,29,'Elebe, filho de Baaná, netofatita; Itai, filho de Ribai, de Gibeá dos filhos de Benjamim;'),
('acf','2sm',23,30,'Benaia, piratonita; Hidai, do ribeiro de Gaás;'),
('acf','2sm',23,31,'Abi-Albom, arbatita; Azmavete, barumita;'),
('acf','2sm',23,32,'Eliaba, saalbonita; os filhos de Jásen e Jônatas;'),
('acf','2sm',23,33,'Samá, hararita, Aião, filho de Sarar, ararita;'),
('acf','2sm',23,34,'Elifelete, filho de Aasbai, filho de um maacatita; Eliã, filho de Aitofel, gilonita;'),
('acf','2sm',23,35,'Hesrai, carmelita; Paarai, arbita;'),
('acf','2sm',23,36,'Igal, filho de Natã, de Zobá; Bani, gadita;'),
('acf','2sm',23,37,'Zeleque, amonita; Naarai, beerotita, o que trazia as armas de Joabe, filho de Zeruia;'),
('acf','2sm',23,38,'Ira, itrita; Garebe, itrita;'),
('acf','2sm',23,39,'Urias, heteu; trinta e sete ao todo.'),
('acf','2sm',24,1,'E a ira do SENHOR se tornou a acender contra Israel; e incitou a Davi contra eles, dizendo: Vai, numera a Israel e a Judá.'),
('acf','2sm',24,2,'Disse, pois, o rei a Joabe, capitão do exército, o qual tinha consigo: Agora percorre todas as tribos de Israel, desde Dã até Berseba, e numera o povo, para que eu saiba o número do povo.'),
('acf','2sm',24,3,'Então disse Joabe ao rei: Ora, multiplique o SENHOR teu Deus a este povo cem vezes tanto quanto agora é, e os olhos do rei meu senhor o vejam; mas, por que deseja o rei meu senhor este negócio?'),
('acf','2sm',24,4,'Porém a palavra do rei prevaleceu contra Joabe, e contra os capitães do exército; Joabe, pois, saiu com os capitães do exército da presença do rei, para numerar o povo de Israel.'),
('acf','2sm',24,5,'E passaram o Jordão; e acamparam-se em Aroer, à direita da cidade que está no meio do ribeiro de Gade, junto a Jazer.'),
('acf','2sm',24,6,'E foram a Gileade, e à terra baixa de Hodsi; também foram até Dã-Jaã, e ao redor de Sidom.'),
('acf','2sm',24,7,'E foram à fortaleza de Tiro, e a todas as cidades dos heveus e dos cananeus; e saíram para o lado do sul de Judá, a Berseba.'),
('acf','2sm',24,8,'Assim percorreram toda a terra; e ao cabo de nove meses e vinte dias voltaram a Jerusalém.'),
('acf','2sm',24,9,'E Joabe deu ao rei a soma do número do povo contado; e havia em Israel oitocentos mil homens de guerra, que arrancavam da espada; e os homens de Judá eram quinhentos mil homens.'),
('acf','2sm',24,10,'E pesou o coração de Davi, depois de haver numerado o povo; e disse Davi ao Senhor: Muito pequei no que fiz; porém agora ó Senhor, peço-te que perdoes a iniqüidade do teu servo; porque tenho procedido mui loucamente.'),
('acf','2sm',24,11,'Levantando-se, pois, Davi pela manhã, veio a palavra do Senhor ao profeta Gade, vidente de Davi, dizendo:'),
('acf','2sm',24,12,'Vai, e dize a Davi: Assim diz o Senhor: Três coisas te ofereço; escolhe uma delas, para que ta faça.'),
('acf','2sm',24,13,'Foi, pois, Gade a Davi, e fez-lho saber; e disse-lhe: Queres que sete anos de fome te venham à tua terra; ou que por três meses fujas de teus inimigos, e eles te persigam; ou que por três dias haja peste na tua terra? Delibera agora, e vê que resposta hei de dar ao que me enviou.'),
('acf','2sm',24,14,'Então disse Davi a Gade: Estou em grande angústia; porém caiamos nas mãos do Senhor, porque muitas são as suas misericórdias; mas nas mãos dos homens não caia eu.'),
('acf','2sm',24,15,'Então enviou o Senhor a peste a Israel, desde a manhã até ao tempo determinado; e desde Dã até Berseba, morreram setenta mil homens do povo.'),
('acf','2sm',24,16,'Estendendo, pois, o anjo a sua mão sobre Jerusalém, para a destruir, o Senhor se arrependeu daquele mal; e disse ao anjo que fazia a destruição entre o povo: Basta, agora retira a tua mão. E o anjo do Senhor estava junto à eira de Araúna, o jebuseu.'),
('acf','2sm',24,17,'E, vendo Davi ao anjo que feria o povo, falou ao Senhor, dizendo: Eis que eu sou o que pequei, e eu que iniquamente procedi; porém estas ovelhas que fizeram? Seja, pois, a tua mão contra mim, e contra a casa de meu pai.'),
('acf','2sm',24,18,'E Gade veio naquele mesmo dia a Davi, e disse-lhe: Sobe, levanta ao Senhor um altar na eira de Araúna, o jebuseu.'),
('acf','2sm',24,19,'Davi subiu conforme à palavra de Gade, como o Senhor lhe tinha ordenado.'),
('acf','2sm',24,20,'E olhou Araúna, e viu que vinham para ele o rei e os seus servos; saiu, pois, Araúna e inclinou-se diante do rei com o rosto em terra.'),
('acf','2sm',24,21,'E disse Araúna: Por que vem o rei meu Senhor ao seu servo? E disse Davi: Para comprar de ti esta eira, a fim de edificar nela um altar ao Senhor, para que este castigo cesse de sobre o povo.'),
('acf','2sm',24,22,'Então disse Araúna a Davi: Tome, e ofereça o rei meu senhor o que bem parecer aos seus olhos; eis aí bois para o holocausto, e os trilhos, e o aparelho dos bois para a lenha.'),
('acf','2sm',24,23,'Tudo isto deu Araúna ao rei; disse mais Araúna ao rei: O Senhor teu Deus tome prazer em ti.'),
('acf','2sm',24,24,'Porém o rei disse a Araúna: Não, mas por preço justo to comprarei, porque não oferecerei ao Senhor meu Deus holocaustos que não me custem nada. Assim Davi comprou a eira e os bois por cinqüenta siclos de prata.'),
('acf','2sm',24,25,'E edificou ali Davi ao Senhor um altar, e ofereceu holocaustos, e ofertas pacíficas. Assim o Senhor se aplacou para com a terra e cessou aquele castigo de sobre Israel.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','1rs',1,1,'Sendo, pois, o rei Davi já velho, e entrado em dias, cobriam-no de roupas, porém não se aquecia.'),
('acf','1rs',1,2,'Então disseram-lhe os seus servos: Busquem para o rei meu senhor uma moça virgem, que esteja perante o rei, e tenha cuidado dele; e durma no seu seio, para que o rei meu senhor se aqueça.'),
('acf','1rs',1,3,'E buscaram por todos os termos de Israel uma moça formosa, e acharam a Abisague, sunamita; e a trouxeram ao rei.'),
('acf','1rs',1,4,'E era a moça sobremaneira formosa; e tinha cuidado do rei, e o servia; porém o rei não a conheceu.'),
('acf','1rs',1,5,'Então Adonias, filho de Hagite, se levantou, dizendo: Eu reinarei. E preparou carros, e cavaleiros, e cinqüenta homens, que corressem adiante dele.'),
('acf','1rs',1,6,'E nunca seu pai o tinha contrariado, dizendo: Por que fizeste assim? E era ele também muito formoso de parecer; e Hagite o tivera depois de Absalão.'),
('acf','1rs',1,7,'E tinha entendimento com Joabe, filho de Zeruia, e com Abiatar o sacerdote; os quais o ajudavam, seguindo a Adonias.'),
('acf','1rs',1,8,'Porém Zadoque, o sacerdote, e Benaia, filho de Joiada, e Natã, o profeta, e Simei, e Rei, e os poderosos que Davi tinha, não estavam com Adonias.'),
('acf','1rs',1,9,'E matou Adonias ovelhas, e vacas, e animais cevados, junto à pedra de Zoelete, que está perto da fonte de Rogel; e convidou a todos os seus irmãos, os filhos do rei, e a todos os homens de Judá, servos do rei.'),
('acf','1rs',1,10,'Porém a Natã, o profeta, e a Benaia, e aos poderosos, e a Salomão, seu irmão, não convidou.'),
('acf','1rs',1,11,'Então falou Natã a Bate-Seba, mãe de Salomão, dizendo: Não ouviste que Adonias, filho de Hagite, reina? E que nosso senhor Davi não o sabe?'),
('acf','1rs',1,12,'Vem, pois, agora, e deixa-me dar-te um conselho, para que salves a tua vida, e a de Salomão teu filho.'),
('acf','1rs',1,13,'Vai, e chega ao rei Davi, e dize-lhe: Não juraste tu, rei senhor meu, à tua serva, dizendo: Certamente teu filho Salomão reinará depois de mim, e ele se assentará no meu trono? Por que, pois, reina Adonias?'),
('acf','1rs',1,14,'Eis que, estando tu ainda aí falando com o rei, eu também entrarei depois de ti, e confirmarei as tuas palavras.'),
('acf','1rs',1,15,'E foi Bate-Seba ao rei na sua câmara; e o rei era muito velho; e Abisague, a sunamita, servia ao rei.'),
('acf','1rs',1,16,'E Bate-Seba inclinou a cabeça, e se prostrou perante o rei; e disse o rei: Que tens?'),
('acf','1rs',1,17,'E ela lhe disse: Senhor meu, tu juraste à tua serva pelo Senhor teu Deus, dizendo: Salomão, teu filho, reinará depois de mim, e ele se assentará no meu trono.'),
('acf','1rs',1,18,'E agora eis que Adonias reina; e tu, ó rei meu senhor, não o sabes.'),
('acf','1rs',1,19,'E matou vacas, e animais cevados, e ovelhas em abundância, e convidou a todos os filhos do rei, e a Abiatar, o sacerdote, e a Joabe, capitão do exército, mas a teu servo Salomão não convidou.'),
('acf','1rs',1,20,'Porém, ó rei meu senhor, os olhos de todo o Israel estão sobre ti, para que lhe declares quem se assentará sobre o trono do rei meu senhor, depois dele.'),
('acf','1rs',1,21,'De outro modo sucederá que, quando o rei meu senhor dormir com seus pais, eu e Salomão meu filho seremos os culpados.'),
('acf','1rs',1,22,'E, estando ela ainda falando com o rei, eis que entra o profeta Natã.'),
('acf','1rs',1,23,'E o fizeram saber ao rei, dizendo: Eis aí está o profeta Natã. E entrou à presença do rei, e prostrou-se diante dele com o rosto em terra.'),
('acf','1rs',1,24,'E disse Natã: Ó rei meu senhor, disseste tu: Adonias reinará depois de mim, e ele se assentará sobre o meu trono?'),
('acf','1rs',1,25,'Porque hoje desceu, e matou vacas, e animais cevados, e ovelhas em abundância, e convidou a todos os filhos do rei e aos capitães do exército, e a Abiatar, o sacerdote, e eis que estão comendo e bebendo perante ele; e dizem: Viva o rei Adonias.'),
('acf','1rs',1,26,'Porém a mim, sendo eu teu servo, e a Zadoque, o sacerdote, e a Benaia, filho de Joiada, e a Salomão, teu servo, não convidou.'),
('acf','1rs',1,27,'Foi feito isto da parte do rei meu senhor? E não fizeste saber a teu servo quem se assentaria no trono do rei meu senhor depois dele?'),
('acf','1rs',1,28,'E respondeu o rei Davi, e disse: Chamai-me a Bate-Seba. E ela entrou à presença do rei; e ficou em pé diante do rei.'),
('acf','1rs',1,29,'Então jurou o rei e disse: Vive o Senhor, o qual remiu a minha alma de toda a angústia,'),
('acf','1rs',1,30,'Que, como te jurei pelo Senhor Deus de Israel, dizendo: Certamente teu filho Salomão reinará depois de mim, e ele se assentará no meu trono, em meu lugar, assim o farei no dia de hoje.'),
('acf','1rs',1,31,'Então Bate-Seba se inclinou com o rosto em terra e se prostrou diante do rei, e disse: Viva o rei Davi meu senhor para sempre.'),
('acf','1rs',1,32,'E disse o rei Davi: Chamai-me a Zadoque, o sacerdote, e a Natã, o profeta, e a Benaia, filho de Joiada. E eles entraram à presença do rei.'),
('acf','1rs',1,33,'E o rei lhes disse: Tomai convosco os servos de vosso senhor, e fazei subir a meu filho Salomão na mula que é minha; e levai-o a Giom.'),
('acf','1rs',1,34,'E Zadoque, o sacerdote, com Natã, o profeta, ali o ungirão rei sobre Israel; então tocareis a trombeta, e direis: Viva o rei Salomão!'),
('acf','1rs',1,35,'Então subireis após ele, e virá e se assentará no meu trono, e ele reinará em meu lugar; porque tenho ordenado que ele seja guia sobre Israel e sobre Judá.'),
('acf','1rs',1,36,'Então Benaia, filho de Joiada, respondeu ao rei, e disse: Amém; assim o diga o SENHOR Deus do rei meu senhor.'),
('acf','1rs',1,37,'Como o SENHOR foi com o rei meu senhor, assim o seja com Salomão, e faça que o seu trono seja maior do que o trono do rei Davi meu senhor.'),
('acf','1rs',1,38,'Então desceu Zadoque, o sacerdote, e Natã, o profeta, e Benaia, filho de Joiada, e os quereteus, e os peleteus, e fizeram montar a Salomão na mula do rei Davi, e o levaram a Giom.'),
('acf','1rs',1,39,'E Zadoque, o sacerdote, tomou o chifre de azeite do tabernáculo, e ungiu a Salomão; e tocaram a trombeta, e todo o povo disse: Viva o rei Salomão!'),
('acf','1rs',1,40,'E todo o povo subiu após ele, e o povo tocava gaitas, e alegrava-se com grande alegria; de maneira que com o seu clamor a terra retiniu.'),
('acf','1rs',1,41,'E o ouviu Adonias, e todos os convidados que estavam com ele, que tinham acabado de comer; também Joabe ouviu o sonido das trombetas, e disse: Por que há tal ruído de cidade alvoroçada?'),
('acf','1rs',1,42,'Estando ele ainda falando, eis que vem Jônatas, filho de Abiatar, o sacerdote, e disse Adonias: Entra, porque és homem valente, e trarás boas novas.'),
('acf','1rs',1,43,'E respondeu Jônatas, e disse a Adonias: Certamente nosso senhor, rei Davi, constituiu rei a Salomão;'),
('acf','1rs',1,44,'E o rei enviou com ele a Zadoque, o sacerdote, e a Natã, o profeta, e a Benaia, filho de Joiada, e aos quereteus e aos peleteus; e o fizeram montar na mula do rei.'),
('acf','1rs',1,45,'E Zadoque, o sacerdote, e Natã, o profeta, o ungiram rei em Giom, e dali subiram alegres, e a cidade está alvoroçada; este é o clamor que ouviste.'),
('acf','1rs',1,46,'E também Salomão está assentado no trono do reino.'),
('acf','1rs',1,47,'E também os servos do rei vieram abençoar a nosso senhor, o rei Davi, dizendo: Faça teu Deus que o nome de Salomão seja melhor do que o teu nome; e faça que o seu trono seja maior do que o teu trono. E o rei se inclinou no leito.'),
('acf','1rs',1,48,'E também disse o rei assim: Bendito o Senhor Deus de Israel, que hoje tem dado quem se assente no meu trono, e que os meus olhos o vissem.'),
('acf','1rs',1,49,'Então estremeceram e se levantaram todos os convidados que estavam com Adonias; e cada um se foi ao seu caminho.'),
('acf','1rs',1,50,'Porém Adonias temeu a Salomão; e levantou-se, e foi, e apegou-se às pontas do altar.'),
('acf','1rs',1,51,'E fez-se saber a Salomão, dizendo: Eis que Adonias teme ao rei Salomão; porque eis que apegou-se às pontas do altar, dizendo: Jure-me hoje o rei Salomão que não matará o seu servo à espada.'),
('acf','1rs',1,52,'E disse Salomão: Se for homem de bem, nem um de seus cabelos cairá em terra; se, porém, se achar nele maldade, morrerá.'),
('acf','1rs',1,53,'E mandou o rei Salomão, e o fizeram descer do altar; e veio, e prostrou-se perante o rei Salomão, e Salomão lhe disse: Vai para tua casa.'),
('acf','1rs',2,1,'E aproximaram-se os dias da morte de Davi; e deu ele ordem a Salomão, seu filho, dizendo:'),
('acf','1rs',2,2,'Eu vou pelo caminho de toda a terra; esforça-te, pois, e sê homem.'),
('acf','1rs',2,3,'E guarda a ordenança do Senhor teu Deus, para andares nos seus caminhos, e para guardares os seus estatutos, e os seus mandamentos, e os seus juízos, e os seus testemunhos, como está escrito na lei de Moisés; para que prosperes em tudo quanto fizeres, e para onde quer que fores.'),
('acf','1rs',2,4,'Para que o Senhor confirme a palavra, que falou de mim, dizendo: Se teus filhos guardarem o seu caminho, para andarem perante a minha face fielmente, com todo o seu coração e com toda a sua alma, nunca, disse, te faltará sucessor ao trono de Israel.'),
('acf','1rs',2,5,'E também tu sabes o que me fez Joabe, filho de Zeruia, e o que fez aos dois capitães do exército de Israel, a Abner filho de Ner, e a Amasa, filho de Jeter, os quais matou, e em paz derramou o sangue de guerra, e pôs o sangue de guerra no cinto que tinha nos lombos, e nos sapatos que trazia nos pés.'),
('acf','1rs',2,6,'Faze, pois, segundo a tua sabedoria, e não permitas que suas cãs desçam à sepultura em paz.'),
('acf','1rs',2,7,'Porém com os filhos de Barzilai, o gileadita, usarás de beneficência, e estarão entre os que comem à tua mesa, porque assim se chegaram eles a mim, quando eu fugia por causa de teu irmão Absalão.'),
('acf','1rs',2,8,'E eis que também contigo está Simei, filho de Gera, filho de Benjamim, de Baurim, que me maldisse com maldição atroz, no dia em que ia a Maanaim; porém ele saiu a encontrar-se comigo junto ao Jordão, e eu pelo Senhor lhe jurei, dizendo que o não mataria à espada.'),
('acf','1rs',2,9,'Mas agora não o tenhas por inculpável, pois és homem sábio, e bem saberás o que lhe hás de fazer para que faças com que as suas cãs desçam à sepultura com sangue.'),
('acf','1rs',2,10,'E Davi dormiu com seus pais, e foi sepultado na cidade de Davi.'),
('acf','1rs',2,11,'E foram os dias que Davi reinou sobre Israel quarenta anos: sete anos reinou em Hebrom, e em Jerusalém reinou trinta e três anos.'),
('acf','1rs',2,12,'E Salomão se assentou no trono de Davi, seu pai, e o seu reino se fortificou sobremaneira.'),
('acf','1rs',2,13,'Então veio Adonias, filho de Hagite, a Bate-Seba, mãe de Salomão; e disse ela: De paz é a tua vinda? E ele disse: É de paz.'),
('acf','1rs',2,14,'Então disse ele: Uma palavra tenho que dizer-te. E ela disse: Fala.'),
('acf','1rs',2,15,'Disse, pois, ele: Bem sabes que o reino era meu, e todo o Israel tinha posto a vista em mim para que eu viesse a reinar, contudo o reino foi transferido e veio a ser de meu irmão, porque foi feito seu pelo Senhor.'),
('acf','1rs',2,16,'Assim que agora uma só petição te faço; não ma rejeites. E ela lhe disse: Fala.'),
('acf','1rs',2,17,'E ele disse: Peço-te que fales ao rei Salomão (porque ele não te rejeitará) que me dê por mulher a Abisague, a sunamita.'),
('acf','1rs',2,18,'E disse Bate-Seba: Bem, eu falarei por ti ao rei.'),
('acf','1rs',2,19,'Assim foi Bate-Seba ao rei Salomão, a falar-lhe por Adonias; e o rei se levantou a encontrar-se com ela, e se inclinou diante dela; então se assentou no seu trono, e fez pôr uma cadeira para a sua mãe, e ela se assentou à sua direita.'),
('acf','1rs',2,20,'Então disse ela: Só uma pequena petição te faço; não ma rejeites. E o rei lhe disse: Pede, minha mãe, porque não ta negarei.'),
('acf','1rs',2,21,'E ela disse: Dê-se Abisague, a sunamita, a Adonias, teu irmão, por mulher.'),
('acf','1rs',2,22,'Então respondeu o rei Salomão, e disse a sua mãe: E por que pedes a Abisague, a sunamita, para Adonias? Pede também para ele o reino (porque é meu irmão maior), para ele, digo, e também para Abiatar, sacerdote, e para Joabe, filho de Zeruia.'),
('acf','1rs',2,23,'E jurou o rei Salomão pelo Senhor, dizendo: Assim Deus me faça, e outro tanto, se não falou Adonias esta palavra contra a sua vida.'),
('acf','1rs',2,24,'Agora, pois, vive o Senhor, que me confirmou, e me fez assentar no trono de Davi, meu pai, e que me tem feito casa, como tinha falado, que hoje morrerá Adonias.'),
('acf','1rs',2,25,'E enviou o rei Salomão pela mão de Benaia, filho de Joiada, o qual arremeteu contra ele de modo que morreu.'),
('acf','1rs',2,26,'E a Abiatar, o sacerdote, disse o rei: Vai para Anatote, para os teus campos, porque és homem digno de morte; porém hoje não te matarei, porquanto levaste a arca do Senhor DEUS diante de Davi, meu pai, e porquanto foste aflito em tudo quanto meu pai foi aflito.'),
('acf','1rs',2,27,'Lançou, pois, Salomão fora a Abiatar, para que não fosse sacerdote do Senhor, para cumprir a palavra do Senhor, que tinha falado sobre a casa de Eli em Siló.'),
('acf','1rs',2,28,'E chegou a notícia até Joabe (porque Joabe tinha se desviado seguindo a Adonias, ainda que não tinha se desviado seguindo a Absalão), e Joabe fugiu para o tabernáculo do Senhor, e apegou-se às pontas do altar.'),
('acf','1rs',2,29,'E disseram ao rei Salomão que Joabe tinha fugido para o tabernáculo do Senhor; e eis que está junto ao altar; então Salomão enviou Benaia, filho de Joiada, dizendo: Vai, arremete sobre ele.'),
('acf','1rs',2,30,'E foi Benaia ao tabernáculo do Senhor, e lhe disse: Assim diz o rei: Sai daí. E disse ele: Não, porém aqui morrerei. E Benaia tornou com a resposta ao rei, dizendo: Assim falou Joabe, e assim me respondeu.'),
('acf','1rs',2,31,'E disse-lhe o rei: Faze como ele disse, e arremete contra ele, e sepulta-o, para que tires de mim e da casa de meu pai o sangue que Joabe sem causa derramou.'),
('acf','1rs',2,32,'Assim o Senhor fará recair o sangue dele sobre a sua cabeça, porque deu sobre dois homens mais justos e melhores do que ele, e os matou à espada, sem que meu pai Davi o soubesse, a saber: a Abner, filho de Ner, capitão do exército de Israel, e a Amasa, filho de Jeter, capitão do exército de Judá.'),
('acf','1rs',2,33,'Assim recairá o sangue destes sobre a cabeça de Joabe e sobre a cabeça da sua descendência para sempre; mas a Davi, e à sua descendência, e à sua casa, e ao seu trono, dará o Senhor paz para todo o sempre.'),
('acf','1rs',2,34,'E subiu Benaia, filho de Joiada, e arremeteu contra ele, e o matou; e foi sepultado em sua casa, no deserto.'),
('acf','1rs',2,35,'E o rei pôs a Benaia, filho de Joiada, em seu lugar sobre o exército, e a Zadoque, o sacerdote, pôs o rei em lugar de Abiatar.'),
('acf','1rs',2,36,'Depois mandou o rei, e chamou a Simei, e disse-lhe: Edifica-te uma casa em Jerusalém, e habita aí, e daí não saias, nem para uma nem para outra parte.'),
('acf','1rs',2,37,'Porque há de ser que no dia em que saíres e passares o ribeiro de Cedrom, de certo que sem dúvida morrerás; o teu sangue será sobre a tua cabeça.'),
('acf','1rs',2,38,'E Simei disse ao rei: Boa é essa palavra; como tem falado o rei meu senhor, assim fará o teu servo. E Simei habitou em Jerusalém muitos dias.'),
('acf','1rs',2,39,'Sucedeu, porém, que, ao cabo de três anos, dois servos de Simei fugiram para Aquis, filho de Maaca, rei de Gate; e deram parte a Simei, dizendo: Eis que teus servos estão em Gate.'),
('acf','1rs',2,40,'Então Simei se levantou, e albardou o seu jumento, e foi a Gate, ter com Aquis, em busca de seus servos; assim foi Simei, e trouxe os seus servos de Gate.'),
('acf','1rs',2,41,'E disseram a Salomão como Simei fora de Jerusalém a Gate, e já tinha voltado.'),
('acf','1rs',2,42,'Então o rei mandou chamar a Simei, e disse-lhe: Não te conjurei eu pelo Senhor, e protestei contra ti, dizendo: No dia em que saíres para uma ou outra parte, sabe de certo que, sem dúvida, morrerás? E tu me disseste: Boa é essa palavra que ouvi.'),
('acf','1rs',2,43,'Por que, pois, não guardaste o juramento do Senhor, nem a ordem que te dei?'),
('acf','1rs',2,44,'Disse mais o rei a Simei: Bem sabes tu toda a maldade que o teu coração reconhece, que fizeste a Davi, meu pai; pelo que o Senhor fez recair a tua maldade sobre a tua cabeça.'),
('acf','1rs',2,45,'Mas o rei Salomão será abençoado, e o trono de Davi será confirmado perante o Senhor para sempre.'),
('acf','1rs',2,46,'E o rei mandou a Benaia, filho de Joiada, o qual saiu, e arremeteu contra ele, de modo que morreu; assim foi confirmado o reino na mão de Salomão.'),
('acf','1rs',3,1,'E Salomão se aparentou com Faraó, rei do Egito; e tomou a filha de Faraó, e a trouxe à cidade de Davi, até que acabasse de edificar a sua casa, e a casa do SENHOR, e a muralha de Jerusalém em redor.'),
('acf','1rs',3,2,'Entretanto, o povo sacrificava sobre os altos; porque até àqueles dias ainda não se havia edificado casa ao nome do Senhor.'),
('acf','1rs',3,3,'E Salomão amava ao Senhor, andando nos estatutos de Davi seu pai; somente que nos altos sacrificava, e queimava incenso.'),
('acf','1rs',3,4,'E foi o rei a Gibeom para lá sacrificar, porque aquele era o alto maior; mil holocaustos sacrificou Salomão naquele altar.'),
('acf','1rs',3,5,'E em Gibeom apareceu o Senhor a Salomão de noite em sonhos; e disse-lhe Deus: Pede o que queres que eu te dê.'),
('acf','1rs',3,6,'E disse Salomão: De grande beneficência usaste tu com teu servo Davi, meu pai, como também ele andou contigo em verdade, e em justiça, e em retidão de coração, perante a tua face; e guardaste-lhe esta grande beneficência, e lhe deste um filho que se assentasse no seu trono, como se vê neste dia.'),
('acf','1rs',3,7,'Agora, pois, ó Senhor meu Deus, tu fizeste reinar a teu servo em lugar de Davi meu pai; e sou apenas um menino pequeno; não sei como sair, nem como entrar.'),
('acf','1rs',3,8,'E teu servo está no meio do teu povo que elegeste; povo grande, que nem se pode contar, nem numerar, pela sua multidão.'),
('acf','1rs',3,9,'A teu servo, pois, dá um coração entendido para julgar a teu povo, para que prudentemente discirna entre o bem e o mal; porque quem poderia julgar a este teu tão grande povo?'),
('acf','1rs',3,10,'E esta palavra pareceu boa aos olhos do Senhor, de que Salomão pedisse isso.'),
('acf','1rs',3,11,'E disse-lhe Deus: Porquanto pediste isso, e não pediste para ti muitos dias, nem pediste para ti riquezas, nem pediste a vida de teus inimigos; mas pediste para ti entendimento, para discernires o que é justo;'),
('acf','1rs',3,12,'Eis que fiz segundo as tuas palavras; eis que te dei um coração tão sábio e entendido, que antes de ti igual não houve, e depois de ti igual não se levantará.'),
('acf','1rs',3,13,'E também até o que não pediste te dei, assim riquezas como glória; de modo que não haverá um igual entre os reis, por todos os teus dias.'),
('acf','1rs',3,14,'E, se andares nos meus caminhos, guardando os meus estatutos, e os meus mandamentos, como andou Davi teu pai, também prolongarei os teus dias.'),
('acf','1rs',3,15,'E acordou Salomão, e eis que era sonho. E indo a Jerusalém, pôs-se perante a arca da aliança do Senhor, e sacrificou holocausto, e preparou sacrifícios pacíficos, e fez um banquete a todos os seus servos.'),
('acf','1rs',3,16,'Então vieram duas mulheres prostitutas ao rei, e se puseram perante ele.'),
('acf','1rs',3,17,'E disse-lhe uma das mulheres: Ah! senhor meu, eu e esta mulher moramos numa casa; e tive um filho, estando com ela naquela casa.'),
('acf','1rs',3,18,'E sucedeu que, ao terceiro dia, depois do meu parto, teve um filho também esta mulher; estávamos juntas; nenhum estranho estava conosco na casa; somente nós duas naquela casa.'),
('acf','1rs',3,19,'E de noite morreu o filho desta mulher, porquanto se deitara sobre ele.'),
('acf','1rs',3,20,'E levantou-se à meia-noite, e tirou o meu filho do meu lado, enquanto dormia a tua serva, e o deitou no seu seio; e a seu filho morto deitou no meu seio.'),
('acf','1rs',3,21,'E, levantando-me eu pela manhã, para dar de mamar a meu filho, eis que estava morto; mas, atentando pela manhã para ele, eis que não era meu filho, que eu havia tido.'),
('acf','1rs',3,22,'Então disse a outra mulher: Não, mas o vivo é meu filho, e teu filho o morto. Porém esta disse: Não, por certo, o morto é teu filho, e meu filho o vivo. Assim falaram perante o rei.'),
('acf','1rs',3,23,'Então disse o rei: Esta diz: Este que vive é meu filho, e teu filho o morto; e esta outra diz: Não, por certo, o morto é teu filho e meu filho o vivo.'),
('acf','1rs',3,24,'Disse mais o rei: Trazei-me uma espada. E trouxeram uma espada diante do rei.'),
('acf','1rs',3,25,'E disse o rei: Dividi em duas partes o menino vivo; e dai metade a uma, e metade a outra.'),
('acf','1rs',3,26,'Mas a mulher, cujo filho era o vivo, falou ao rei (porque as suas entranhas se lhe enterneceram por seu filho), e disse: Ah! senhor meu, dai-lhe o menino vivo, e de modo nenhum o mateis. Porém a outra dizia: Nem teu nem meu seja; dividi-o.'),
('acf','1rs',3,27,'Então respondeu o rei, e disse: Dai a esta o menino vivo, e de maneira nenhuma o mateis, porque esta é sua mãe.'),
('acf','1rs',3,28,'E todo o Israel ouviu o juízo que havia dado o rei, e temeu ao rei; porque viram que havia nele a sabedoria de Deus, para fazer justiça.'),
('acf','1rs',4,1,'Assim foi Salomão rei sobre todo o Israel.'),
('acf','1rs',4,2,'E estes eram os príncipes que tinha: Azarias, filho de Zadoque, sacerdote;'),
('acf','1rs',4,3,'Eliorefe e Aías, filhos de Sisa, secretários; Jeosafá, filho de Ailude, cronista;'),
('acf','1rs',4,4,'Benaia, filho de Joiada, sobre o exército; e Zadoque e Abiatar eram sacerdotes;'),
('acf','1rs',4,5,'E Azarias, filho de Natã, sobre os provedores; e Zabude, filho de Natã, oficial-mor, amigo do rei;'),
('acf','1rs',4,6,'E Aisar, mordomo; Adonirão, filho de Abda, sobre o tributo.'),
('acf','1rs',4,7,'E tinha Salomão doze oficiais sobre todo o Israel, que proviam ao rei e à sua casa; e cada um tinha que abastecê-lo por um mês no ano.'),
('acf','1rs',4,8,'E estes são os seus nomes: Ben-Hur, nas montanhas de Efraim;'),
('acf','1rs',4,9,'Ben-Dequer em Macaz, e em Saalbim, e em Bete-Semes, e em Elom, e em Bete-Hanã;'),
('acf','1rs',4,10,'Ben-Hesede em Arubote; também este tinha a Socó e a toda a terra de Hefer;'),
('acf','1rs',4,11,'Ben-Abinadabe em todo o termo de Dor; tinha este a Tafate, filha de Salomão, por mulher;'),
('acf','1rs',4,12,'Baana, filho de Ailude, tinha a Taanaque, e a Megido, e a toda a Bete-Seã, que está junto a Zaretã, abaixo de Jizreel, desde Bete-Seã até Abel-Meolá, para além de Jocmeão;'),
('acf','1rs',4,13,'O filho de Geber, em Ramote de Gileade; tinha este as aldeias de Jair, filho de Manassés, as quais estão em Gileade; também tinha o termo de Argobe, o qual está em Basã, sessenta grandes cidades, com muros e ferrolhos de cobre;'),
('acf','1rs',4,14,'Ainadabe, filho de Ido, em Maanaim.'),
('acf','1rs',4,15,'Aimaás em Naftali; também este tomou a Basemate, filha de Salomão, por mulher;'),
('acf','1rs',4,16,'Baaná, filho de Husai, em Aser e em Alote;'),
('acf','1rs',4,17,'Jeosafá, filho de Parua, em Issacar;'),
('acf','1rs',4,18,'Simei, filho de Elá, em Benjamim:'),
('acf','1rs',4,19,'Geber, filho de Uri, na terra de Gileade, a terra de Siom, rei dos amorreus, e de Ogue, rei de Basã; e só uma guarnição havia naquela terra.'),
('acf','1rs',4,20,'Eram, pois, os de Judá e Israel muitos, como a areia que está junto ao mar em multidão, comendo, e bebendo, e alegrando-se.'),
('acf','1rs',4,21,'E dominava Salomão sobre todos os reinos desde o rio até à terra dos filisteus, e até ao termo do Egito; os quais traziam presentes, e serviram a Salomão todos os dias da sua vida.'),
('acf','1rs',4,22,'Era, pois, o provimento de Salomão cada dia, trinta coros de flor de farinha, e sessenta coros de farinha;'),
('acf','1rs',4,23,'Dez bois cevados, e vinte bois de pasto, e cem carneiros; afora os veados e as cabras montesas, e os corços, e aves cevadas.'),
('acf','1rs',4,24,'Porque dominava sobre tudo quanto havia do lado de cá do rio, Tifsa até Gaza, sobre todos os reis do lado de cá do rio; e tinha paz de todos os lados em redor dele.'),
('acf','1rs',4,25,'E Judá e Israel habitavam seguros, cada um debaixo da sua videira, e debaixo da sua figueira, desde Dã até Berseba, todos os dias de Salomão.'),
('acf','1rs',4,26,'Tinha também Salomão quarenta mil estrebarias de cavalos para os seus carros, e doze mil cavaleiros.'),
('acf','1rs',4,27,'Proviam, pois, estes provedores, cada um no seu mês, ao rei Salomão e a todos quantos se chegaram à mesa do rei Salomão; coisa nenhuma deixavam faltar.'),
('acf','1rs',4,28,'E traziam a cevada e a palha para os cavalos e para os ginetes, para o lugar onde estava, cada um segundo o seu cargo.'),
('acf','1rs',4,29,'E deu Deus a Salomão sabedoria, e muitíssimo entendimento, e largueza de coração, como a areia que está na praia do mar.'),
('acf','1rs',4,30,'E era a sabedoria de Salomão maior do que a sabedoria de todos os do oriente e do que toda a sabedoria dos egípcios.'),
('acf','1rs',4,31,'E era ele ainda mais sábio do que todos os homens, e do que Etã, ezraíta, e Hemã, e Calcol, e Darda, filhos de Maol; e correu o seu nome por todas as nações em redor.'),
('acf','1rs',4,32,'E disse três mil provérbios, e foram os seus cânticos mil e cinco.'),
('acf','1rs',4,33,'Também falou das árvores, desde o cedro que está no Líbano até ao hissopo que nasce na parede; também falou dos animais e das aves, e dos répteis e dos peixes.'),
('acf','1rs',4,34,'E vinham de todos os povos a ouvir a sabedoria de Salomão, e de todos os reis da terra que tinham ouvido da sua sabedoria.'),
('acf','1rs',5,1,'E enviou Hirão, rei de Tiro, os seus servos a Salomão (porque ouvira que ungiram a Salomão rei em lugar de seu pai), porquanto Hirão sempre tinha amado a Davi.'),
('acf','1rs',5,2,'Então Salomão mandou dizer a Hirão:'),
('acf','1rs',5,3,'Bem sabes tu que Davi, meu pai, não pôde edificar uma casa ao nome do Senhor seu Deus, por causa da guerra com que o cercaram, até que o Senhor pôs seus inimigos debaixo das plantas dos seus pés.'),
('acf','1rs',5,4,'Porém agora o Senhor meu Deus me tem dado descanso de todos os lados; adversário não há, nem algum mau encontro.'),
('acf','1rs',5,5,'E eis que eu intento edificar uma casa ao nome do Senhor meu Deus, como falou o Senhor a Davi, meu pai, dizendo: Teu filho, que porei em teu lugar no teu trono, ele edificará uma casa ao meu nome.'),
('acf','1rs',5,6,'Dá ordem, pois, agora, que do Líbano me cortem cedros, e os meus servos estarão com os teus servos, e eu te darei o salário dos teus servos, conforme a tudo o que disseres; porque bem sabes tu que entre nós ninguém há que saiba cortar a madeira como os sidônios.'),
('acf','1rs',5,7,'E aconteceu que, ouvindo Hirão as palavras de Salomão, muito se alegrou, e disse: Bendito seja hoje o Senhor, que deu a Davi um filho sábio sobre este tão grande povo.'),
('acf','1rs',5,8,'E enviou Hirão a Salomão, dizendo: Ouvi o que me mandaste dizer. Eu farei toda a tua vontade acerca das madeiras de cedro e de cipreste.'),
('acf','1rs',5,9,'Os meus servos as levarão desde o Líbano até ao mar, e eu as farei conduzir em jangadas pelo mar até ao lugar que me designares, e ali as desamarrarei; e tu as tomarás; tu também farás a minha vontade, dando sustento à minha casa.'),
('acf','1rs',5,10,'Assim deu Hirão a Salomão madeira de cedro e madeira de cipreste, conforme a toda a sua vontade.'),
('acf','1rs',5,11,'E Salomão deu a Hirão vinte mil coros de trigo, para sustento da sua casa, e vinte coros de azeite batido; isto dava Salomão a Hirão anualmente.'),
('acf','1rs',5,12,'Deu, pois, o Senhor a Salomão sabedoria, como lhe tinha falado; e houve paz entre Hirão e Salomão, e ambos fizeram acordo.'),
('acf','1rs',5,13,'E o rei Salomão fez subir uma leva de gente dentre todo o Israel, e foi a leva de gente trinta mil homens;'),
('acf','1rs',5,14,'E os enviava ao Líbano, cada mês, dez mil por turno; um mês estavam no Líbano, e dois meses cada um em sua casa; e Adonirão estava sobre a leva de gente.'),
('acf','1rs',5,15,'Tinha também Salomão setenta mil que levavam as cargas, e oitenta mil que talhavam pedras nas montanhas,'),
('acf','1rs',5,16,'Afora os chefes dos oficiais de Salomão, que estavam sobre aquela obra, três mil e trezentos, os quais davam as ordens ao povo que fazia aquela obra.'),
('acf','1rs',5,17,'E mandou o rei que trouxessem pedras grandes, e pedras valiosas, pedras lavradas, para fundarem a casa.'),
('acf','1rs',5,18,'E as lavraram os edificadores de Hirão, e os giblitas; e preparavam a madeira e as pedras para edificar a casa.'),
('acf','1rs',6,1,'E sucedeu que no ano de quatrocentos e oitenta, depois de saírem os filhos de Israel do Egito, no ano quarto do reinado de Salomão sobre Israel, no mês de Zive (este é o mês segundo), começou a edificar a casa do SENHOR.'),
('acf','1rs',6,2,'E a casa que o rei Salomão edificou ao Senhor era de sessenta côvados de comprimento, e de vinte côvados de largura, e de trinta côvados de altura.'),
('acf','1rs',6,3,'E o pórtico diante do templo da casa era de vinte côvados de comprimento, segundo a largura da casa, e de dez côvados de largura diante da casa.'),
('acf','1rs',6,4,'E fez para a casa janelas de gelósias fixas.'),
('acf','1rs',6,5,'E edificou câmaras junto ao muro da casa, contra as paredes da casa, em redor, tanto do templo como do oráculo; e assim lhe fez câmaras laterais em redor.'),
('acf','1rs',6,6,'A câmara de baixo era de cinco côvados de largura, e a do meio de seis côvados de largura, e a terceira de sete côvados de largura; porque pela parte de fora da casa, em redor, fizera encostos, para que as vigas não se apoiassem nas paredes da casa.'),
('acf','1rs',6,7,'E edificava-se a casa com pedras preparadas, como as traziam se edificava; de maneira que nem martelo, nem machado, nem nenhum outro instrumento de ferro se ouviu na casa quando a edificavam.'),
('acf','1rs',6,8,'A porta da câmara do meio estava ao lado direito da casa, e por caracóis se subia à do meio, e da do meio à terceira.'),
('acf','1rs',6,9,'Assim, pois, edificou a casa, e a acabou; e cobriu a casa com pranchões e tabuados de cedro.'),
('acf','1rs',6,10,'Também edificou as câmaras em volta de toda a casa, de cinco côvados de altura, e as ligou à casa com madeira de cedro.'),
('acf','1rs',6,11,'Então veio a palavra do Senhor a Salomão, dizendo:'),
('acf','1rs',6,12,'Quanto a esta casa que tu edificas, se andares nos meus estatutos, e fizeres os meus juízos, e guardares todos os meus mandamentos, andando neles, confirmarei para contigo a minha palavra, a qual falei a Davi, teu pai;'),
('acf','1rs',6,13,'E habitarei no meio dos filhos de Israel, e não desampararei o meu povo de Israel.'),
('acf','1rs',6,14,'Assim edificou Salomão aquela casa, e a acabou.'),
('acf','1rs',6,15,'Também cobriu as paredes da casa por dentro com tábuas de cedro; desde o soalho da casa até ao teto tudo cobriu com madeira por dentro; e cobriu o soalho da casa com tábuas de cipreste.'),
('acf','1rs',6,16,'Edificou mais vinte côvados de tábuas de cedro nos lados da casa, desde o soalho até às paredes; e por dentro lhas edificou para o oráculo, para o Santo dos Santos.'),
('acf','1rs',6,17,'A casa, isto é, o templo anterior tinha quarenta côvados.'),
('acf','1rs',6,18,'E o cedro da casa por dentro era lavrado de botões e flores abertas; tudo era cedro, pedra nenhuma se via.'),
('acf','1rs',6,19,'E por dentro da casa, na parte mais interior, preparou o oráculo, para pôr ali a arca da aliança do Senhor.'),
('acf','1rs',6,20,'E o oráculo no interior era de vinte côvados de comprimento, e de vinte côvados de largura, e de vinte côvados de altura; e o revestiu de ouro puro; também revestiu de cedro o altar.'),
('acf','1rs',6,21,'E revestiu Salomão a casa por dentro de ouro puro; e com cadeias de ouro pôs uma cortina diante do oráculo, e o revestiu com ouro.'),
('acf','1rs',6,22,'Assim cobriu de ouro toda a casa, inteiramente; também cobriu de ouro todo o altar que estava diante do oráculo.'),
('acf','1rs',6,23,'E no oráculo fez dois querubins de madeira de oliveira, cada um da altura de dez côvados.'),
('acf','1rs',6,24,'E uma asa de um querubim era de cinco côvados, e a outra asa do querubim de outros cinco côvados; dez côvados havia desde a extremidade de uma das suas asas até à extremidade da outra das suas asas.'),
('acf','1rs',6,25,'Assim era também de dez côvados o outro querubim; ambos os querubins eram de uma mesma medida e de um mesmo talhe.'),
('acf','1rs',6,26,'A altura de um querubim era de dez côvados, e assim a do outro querubim.'),
('acf','1rs',6,27,'E pôs a estes querubins no meio da casa de dentro; e os querubins estendiam as asas, de maneira que a asa de um tocava na parede, e a asa do outro querubim tocava na outra parede; e as suas asas no meio da casa tocavam uma na outra.'),
('acf','1rs',6,28,'E revestiu de ouro os querubins.'),
('acf','1rs',6,29,'E todas as paredes da casa, em redor, lavrou de esculturas e entalhes de querubins, e de palmas, e de flores abertas, por dentro e por fora.'),
('acf','1rs',6,30,'Também revestiu de ouro o soalho da casa, por dentro e por fora.'),
('acf','1rs',6,31,'E à entrada do oráculo fez portas de madeira de oliveira; o umbral de cima com as ombreiras faziam a quinta parte da parede.'),
('acf','1rs',6,32,'Também as duas portas eram de madeira de oliveira; e lavrou nelas entalhes de querubins, e de palmas, e de flores abertas, os quais revestiu de ouro; também estendeu ouro sobre os querubins e sobre as palmas.'),
('acf','1rs',6,33,'E assim fez à porta do templo ombreiras de madeira de oliveira, da quarta parte da parede.'),
('acf','1rs',6,34,'E eram as duas portas de madeira de cipreste; e as duas folhas de uma porta eram dobradiças, assim como eram também dobradiças as duas folhas entalhadas das outras portas.'),
('acf','1rs',6,35,'E as lavrou de querubins e de palmas, e de flores abertas, e as revestiu de ouro acomodado ao lavor.'),
('acf','1rs',6,36,'Também edificou o pátio interior de três ordens de pedras lavradas e de uma ordem de vigas de cedro.'),
('acf','1rs',6,37,'No ano quarto se pôs o fundamento da casa do Senhor, no mês de Zive.'),
('acf','1rs',6,38,'E no ano undécimo, no mês de Bul, que é o mês oitavo, se acabou esta casa com todas as suas coisas, e com tudo o que lhe convinha; e a edificou em sete anos.'),
('acf','1rs',7,1,'Porém a sua casa edificou Salomão em treze anos; e acabou toda a sua casa.'),
('acf','1rs',7,2,'Também edificou a casa do bosque do Líbano de cem côvados de comprimento, e de cinqüenta côvados de largura, e de trinta côvados de altura, sobre quatro ordens de colunas de cedro, e vigas de cedro sobre as colunas.'),
('acf','1rs',7,3,'E por cima estava coberta de cedro sobre as vigas, que estavam sobre quarenta e cinco colunas, quinze em cada ordem.'),
('acf','1rs',7,4,'E havia três ordens de janelas; e uma janela estava defronte da outra janela, em três ordens.'),
('acf','1rs',7,5,'Também todas as portas e ombreiras quadradas eram de uma mesma vista; e uma janela estava defronte da outra, em três ordens.'),
('acf','1rs',7,6,'Depois fez um pórtico de colunas de cinqüenta côvados de comprimento e de trinta côvados de largura; e o pórtico estava defronte delas, e as colunas com as grossas vigas defronte delas.'),
('acf','1rs',7,7,'Também fez o pórtico para o trono onde julgava, isto é, o pórtico do juízo, que estava revestido de cedro de soalho a soalho.'),
('acf','1rs',7,8,'E em sua casa, em que morava, havia outro pátio, por dentro do pórtico, de obra semelhante à deste; também para a filha de Faraó, que Salomão tomara por mulher, fez uma casa semelhante àquele pórtico.'),
('acf','1rs',7,9,'Todas estas coisas eram de pedras de grande valor, cortadas à medida, serradas à serra por dentro e por fora; e isto desde o fundamento até às beiras do teto, e por fora até ao grande pátio.'),
('acf','1rs',7,10,'Também estava fundado sobre pedras finas, pedras grandes; sobre pedras de dez côvados e pedras de oito côvados.'),
('acf','1rs',7,11,'E em cima delas pedras de grande valor, lavradas segundo as medidas, e madeira de cedro.'),
('acf','1rs',7,12,'Havia três ordens de pedras lavradas, com uma ordem de vigas de cedro; assim era também o pátio interior da casa do Senhor e o pórtico daquela casa.'),
('acf','1rs',7,13,'E enviou o rei Salomão um mensageiro e mandou trazer a Hirão de Tiro.'),
('acf','1rs',7,14,'Era ele filho de uma mulher viúva, da tribo de Naftali, e fora seu pai um homem de Tiro, que trabalhava em cobre; e era cheio de sabedoria, e de entendimento, e de ciência para fazer toda a obra de cobre; este veio ao rei Salomão, e fez toda a sua obra.'),
('acf','1rs',7,15,'E formou duas colunas de cobre; a altura de cada coluna era de dezoito côvados, e um fio de doze côvados cercava cada uma das colunas.'),
('acf','1rs',7,16,'Também fez dois capitéis de fundição de cobre para pôr sobre as cabeças das colunas; de cinco côvados era a altura de um capitel, e de cinco côvados a altura do outro capitel.'),
('acf','1rs',7,17,'As redes eram de malhas, as ligas de obra de cadeia para os capitéis que estavam sobre a cabeça das colunas, sete para um capitel e sete para o outro capitel.'),
('acf','1rs',7,18,'Assim fez as colunas, juntamente com duas fileiras em redor sobre uma rede, para cobrir os capitéis que estavam sobre a cabeça das romãs, assim também fez com o outro capitel.'),
('acf','1rs',7,19,'E os capitéis que estavam sobre a cabeça das colunas eram de obra de lírios no pórtico, de quatro côvados.'),
('acf','1rs',7,20,'Os capitéis, pois, sobre as duas colunas estavam também defronte, em cima da parte globular que estava junto à rede; e duzentas romãs, em fileiras em redor, estavam também sobre o outro capitel.'),
('acf','1rs',7,21,'Depois levantou as colunas no pórtico do templo; e levantando a coluna direita, pôs-lhe o nome de Jaquim; e levantando a coluna esquerda, pôs-lhe o nome de Boaz.'),
('acf','1rs',7,22,'E sobre a cabeça das colunas estava a obra de lírios; e assim se acabou a obra das colunas.'),
('acf','1rs',7,23,'Fez mais o mar de fundição, de dez côvados de uma borda até à outra borda, perfeitamente redondo, e de cinco côvados de alto; e um cordão de trinta côvados o cingia em redor.'),
('acf','1rs',7,24,'E por baixo da sua borda em redor havia botões que o cingiam; por dez côvados cercavam aquele mar em redor; duas ordens destes botões foram fundidas quando o mar foi fundido.'),
('acf','1rs',7,25,'E firmava-se sobre doze bois, três que olhavam para o norte, e três que olhavam para o ocidente, e três que olhavam para o sul, e três que olhavam para o oriente; e o mar estava em cima deles, e todas as suas partes posteriores para o lado de dentro.'),
('acf','1rs',7,26,'E a grossura era de um palmo, e a sua borda era como a de um copo, como de flor de lírios; ele levava dois mil batos.'),
('acf','1rs',7,27,'Fez também as dez bases de cobre; o comprimento de uma base de quatro côvados, e de quatro côvados a sua largura, e três côvados a sua altura.'),
('acf','1rs',7,28,'E esta era a obra das bases; tinham cintas, e as cintas estavam entre as molduras.'),
('acf','1rs',7,29,'E sobre as cintas que estavam entre as molduras havia leões, bois, e querubins, e sobre as molduras uma base por cima; e debaixo dos leões e dos bois junturas de obra estendida.'),
('acf','1rs',7,30,'E uma base tinha quatro rodas de metal, e lâminas de cobre; e os seus quatro cantos tinham suportes; debaixo da pia estavam estes suportes fundidos, do lado de cada uma das junturas.'),
('acf','1rs',7,31,'E a boca da pia estava dentro da coroa, e de um côvado por cima; e era a sua boca redonda segundo a obra da base, de côvado e meio; e também sobre a sua boca havia entalhes, e as suas cintas eram quadradas, não redondas.'),
('acf','1rs',7,32,'E as quatro rodas estavam debaixo das cintas, e os eixos das rodas na base; e era a altura de cada roda de côvado e meio.'),
('acf','1rs',7,33,'E era a obra das rodas como a obra da roda de carro; seus eixos, e suas cambas e seus cubos, e seus raios, todos eram fundidos.'),
('acf','1rs',7,34,'E havia quatro suportes aos quatro cantos de cada base; seus suportes saíam da base.'),
('acf','1rs',7,35,'E no alto de cada base havia uma peça redonda de meio côvado de altura; também sobre o alto de cada base havia asas e cintas, que saíam delas.'),
('acf','1rs',7,36,'E nas placas de seus esteios e nas suas cintas lavrou querubins, leões, e palmas, segundo o espaço de cada uma, e outros adornos em redor.'),
('acf','1rs',7,37,'Conforme a esta fez as dez bases; todas tinham uma mesma fundição, uma mesma medida, e um mesmo entalhe.'),
('acf','1rs',7,38,'Também fez dez pias de cobre; em cada pia cabiam quarenta batos, e cada pia era de quatro côvados, e sobre cada uma das dez bases estava uma pia.'),
('acf','1rs',7,39,'E pôs cinco bases à direita da casa, e cinco à esquerda da casa; porém o mar pôs ao lado direito da casa para o lado do oriente, da parte do sul.'),
('acf','1rs',7,40,'Depois fez Hirão as pias, e as pás, e as bacias; e acabou Hirão de fazer toda a obra que fez para o rei Salomão, para a casa do Senhor.'),
('acf','1rs',7,41,'A saber: as duas colunas, e os globos dos capitéis que estavam sobre a cabeça das duas colunas; e as duas redes, para cobrir os dois globos dos capitéis que estavam sobre a cabeça das colunas.'),
('acf','1rs',7,42,'E as quatrocentas romãs para as duas redes, a saber: duas carreiras de romãs para cada rede, para cobrirem os dois globos dos capitéis que estavam em cima das colunas.'),
('acf','1rs',7,43,'Juntamente com as dez bases, e as dez pias sobre as bases;'),
('acf','1rs',7,44,'Como também um mar, e os doze bois debaixo daquele mar;'),
('acf','1rs',7,45,'E os caldeirões, e as pás, e as bacias, e todos estes objetos que fez Hirão para o rei Salomão, para a casa do Senhor, todos eram de cobre polido.'),
('acf','1rs',7,46,'Na planície do Jordão, o rei os fundiu em terra barrenta; entre Sucote e Zaretã.'),
('acf','1rs',7,47,'E deixou Salomão de pesar todos os objetos, pelo seu excessivo número; nem se averiguou o peso do cobre.'),
('acf','1rs',7,48,'Também fez Salomão todos os objetos que convinham à casa do Senhor; o altar de ouro, e a mesa de ouro, sobre a qual estavam os pães da proposição.'),
('acf','1rs',7,49,'E os castiçais, cinco à direita e cinco à esquerda, diante do oráculo, de ouro finíssimo; e as flores, e as lâmpadas, e os espevitadores, também de ouro.'),
('acf','1rs',7,50,'Como também os vasos, e os apagadores, e as bacias, e as colheres, e os perfumadores, de ouro finíssimo; e as dobradiças para as portas da casa interior para o lugar santíssimo, e as das portas da casa do templo, também de ouro.'),
('acf','1rs',7,51,'Assim se acabou toda a obra que fez o rei Salomão para a casa do Senhor; então trouxe Salomão as coisas que seu pai Davi havia consagrado; a prata, e o ouro, e os objetos pôs entre os tesouros da casa do Senhor.'),
('acf','1rs',8,1,'Então congregou Salomão os anciãos de Israel, e todos os cabeças das tribos, os chefes dos pais dos filhos de Israel, diante de si em Jerusalém; para fazerem subir a arca da aliança do SENHOR da cidade de Davi, que é Sião.'),
('acf','1rs',8,2,'E todos os homens de Israel se congregaram ao rei Salomão, na ocasião da festa, no mês de Etanim, que é o sétimo mês.'),
('acf','1rs',8,3,'E vieram todos os anciãos de Israel; e os sacerdotes alçaram a arca.'),
('acf','1rs',8,4,'E trouxeram a arca do Senhor para cima, e o tabernáculo da congregação, juntamente com todos os objetos sagrados que havia no tabernáculo; assim os trouxeram para cima os sacerdotes e os levitas.'),
('acf','1rs',8,5,'E o rei Salomão, e toda a congregação de Israel que se congregara a ele, estava com ele diante da arca, sacrificando ovelhas e vacas, que não se podiam contar nem numerar pela sua quantidade.'),
('acf','1rs',8,6,'Assim trouxeram os sacerdotes a arca da aliança do Senhor ao seu lugar, ao oráculo da casa, ao lugar santíssimo, até debaixo das asas dos querubins.'),
('acf','1rs',8,7,'Porque os querubins estendiam ambas as asas sobre o lugar da arca; e os querubins cobriam, por cima, a arca e os seus varais.'),
('acf','1rs',8,8,'E os varais sobressaíram tanto, que as pontas dos varais se viam desde o santuário diante do oráculo, porém de fora não se viam; e ficaram ali até ao dia de hoje.'),
('acf','1rs',8,9,'Na arca nada havia, senão só as duas tábuas de pedra, que Moisés ali pusera junto a Horebe, quando o Senhor fez a aliança com os filhos de Israel, saindo eles da terra do Egito.'),
('acf','1rs',8,10,'E sucedeu que, saindo os sacerdotes do santuário, uma nuvem encheu a casa do Senhor.'),
('acf','1rs',8,11,'E os sacerdotes não podiam permanecer em pé para ministrar, por causa da nuvem, porque a glória do Senhor enchera a casa do Senhor.'),
('acf','1rs',8,12,'Então falou Salomão: O Senhor disse que ele habitaria nas trevas.'),
('acf','1rs',8,13,'Certamente te edifiquei uma casa para morada, assento para a tua eterna habitação.'),
('acf','1rs',8,14,'Então virou o rei o seu rosto, e abençoou toda a congregação de Israel; e toda a congregação de Israel estava em pé.'),
('acf','1rs',8,15,'E disse: Bendito seja o Senhor Deus de Israel, que falou pela sua boca a Davi, meu pai, e pela sua mão o cumpriu, dizendo:'),
('acf','1rs',8,16,'Desde o dia em que eu tirei o meu povo Israel do Egito, não escolhi cidade alguma de todas as tribos de Israel, para edificar alguma casa para ali estabelecer o meu nome; porém escolhi a Davi, para que presidisse sobre o meu povo Israel.'),
('acf','1rs',8,17,'Também Davi, meu pai, propusera em seu coração o edificar casa ao nome do Senhor Deus de Israel.'),
('acf','1rs',8,18,'Porém o Senhor disse a Davi, meu pai: Porquanto propuseste no teu coração o edificar casa ao meu nome, bem fizeste em o propor no teu coração.'),
('acf','1rs',8,19,'Todavia tu não edificarás esta casa; porém teu filho, que sair de teus lombos, edificará esta casa ao meu nome.'),
('acf','1rs',8,20,'Assim confirmou o Senhor a sua palavra que falou; porque me levantei em lugar de Davi, meu pai, e me assentei no trono de Israel, como tem falado o Senhor; e edifiquei uma casa ao nome do Senhor Deus de Israel.'),
('acf','1rs',8,21,'E constituí ali lugar para a arca em que está a aliança do Senhor, a qual fez com nossos pais, quando os tirou da terra do Egito.'),
('acf','1rs',8,22,'E pôs-se Salomão diante do altar do Senhor, na presença de toda a congregação de Israel; e estendeu as suas mãos para os céus,'),
('acf','1rs',8,23,'E disse: Ó Senhor Deus de Israel, não há Deus como tu, em cima nos céus nem em baixo na terra; que guardas a aliança e a beneficência a teus servos que andam com todo o seu coração diante de ti.'),
('acf','1rs',8,24,'Que guardaste a teu servo Davi, meu pai, o que lhe disseras; porque com a tua boca o disseste, e com a tua mão o cumpriste, como neste dia se vê.'),
('acf','1rs',8,25,'Agora, pois, ó Senhor Deus de Israel, guarda a teu servo Davi, meu pai, o que lhe falaste, dizendo: Não te faltará sucessor diante de mim, que se assente no trono de Israel; somente que teus filhos guardem o seu caminho, para andarem diante de mim como tu andaste diante de mim.'),
('acf','1rs',8,26,'Agora também, ó Deus de Israel, cumpra-se a tua palavra que disseste a teu servo Davi, meu pai.'),
('acf','1rs',8,27,'Mas, na verdade, habitaria Deus na terra? Eis que os céus, e até o céu dos céus, não te poderiam conter, quanto menos esta casa que eu tenho edificado.'),
('acf','1rs',8,28,'Volve-te, pois, para a oração de teu servo, e para a sua súplica, ó Senhor meu Deus, para ouvires o clamor e a oração que o teu servo hoje faz diante de ti.'),
('acf','1rs',8,29,'Para que os teus olhos noite e dia estejam abertos sobre esta casa, sobre este lugar, do qual disseste: O meu nome estará ali; para ouvires a oração que o teu servo fizer neste lugar.'),
('acf','1rs',8,30,'Ouve, pois, a súplica do teu servo, e do teu povo Israel, quando orarem neste lugar; também ouve tu no lugar da tua habitação nos céus; ouve também, e perdoa.'),
('acf','1rs',8,31,'Quando alguém pecar contra o seu próximo, e puserem sobre ele juramento de maldição, fazendo-o jurar, e vier juramento de maldição diante do teu altar nesta casa,'),
('acf','1rs',8,32,'Ouve tu, então, nos céus e age e julga a teus servos, condenando ao injusto, fazendo recair o seu proceder sobre a sua cabeça, e justificando ao justo, rendendo-lhe segundo a sua justiça.'),
('acf','1rs',8,33,'Quando o teu povo Israel for ferido diante do inimigo, por ter pecado contra ti, e se converterem a ti, e confessarem o teu nome, e orarem e suplicarem a ti nesta casa,'),
('acf','1rs',8,34,'Ouve tu então nos céus, e perdoa o pecado do teu povo Israel, e torna-o a levar à terra que tens dado a seus pais.'),
('acf','1rs',8,35,'Quando os céus se fechar, e não houver chuva, por terem pecado contra ti, e orarem neste lugar, e confessarem o teu nome, e se converterem dos seus pecados, havendo-os tu afligido,'),
('acf','1rs',8,36,'Ouve tu então nos céus, e perdoa o pecado de teus servos e do teu povo Israel, ensinando-lhes o bom caminho em que andem, e dá chuva na tua terra que deste ao teu povo em herança.'),
('acf','1rs',8,37,'Quando houver fome na terra, quando houver peste, quando houver queima de searas, ferrugem, gafanhotos ou pulgão, quando o seu inimigo o cercar na terra das suas portas, ou houver alguma praga ou doença,'),
('acf','1rs',8,38,'Toda a oração, toda a súplica, que qualquer homem de todo o teu povo Israel fizer, conhecendo cada um a chaga do seu coração, e estendendo as suas mãos para esta casa,'),
('acf','1rs',8,39,'Ouve tu então nos céus, assento da tua habitação, e perdoa, e age, e dá a cada um conforme a todos os seus caminhos, e segundo vires o seu coração, porque só tu conheces o coração de todos os filhos dos homens.'),
('acf','1rs',8,40,'Para que te temam todos os dias que viverem na terra que deste a nossos pais.'),
('acf','1rs',8,41,'E também ouve ao estrangeiro, que não for do teu povo Israel, quando vier de terras remotas, por amor do teu nome'),
('acf','1rs',8,42,'(Porque ouvirão do teu grande nome, e da tua forte mão, e do teu braço estendido), e vier orar voltado para esta casa,'),
('acf','1rs',8,43,'Ouve tu nos céus, assento da tua habitação, e faze conforme a tudo o que o estrangeiro a ti clamar, a fim de que todos os povos da terra conheçam o teu nome, para te temerem como o teu povo Israel, e para saberem que o teu nome é invocado sobre esta casa que tenho edificado.'),
('acf','1rs',8,44,'Quando o teu povo sair à guerra contra o seu inimigo, pelo caminho por que os enviares, e orarem ao Senhor, para o lado desta cidade, que tu elegeste, e desta casa, que edifiquei ao teu nome,'),
('acf','1rs',8,45,'Ouve, então, nos céus a sua oração e a sua súplica, e faze-lhes justiça.'),
('acf','1rs',8,46,'Quando pecarem contra ti (pois não há homem que não peque), e tu te indignares contra eles, e os entregares às mãos do inimigo, de modo que os levem em cativeiro para a terra inimiga, quer longe ou perto esteja,'),
('acf','1rs',8,47,'E na terra aonde forem levados em cativeiro caírem em si, e se converterem, e na terra do seu cativeiro te suplicarem, dizendo: Pecamos, e perversamente procedemos, e cometemos iniqüidade,'),
('acf','1rs',8,48,'E se converterem a ti com todo o seu coração e com toda a sua alma, na terra de seus inimigos que os levarem em cativeiro, e orarem a ti para o lado da sua terra que deste a seus pais, para esta cidade que elegeste, e para esta casa que edifiquei ao teu nome;'),
('acf','1rs',8,49,'Ouve então nos céus, assento da tua habitação, a sua oração e a sua súplica, e faze-lhes justiça.'),
('acf','1rs',8,50,'E perdoa ao teu povo que houver pecado contra ti, todas as transgressões que houverem cometido contra ti; e dá-lhes misericórdia perante aqueles que os têm cativos, para que deles tenham compaixão.'),
('acf','1rs',8,51,'Porque são o teu povo e a tua herança que tiraste da terra do Egito, do meio do forno de ferro.'),
('acf','1rs',8,52,'Para que teus olhos estejam abertos à súplica do teu servo e à súplica do teu povo Israel, a fim de os ouvires em tudo quanto clamarem a ti.'),
('acf','1rs',8,53,'Pois tu para tua herança os elegeste de todos os povos da terra, como tens falado pelo ministério de Moisés, teu servo, quando tiraste a nossos pais do Egito, Senhor DEUS.'),
('acf','1rs',8,54,'Sucedeu, pois, que, acabando Salomão de fazer ao Senhor esta oração e esta súplica, estando de joelhos e com as mãos estendidas para os céus, se levantou de diante do altar do Senhor.'),
('acf','1rs',8,55,'E pôs-se em pé, e abençoou a toda a congregação de Israel em alta voz, dizendo:'),
('acf','1rs',8,56,'Bendito seja o Senhor, que deu repouso ao seu povo Israel, segundo tudo o que disse; nem uma só palavra caiu de todas as suas boas palavras que falou pelo ministério de Moisés, seu servo.'),
('acf','1rs',8,57,'O Senhor nosso Deus seja conosco, como foi com nossos pais; não nos desampare, e não nos deixe.'),
('acf','1rs',8,58,'Inclinando a si o nosso coração, para andar em todos os seus caminhos, e para guardar os seus mandamentos, e os seus estatutos, e os seus juízos que ordenou a nossos pais.'),
('acf','1rs',8,59,'E que estas minhas palavras, com que supliquei perante o Senhor, estejam perto, diante do Senhor nosso Deus, de dia e de noite, para que execute o juízo do seu servo e o juízo do seu povo Israel, a cada qual no seu dia.'),
('acf','1rs',8,60,'Para que todos os povos da terra saibam que o Senhor é Deus, e que não há outro.'),
('acf','1rs',8,61,'E seja o vosso coração inteiro para com o Senhor nosso Deus, para andardes nos seus estatutos, e guardardes os seus mandamentos como hoje.'),
('acf','1rs',8,62,'E o rei e todo o Israel com ele ofereceram sacrifícios perante a face do Senhor.'),
('acf','1rs',8,63,'E deu Salomão para o sacrifício pacífico que ofereceu ao Senhor, vinte e duas mil vacas e cento e vinte mil ovelhas; assim o rei e todos os filhos de Israel consagraram a casa do Senhor.'),
('acf','1rs',8,64,'No mesmo dia santificou o rei o meio do átrio que estava diante da casa do Senhor; porquanto ali preparara os holocaustos e as ofertas com a gordura dos sacrifícios pacíficos; porque o altar de cobre que estava diante da face do Senhor era muito pequeno para nele caberem os holocaustos e as ofertas, e a gordura dos sacrifícios pacíficos.'),
('acf','1rs',8,65,'No mesmo tempo celebrou Salomão a festa, e todo o Israel com ele, uma grande congregação, desde a entrada de Hamate até ao rio do Egito, perante a face do Senhor nosso Deus; por sete dias, e mais sete dias; catorze dias.'),
('acf','1rs',8,66,'E no oitavo dia despediu o povo, e eles abençoaram o rei; então se foram às suas tendas, alegres e felizes de coração, por causa de todo o bem que o Senhor fizera a Davi seu servo, e a Israel seu povo.'),
('acf','1rs',9,1,'Sucedeu, pois, que, acabando Salomão de edificar a casa do SENHOR, e a casa do rei, e todo o desejo de Salomão, que lhe veio à vontade fazer,'),
('acf','1rs',9,2,'O Senhor tornou a aparecer a Salomão; como lhe tinha aparecido em Gibeom.'),
('acf','1rs',9,3,'E o Senhor lhe disse: Ouvi a tua oração, e a súplica que fizeste perante mim; santifiquei a casa que edificaste, a fim de pôr ali o meu nome para sempre; e os meus olhos e o meu coração estarão ali todos os dias.'),
('acf','1rs',9,4,'E se tu andares perante mim como andou Davi, teu pai, com inteireza de coração e com sinceridade, para fazeres segundo tudo o que te mandei, e guardares os meus estatutos e os meus juízos,'),
('acf','1rs',9,5,'Então confirmarei o trono de teu reino sobre Israel para sempre; como falei acerca de teu pai Davi, dizendo: Não te faltará sucessor sobre o trono de Israel;'),
('acf','1rs',9,6,'Porém, se vós e vossos filhos de qualquer maneira vos apartardes de mim, e não guardardes os meus mandamentos, e os meus estatutos, que vos tenho proposto, mas fordes, e servirdes a outros deuses, e vos prostrardes perante eles,'),
('acf','1rs',9,7,'Então destruirei a Israel da terra que lhes dei; e a esta casa, que santifiquei a meu nome, lançarei longe da minha presença; e Israel será por provérbio e motejo, entre todos os povos.'),
('acf','1rs',9,8,'E desta casa, que é tão exaltada, todo aquele que por ela passar pasmará, e assobiará, e dirá: Por que fez o Senhor assim a esta terra e a esta casa?'),
('acf','1rs',9,9,'E dirão: Porque deixaram ao Senhor seu Deus, que tirou da terra do Egito a seus pais, e se apegaram a deuses alheios, e se encurvaram perante eles, e os serviram; por isso trouxe o Senhor sobre eles todo este mal.'),
('acf','1rs',9,10,'E sucedeu, ao fim de vinte anos, que Salomão edificara as duas casas; a casa do Senhor e a casa do rei'),
('acf','1rs',9,11,'(Para o que Hirão, rei de Tiro, trouxera a Salomão madeira de cedro e de cipreste, e ouro, segundo todo o seu desejo); então deu o rei Salomão a Hirão vinte cidades na terra da Galiléia.'),
('acf','1rs',9,12,'E saiu Hirão de Tiro a ver as cidades que Salomão lhe dera, porém não foram boas aos seus olhos.'),
('acf','1rs',9,13,'Por isso disse: Que cidades são estas que me deste, irmão meu? E chamaram-nas: Terra de Cabul, até hoje.'),
('acf','1rs',9,14,'E enviara Hirão ao rei cento e vinte talentos de ouro.'),
('acf','1rs',9,15,'E esta é a causa do tributo que impôs o rei Salomão, para edificar a casa do Senhor e a sua casa, e Milo, e o muro de Jerusalém, como também a Hasor, e a Megido, e a Gezer.'),
('acf','1rs',9,16,'Porque Faraó, rei do Egito, subiu e tomou a Gezer, e a queimou a fogo, e matou os cananeus que moravam na cidade, e a deu em dote à sua filha, mulher de Salomão.'),
('acf','1rs',9,17,'Assim edificou Salomão a Gezer, e Bete-Horom, a baixa,'),
('acf','1rs',9,18,'E a Baalate, e a Tadmor, no deserto daquela terra,'),
('acf','1rs',9,19,'E a todas as cidades de provisões que Salomão tinha, e as cidades dos carros, e as cidades dos cavaleiros, e tudo o que Salomão quis edificar em Jerusalém, e no Líbano, e em toda a terra do seu domínio.'),
('acf','1rs',9,20,'Quanto a todo o povo que restou dos amorreus, heteus, perizeus, heveus, e jebuseus, e que não eram dos filhos de Israel,'),
('acf','1rs',9,21,'A seus filhos, que restaram depois deles na terra, os quais os filhos de Israel não puderam destruir totalmente, Salomão os reduziu a tributo servil, até hoje.'),
('acf','1rs',9,22,'Porém dos filhos de Israel não fez Salomão servo algum; porém eram homens de guerra, e seus criados, e seus príncipes, e seus capitães, e chefes dos seus carros e dos seus cavaleiros.'),
('acf','1rs',9,23,'Estes eram os chefes dos oficiais que estavam sobre a obra de Salomão, quinhentos e cinqüenta, que davam ordens ao povo que trabalhava na obra.'),
('acf','1rs',9,24,'Subiu, porém, a filha de Faraó da cidade de Davi, à sua casa, que Salomão lhe edificara; então edificou a Milo.'),
('acf','1rs',9,25,'E oferecia Salomão três vezes cada ano holocaustos e sacrifícios pacíficos sobre o altar que edificaram ao Senhor, e queimava incenso sobre o que estava perante o Senhor; e assim acabou a casa.'),
('acf','1rs',9,26,'Também o rei Salomão fez naus em Eziom-Geber, que está junto a Elate, à praia do mar de Sufe, na terra de Edom.'),
('acf','1rs',9,27,'E mandou Hirão com aquelas naus a seus servos, marinheiros, que sabiam do mar, com os servos de Salomão.'),
('acf','1rs',9,28,'E vieram a Ofir, e tomaram de lá quatrocentos e vinte talentos de ouro, e os trouxeram ao rei Salomão.'),
('acf','1rs',10,1,'E ouvindo a rainha de Sabá a fama de Salomão, acerca do nome do SENHOR, veio prová-lo com questões difíceis.'),
('acf','1rs',10,2,'E chegou a Jerusalém com uma grande comitiva; com camelos carregados de especiarias, e muitíssimo ouro, e pedras preciosas; e foi a Salomão, e disse-lhe tudo quanto tinha no seu coração.'),
('acf','1rs',10,3,'E Salomão lhe deu resposta a todas as suas perguntas, nada houve que não lhe pudesse esclarecer.'),
('acf','1rs',10,4,'Vendo, pois, a rainha de Sabá toda a sabedoria de Salomão, e a casa que edificara,'),
('acf','1rs',10,5,'E a comida da sua mesa, e o assentar de seus servos, e o estar de seus criados, e as vestes deles, e os seus copeiros, e os holocaustos que ele oferecia na casa do Senhor, ficou fora de si.'),
('acf','1rs',10,6,'E disse ao rei: Era verdade a palavra que ouvi na minha terra, dos teus feitos e da tua sabedoria.'),
('acf','1rs',10,7,'E eu não cria naquelas palavras, até que vim e os meus olhos o viram; eis que não me disseram metade; sobrepujaste em sabedoria e bens a fama que ouvi.'),
('acf','1rs',10,8,'Bem-aventurados os teus homens, bem-aventurados estes teus servos, que estão sempre diante de ti, que ouvem a tua sabedoria!'),
('acf','1rs',10,9,'Bendito seja o Senhor teu Deus, que teve agrado em ti, para te pôr no trono de Israel; porque o Senhor ama a Israel para sempre, por isso te estabeleceu rei, para fazeres juízo e justiça.'),
('acf','1rs',10,10,'E deu ao rei cento e vinte talentos de ouro, e muitíssimas especiarias, e pedras preciosas; nunca veio especiaria em tanta abundância, como a que a rainha de Sabá deu ao rei Salomão.'),
('acf','1rs',10,11,'Também as naus de Hirão, que de Ofir levavam ouro, traziam de Ofir muita madeira de almugue, e pedras preciosas.'),
('acf','1rs',10,12,'E desta madeira de almugue fez o rei balaústres para a casa do Senhor, e para a casa do rei, como também harpas e alaúdes para os cantores; nunca veio tal madeira de almugue, nem se viu até o dia de hoje.'),
('acf','1rs',10,13,'E o rei Salomão deu à rainha de Sabá tudo o que ela desejou, tudo quanto pediu, além do que dera por sua generosidade; então voltou e partiu para a sua terra, ela e os seus servos.'),
('acf','1rs',10,14,'E o peso do ouro que se trazia a Salomão cada ano era de seiscentos e sessenta e seis talentos de ouro;'),
('acf','1rs',10,15,'Além do que entrava dos negociantes, e do contrato dos especieiros, e de todos os reis da Arábia, e dos governadores da mesma terra.'),
('acf','1rs',10,16,'Também o rei Salomão fez duzentos paveses de ouro batido; seiscentos siclos de ouro destinou para cada pavês;'),
('acf','1rs',10,17,'Fez também trezentos escudos de ouro batido; três arráteis de ouro destinou para cada escudo; e o rei os pôs na casa do bosque do Líbano.'),
('acf','1rs',10,18,'Fez mais o rei um grande trono de marfim, e o revestiu de ouro puríssimo.'),
('acf','1rs',10,19,'Tinha este trono seis degraus, e era o alto do trono por detrás redondo, e de ambos os lados tinha encostos até ao assento; e dois leões, em pé, juntos aos encostos.'),
('acf','1rs',10,20,'Também doze leões estavam ali sobre os seis degraus de ambos os lados; nunca se tinha feito obra semelhante em nenhum dos reinos.'),
('acf','1rs',10,21,'Também todas as taças de beber do rei Salomão eram de ouro, e todos os vasos da casa do bosque do Líbano eram de ouro puro; não havia neles prata, porque nos dias de Salomão não tinha valor algum.'),
('acf','1rs',10,22,'Porque o rei tinha no mar as naus de Társis, com as naus de Hirão; uma vez em três anos tornavam as naus de Társis, e traziam ouro e prata, marfim, e bugios, e pavões.'),
('acf','1rs',10,23,'Assim o rei Salomão excedeu a todos os reis da terra, tanto em riquezas como em sabedoria.'),
('acf','1rs',10,24,'E toda a terra buscava a face de Salomão, para ouvir a sabedoria que Deus tinha posto no seu coração.'),
('acf','1rs',10,25,'E cada um trazia o seu presente, vasos de prata e vasos de ouro, e roupas, e armaduras, e especiarias, cavalos e mulas; isso faziam de ano em ano.'),
('acf','1rs',10,26,'Também ajuntou Salomão carros e cavaleiros, de sorte que tinha mil e quatrocentos carros e doze mil cavaleiros; e os levou às cidades dos carros, e junto ao rei em Jerusalém.'),
('acf','1rs',10,27,'E fez o rei que em Jerusalém houvesse prata como pedras; e cedros em abundância como sicômoros que estão nas planícies.'),
('acf','1rs',10,28,'E traziam do Egito, para Salomão, cavalos e fio de linho; e os mercadores do rei recebiam o fio de linho, por um certo preço.'),
('acf','1rs',10,29,'E subia e saía um carro do Egito por seiscentos siclos de prata, e um cavalo por cento e cinqüenta; e assim, por meio deles, eram exportados para todos os reis dos heteus e para os reis da Síria.'),
('acf','1rs',11,1,'E o rei Salomão amou muitas mulheres estrangeiras, além da filha de Faraó: moabitas, amonitas, edomitas, sidônias e hetéias,'),
('acf','1rs',11,2,'Das nações de que o Senhor tinha falado aos filhos de Israel: Não chegareis a elas, e elas não chegarão a vós; de outra maneira perverterão o vosso coração para seguirdes os seus deuses. A estas se uniu Salomão com amor.'),
('acf','1rs',11,3,'E tinha setecentas mulheres, princesas, e trezentas concubinas; e suas mulheres lhe perverteram o coração.'),
('acf','1rs',11,4,'Porque sucedeu que, no tempo da velhice de Salomão, suas mulheres lhe perverteram o coração para seguir outros deuses; e o seu coração não era perfeito para com o Senhor seu Deus, como o coração de Davi, seu pai,'),
('acf','1rs',11,5,'Porque Salomão seguiu a Astarote, deusa dos sidônios, e Milcom, a abominação dos amonitas.'),
('acf','1rs',11,6,'Assim fez Salomão o que parecia mal aos olhos do Senhor; e não perseverou em seguir ao Senhor, como Davi, seu pai.'),
('acf','1rs',11,7,'Então edificou Salomão um alto a Quemós, a abominação dos moabitas, sobre o monte que está diante de Jerusalém, e a Moloque, a abominação dos filhos de Amom.'),
('acf','1rs',11,8,'E assim fez para com todas as suas mulheres estrangeiras, as quais queimavam incenso e sacrificavam a seus deuses.'),
('acf','1rs',11,9,'Pelo que o Senhor se indignou contra Salomão; porquanto desviara o seu coração do Senhor Deus de Israel, o qual duas vezes lhe aparecera.'),
('acf','1rs',11,10,'E acerca deste assunto lhe tinha dado ordem que não seguisse a outros deuses; porém não guardou o que o Senhor lhe ordenara.'),
('acf','1rs',11,11,'Assim disse o Senhor a Salomão: Pois que houve isto em ti, que não guardaste a minha aliança e os meus estatutos que te mandei, certamente rasgarei de ti este reino, e o darei a teu servo.'),
('acf','1rs',11,12,'Todavia nos teus dias não o farei, por amor de Davi, teu pai; da mão de teu filho o rasgarei;'),
('acf','1rs',11,13,'Porém todo o reino não rasgarei; uma tribo darei a teu filho, por amor de meu servo Davi, e por amor a Jerusalém, que tenho escolhido.'),
('acf','1rs',11,14,'Levantou, pois, o Senhor contra Salomão um adversário, Hadade, o edomeu; ele era da descendência do rei em Edom.'),
('acf','1rs',11,15,'Porque sucedeu que, estando Davi em Edom, e subindo Joabe, o capitão do exército, a enterrar os mortos, feriu a todo o homem em Edom'),
('acf','1rs',11,16,'(Porque Joabe ficou ali seis meses com todo o Israel, até que destruiu a todo o homem em Edom).'),
('acf','1rs',11,17,'Hadade, porém, fugiu, ele e alguns homens edomeus, dos servos de seu pai, com ele, para ir ao Egito; era, porém, Hadade muito jovem.'),
('acf','1rs',11,18,'E levantaram-se de Midiã, e foram a Parã, e tomaram consigo homens de Parã, e foram ao Egito ter com Faraó, rei do Egito, o qual lhe deu uma casa, e lhe prometeu sustento, e lhe deu uma terra.'),
('acf','1rs',11,19,'E achou Hadade grande graça diante de Faraó, de maneira que lhe deu por mulher a irmã de sua mulher, a irmã de Tafnes, a rainha.'),
('acf','1rs',11,20,'E a irmã de Tafnes deu-lhe um filho, Genubate, o qual Tafnes criou na casa de Faraó; e Genubate estava na casa de Faraó, entre os filhos de Faraó.'),
('acf','1rs',11,21,'Ouvindo, pois, Hadade, no Egito, que Davi adormecera com seus pais, e que Joabe, capitão do exército, era morto, disse Hadade a Faraó: Despede-me, para que vá à minha terra.'),
('acf','1rs',11,22,'Porém Faraó lhe disse: Pois que te falta comigo, que procuras partir para a tua terra? E disse ele: Nada, mas todavia despede-me.'),
('acf','1rs',11,23,'Também Deus lhe levantou outro adversário, a Rezom, filho de Eliada, que tinha fugido de seu senhor Hadadezer, rei de Zobá,'),
('acf','1rs',11,24,'Contra quem também ajuntou homens, e foi capitão de um esquadrão, quando Davi os matou; e, indo-se para Damasco, habitaram ali, e reinaram em Damasco.'),
('acf','1rs',11,25,'E foi adversário de Israel, por todos os dias de Salomão, e isto além do mal que Hadade fazia; porque detestava a Israel, e reinava sobre a Síria.'),
('acf','1rs',11,26,'Até Jeroboão, filho de Nebate, efrateu, de Zereda, servo de Salomão (cuja mãe era mulher viúva, por nome Zerua), também levantou a mão contra o rei.'),
('acf','1rs',11,27,'E esta foi a causa por que levantou a mão contra o rei: Salomão tinha edificado a Milo, e cerrou as aberturas da cidade de Davi, seu pai.'),
('acf','1rs',11,28,'E o homem Jeroboão era forte e valente; e vendo Salomão a este jovem, que era laborioso, ele o pôs sobre todo o cargo da casa de José.'),
('acf','1rs',11,29,'Sucedeu, pois, naquele tempo que, saindo Jeroboão de Jerusalém, o profeta Aías, o silonita, o encontrou no caminho, e ele estava vestido com uma roupa nova, e os dois estavam sós no campo.'),
('acf','1rs',11,30,'E Aías pegou na roupa nova que tinha sobre si, e a rasgou em doze pedaços.'),
('acf','1rs',11,31,'E disse a Jeroboão: Toma para ti os dez pedaços, porque assim diz o Senhor Deus de Israel: Eis que rasgarei o reino da mão de Salomão, e a ti darei as dez tribos.'),
('acf','1rs',11,32,'Porém ele terá uma tribo, por amor de Davi, meu servo, e por amor de Jerusalém, a cidade que escolhi de todas as tribos de Israel.'),
('acf','1rs',11,33,'Porque me deixaram, e se encurvaram a Astarote, deusa dos sidônios, a Quemós, deus dos moabitas, e a Milcom, deus dos filhos de Amom; e não andaram pelos meus caminhos, para fazerem o que é reto aos meus olhos, a saber, os meus estatutos e os meus juízos, como Davi, seu pai.'),
('acf','1rs',11,34,'Porém não tomarei nada deste reino da sua mão; mas por príncipe o ponho por todos os dias da sua vida, por amor de Davi, meu servo, a quem escolhi, o qual guardou os meus mandamentos e os meus estatutos.'),
('acf','1rs',11,35,'Mas da mão de seu filho tomarei o reino, e darei a ti, as dez tribos dele.'),
('acf','1rs',11,36,'E a seu filho darei uma tribo; para que Davi, meu servo, sempre tenha uma lâmpada diante de mim em Jerusalém, a cidade que escolhi para pôr ali o meu nome.'),
('acf','1rs',11,37,'E te tomarei, e reinarás sobre tudo o que desejar a tua alma; e serás rei sobre Israel.'),
('acf','1rs',11,38,'E há de ser que, se ouvires tudo o que eu te mandar, e andares pelos meus caminhos, e fizeres o que é reto aos meus olhos, guardando os meus estatutos e os meus mandamentos, como fez Davi, meu servo, eu serei contigo, e te edificarei uma casa firme, como edifiquei a Davi, e te darei Israel.'),
('acf','1rs',11,39,'E por isso afligirei a descendência de Davi; todavia não para sempre.'),
('acf','1rs',11,40,'Assim Salomão procurou matar Jeroboão; porém Jeroboão se levantou, e fugiu para o Egito, a ter com Sisaque, rei do Egito; e esteve no Egito até que Salomão morreu.'),
('acf','1rs',11,41,'Quanto ao mais dos atos de Salomão, e a tudo quanto fez, e à sua sabedoria, porventura não está escrito no livro dos feitos de Salomão?'),
('acf','1rs',11,42,'E o tempo que reinou Salomão, em Jerusalém, sobre todo o Israel foi quarenta anos.'),
('acf','1rs',11,43,'E adormeceu Salomão com seus pais, e foi sepultado na cidade de Davi, seu pai; e Roboão, seu filho, reinou em seu lugar.'),
('acf','1rs',12,1,'E foi Roboão para Siquém; porque todo o Israel se reuniu em Siquém, para o fazerem rei.'),
('acf','1rs',12,2,'Sucedeu que, Jeroboão, filho de Nebate, achando-se ainda no Egito, para onde fugira de diante do rei Salomão, voltou do Egito,'),
('acf','1rs',12,3,'Porque mandaram chamá-lo; veio, pois, Jeroboão e toda a congregação de Israel, e falaram a Roboão, dizendo:'),
('acf','1rs',12,4,'Teu pai agravou o nosso jugo; agora, pois, alivia tu a dura servidão de teu pai, e o pesado jugo que nos impôs, e nós te serviremos.'),
('acf','1rs',12,5,'E ele lhes disse: Ide-vos até ao terceiro dia, e então voltai a mim. E o povo se foi.'),
('acf','1rs',12,6,'E teve o rei Roboão conselho com os anciãos que estiveram na presença de Salomão, seu pai, quando este ainda vivia, dizendo: Como aconselhais vós que se responda a este povo?'),
('acf','1rs',12,7,'E eles lhe falaram, dizendo: Se hoje fores servo deste povo, e o servires, e respondendo-lhe, lhe falares boas palavras, todos os dias serão teus servos.'),
('acf','1rs',12,8,'Porém ele deixou o conselho que os anciãos lhe tinham dado, e teve conselho com os jovens que haviam crescido com ele, que estavam diante dele.'),
('acf','1rs',12,9,'E disse-lhes: Que aconselhais vós que respondamos a este povo, que me falou, dizendo: Alivia o jugo que teu pai nos impôs?'),
('acf','1rs',12,10,'E os jovens que haviam crescido com ele lhe falaram: Assim dirás a este povo que te falou: Teu pai fez pesadíssimo o nosso jugo, mas tu o alivia de sobre nós; assim lhe falarás: Meu dedo mínimo é mais grosso do que os lombos de meu pai.'),
('acf','1rs',12,11,'Assim que, se meu pai vos carregou de um jugo pesado, ainda eu aumentarei o vosso jugo; meu pai vos castigou com açoites, porém eu vos castigarei com escorpiões.'),
('acf','1rs',12,12,'Veio, pois, Jeroboão e todo o povo, ao terceiro dia, a Roboão, como o rei havia ordenado, dizendo: Voltai a mim ao terceiro dia.'),
('acf','1rs',12,13,'E o rei respondeu ao povo duramente; porque deixara o conselho que os anciãos lhe haviam dado.'),
('acf','1rs',12,14,'E lhe falou conforme ao conselho dos jovens, dizendo: Meu pai agravou o vosso jugo, porém eu ainda aumentarei o vosso jugo; meu pai vos castigou com açoites, porém eu vos castigarei com escorpiões.'),
('acf','1rs',12,15,'O rei, pois, não deu ouvidos ao povo; porque esta revolta vinha do Senhor, para confirmar a palavra que o Senhor tinha falado pelo ministério de Aías, o silonita, a Jeroboão, filho de Nebate.'),
('acf','1rs',12,16,'Vendo, pois, todo o Israel que o rei não lhe dava ouvidos, tornou-lhe o povo a responder, dizendo: Que parte temos nós com Davi? Não há para nós herança no filho de Jessé. Às tuas tendas, ó Israel! Provê agora a tua casa, ó Davi. Então Israel se foi às suas tendas.'),
('acf','1rs',12,17,'No tocante, porém, aos filhos de Israel que habitavam nas cidades de Judá, também sobre eles reinou Roboão.'),
('acf','1rs',12,18,'Então o rei Roboão enviou a Adorão, que estava sobre os tributos; e todo o Israel o apedrejou, e ele morreu; mas o rei Roboão se animou a subir ao carro para fugir para Jerusalém.'),
('acf','1rs',12,19,'Assim se rebelaram os israelitas contra a casa de Davi, até ao dia de hoje.'),
('acf','1rs',12,20,'E sucedeu que, ouvindo todo o Israel que Jeroboão tinha voltado, enviaram, e o chamaram para a congregação, e o fizeram rei sobre todo o Israel; e ninguém seguiu a casa de Davi senão somente a tribo de Judá.'),
('acf','1rs',12,21,'Vindo, pois, Roboão a Jerusalém, reuniu toda a casa de Judá e a tribo de Benjamim, cento e oitenta mil escolhidos, destros para a guerra, para pelejar contra a casa de Israel, para restituir o reino a Roboão, filho de Salomão.'),
('acf','1rs',12,22,'Porém veio a palavra de Deus a Semaías, homem de Deus, dizendo:'),
('acf','1rs',12,23,'Fala a Roboão, filho de Salomão, rei de Judá, e a toda a casa de Judá, e a Benjamim, e ao restante do povo, dizendo:'),
('acf','1rs',12,24,'Assim diz o Senhor: Não subireis nem pelejareis contra vossos irmãos, os filhos de Israel; volte cada um para a sua casa, porque eu é que fiz esta obra. E ouviram a palavra do Senhor, e voltaram segundo a palavra do Senhor.'),
('acf','1rs',12,25,'E Jeroboão edificou a Siquém, no monte de Efraim, e habitou ali; e saiu dali, e edificou a Penuel.'),
('acf','1rs',12,26,'E disse Jeroboão no seu coração: Agora tornará o reino à casa de Davi.'),
('acf','1rs',12,27,'Se este povo subir para fazer sacrifícios na casa do SENHOR, em Jerusalém, o coração deste povo se tornará a seu senhor, a Roboão, rei de Judá; e me matarão, e tornarão a Roboão, rei de Judá.'),
('acf','1rs',12,28,'Assim o rei tomou conselho, e fez dois bezerros de ouro; e lhes disse: Muito trabalho vos será o subir a Jerusalém; vês aqui teus deuses, ó Israel, que te fizeram subir da terra do Egito.'),
('acf','1rs',12,29,'E pôs um em Betel, e colocou o outro em Dã.'),
('acf','1rs',12,30,'E este feito se tornou em pecado; pois que o povo ia até Dã para adorar o bezerro.'),
('acf','1rs',12,31,'Também fez casa nos altos; e constituiu sacerdotes dos mais baixos do povo, que não eram dos filhos de Levi.'),
('acf','1rs',12,32,'E fez Jeroboão uma festa no oitavo mês, no dia décimo quinto do mês, como a festa que se fazia em Judá, e sacrificou no altar; semelhantemente fez em Betel, sacrificando aos bezerros que fizera; também em Betel estabeleceu sacerdotes dos altos que fizera.'),
('acf','1rs',12,33,'E sacrificou no altar que fizera em Betel, no dia décimo quinto do oitavo mês, que ele tinha imaginado no seu coração; assim fez a festa aos filhos de Israel, e sacrificou no altar, queimando incenso.'),
('acf','1rs',13,1,'E eis que, por ordem do SENHOR, veio, de Judá a Betel, um homem de Deus; e Jeroboão estava junto ao altar, para queimar incenso.'),
('acf','1rs',13,2,'E ele clamou contra o altar por ordem do Senhor, e disse: Altar, altar! Assim diz o Senhor: Eis que um filho nascerá à casa de Davi, cujo nome será Josias, o qual sacrificará sobre ti os sacerdotes dos altos que sobre ti queimam incenso, e ossos de homens se queimarão sobre ti.'),
('acf','1rs',13,3,'E deu, naquele mesmo dia, um sinal, dizendo: Este é o sinal de que o Senhor falou: Eis que o altar se fenderá, e a cinza, que nele está, se derramará.'),
('acf','1rs',13,4,'Sucedeu, pois, que, ouvindo o rei a palavra do homem de Deus, que clamara contra o altar de Betel, Jeroboão estendeu a sua mão de sobre o altar, dizendo: Pegai-o! Mas a sua mão, que estendera contra ele, se secou, e não podia tornar a trazê-la a si.'),
('acf','1rs',13,5,'E o altar se fendeu, e a cinza se derramou do altar, segundo o sinal que o homem de Deus apontara por ordem do Senhor.'),
('acf','1rs',13,6,'Então respondeu o rei, e disse ao homem de Deus: Suplica ao Senhor teu Deus, e roga por mim, para que se me restitua a minha mão. Então o homem de Deus suplicou ao Senhor, e a mão do rei se lhe restituiu, e ficou como dantes.'),
('acf','1rs',13,7,'E o rei disse ao homem de Deus: Vem comigo para casa, e conforta-te; e dar-te-ei um presente.'),
('acf','1rs',13,8,'Porém o homem de Deus disse ao rei: Ainda que me desses metade da tua casa, não iria contigo, nem comeria pão nem beberia água neste lugar.'),
('acf','1rs',13,9,'Porque assim me ordenou o Senhor pela sua palavra, dizendo: Não comerás pão nem beberás água; e não voltarás pelo caminho por onde vieste.'),
('acf','1rs',13,10,'Assim foi por outro caminho; e não voltou pelo caminho, por onde viera a Betel.'),
('acf','1rs',13,11,'E morava em Betel um velho profeta; e vieram seus filhos, e contaram-lhe tudo o que o homem de Deus fizera aquele dia em Betel, e as palavras que dissera ao rei; e as contaram a seu pai.'),
('acf','1rs',13,12,'E disse-lhes seu pai: Por que caminho se foi? E seus filhos lhe mostraram o caminho por onde fora o homem de Deus que viera de Judá.'),
('acf','1rs',13,13,'Então disse a seus filhos: Albardai-me um jumento. E albardaram-lhe o jumento no qual ele montou.'),
('acf','1rs',13,14,'E foi após o homem de Deus, e achou-o assentado debaixo de um carvalho, e disse-lhe: És tu o homem de Deus que vieste de Judá? E ele disse: Sou.'),
('acf','1rs',13,15,'Então lhe disse: Vem comigo à casa, e come pão.'),
('acf','1rs',13,16,'Porém ele disse: Não posso voltar contigo, nem entrarei contigo; nem tampouco comerei pão, nem beberei contigo água neste lugar.'),
('acf','1rs',13,17,'Porque me foi mandado pela palavra do Senhor: Ali não comerás pão, nem beberás água; nem voltarás pelo caminho por onde vieste.'),
('acf','1rs',13,18,'E ele lhe disse: Também eu sou profeta como tu, e um anjo me falou por ordem do Senhor, dizendo: Faze-o voltar contigo à tua casa, para que coma pão e beba água (porém mentiu-lhe).'),
('acf','1rs',13,19,'Assim voltou com ele, e comeu pão em sua casa e bebeu água.'),
('acf','1rs',13,20,'E sucedeu que, estando eles à mesa, a palavra do Senhor veio ao profeta que o tinha feito voltar.'),
('acf','1rs',13,21,'E clamou ao homem de Deus, que viera de Judá, dizendo: Assim diz o Senhor: Porquanto foste rebelde à ordem do Senhor, e não guardaste o mandamento que o Senhor teu Deus te mandara,'),
('acf','1rs',13,22,'Antes voltaste, e comeste pão e bebeste água no lugar de que o Senhor te dissera: Não comerás pão nem beberás água; o teu cadáver não entrará no sepulcro de teus pais.'),
('acf','1rs',13,23,'E sucedeu que, depois que comeu pão, e depois que bebeu, albardou ele o jumento para o profeta que fizera voltar.'),
('acf','1rs',13,24,'Este, pois, se foi, e um leão o encontrou no caminho, e o matou; e o seu cadáver ficou estendido no caminho, e o jumento estava parado junto a ele, e também o leão estava junto ao cadáver.'),
('acf','1rs',13,25,'E eis que alguns homens passaram, e viram o corpo lançado no caminho, como também o leão, que estava junto ao corpo; e foram, e o disseram na cidade onde o velho profeta habitava.'),
('acf','1rs',13,26,'E, ouvindo-o o profeta que o fizera voltar do caminho, disse: É o homem de Deus, que foi rebelde à ordem do Senhor; por isso o Senhor o entregou ao leão, que o despedaçou e matou, segundo a palavra que o Senhor lhe dissera.'),
('acf','1rs',13,27,'Então disse a seus filhos: Albardai-me o jumento. Eles o albardaram.'),
('acf','1rs',13,28,'Então foi, e achou o cadáver estendido no caminho, e o jumento e o leão, que estavam parados junto ao cadáver; e o leão não tinha devorado o corpo, nem tinha despedaçado o jumento.'),
('acf','1rs',13,29,'Então o profeta levantou o cadáver do homem de Deus, e pô-lo em cima do jumento levando-o consigo; assim veio o velho profeta à cidade, para o chorar e enterrar.'),
('acf','1rs',13,30,'E colocou o cadáver no seu próprio sepulcro; e prantearam-no, dizendo: Ah, irmão meu!'),
('acf','1rs',13,31,'E sucedeu que, depois de o haver sepultado, disse a seus filhos: Morrendo eu, sepultai-me no sepulcro em que o homem de Deus está sepultado; ponde os meus ossos junto aos ossos dele.'),
('acf','1rs',13,32,'Porque certamente se cumprirá o que pela palavra do Senhor exclamou contra o altar que está em Betel, como também contra todas as casas dos altos que estão nas cidades de Samaria.'),
('acf','1rs',13,33,'Nem depois destas coisas deixou Jeroboão o seu mau caminho; antes, de todo o povo, tornou a constituir sacerdotes dos lugares altos; e a qualquer que queria consagrava sacerdote dos lugares altos.'),
('acf','1rs',13,34,'E isso foi causa de pecado à casa de Jeroboão, para destruí-la e extingui-la da terra.'),
('acf','1rs',14,1,'Naquele tempo adoeceu Abias, filho de Jeroboão.'),
('acf','1rs',14,2,'E disse Jeroboão à sua mulher: Levanta-te agora, e disfarça-te, para que não conheçam que és mulher de Jeroboão; e vai a Siló. Eis que lá está o profeta Aías, o qual falou de mim, que eu seria rei sobre este povo.'),
('acf','1rs',14,3,'E leva contigo dez pães, e bolos, e uma botija de mel, e vai a ele; ele te declarará o que há de suceder a este menino.'),
('acf','1rs',14,4,'E a mulher de Jeroboão assim fez, e se levantou, e foi a Siló, e entrou na casa de Aías; e já Aías não podia ver, porque os seus olhos estavam já escurecidos por causa da sua velhice.'),
('acf','1rs',14,5,'Porém o Senhor disse a Aías: Eis que a mulher de Jeroboão vem consultar-te sobre seu filho, porque está doente; assim e assim lhe falarás; porque há de ser que, entrando ela, fingirá ser outra.'),
('acf','1rs',14,6,'E sucedeu que, ouvindo Aías o ruído de seus pés, entrando ela pela porta, disse-lhe ele: Entra, mulher de Jeroboão; por que te disfarças assim? Pois eu sou enviado a ti com duras novas.'),
('acf','1rs',14,7,'Vai, dize a Jeroboão: Assim diz o Senhor Deus de Israel: Porquanto te levantei do meio do povo, e te pus por príncipe sobre o meu povo de Israel,'),
('acf','1rs',14,8,'E rasguei o reino da casa de Davi, e o dei a ti, e tu não foste como o meu servo Davi, que guardou os meus mandamentos e que andou após mim com todo o seu coração para fazer somente o que era reto aos meus olhos,'),
('acf','1rs',14,9,'Antes tu fizeste o mal, pior do que todos os que foram antes de ti; e foste, e fizeste outros deuses e imagens de fundição, para provocar-me à ira, e me lançaste para trás das tuas costas;'),
('acf','1rs',14,10,'Portanto, eis que trarei mal sobre a casa de Jeroboão; destruirei de Jeroboão todo o homem até ao menino, tanto o escravo como o livre em Israel; e lançarei fora os descendentes da casa de Jeroboão, como se lança fora o esterco, até que de todo se acabe.'),
('acf','1rs',14,11,'Quem morrer dos de Jeroboão, na cidade, os cães o comerão, e o que morrer no campo as aves do céu o comerão, porque o Senhor o disse.'),
('acf','1rs',14,12,'Tu, pois, levanta-te, e vai para tua casa; entrando os teus pés na cidade, o menino morrerá.'),
('acf','1rs',14,13,'E todo o Israel o pranteará, e o sepultará; porque de Jeroboão só este entrará em sepultura, porquanto se achou nele coisa boa para com o Senhor Deus de Israel em casa de Jeroboão.'),
('acf','1rs',14,14,'O Senhor, porém, levantará para si um rei sobre Israel, que destruirá a casa de Jeroboão no mesmo dia. Que digo eu? Há de ser já.'),
('acf','1rs',14,15,'Também o Senhor ferirá a Israel como se agita a cana nas águas; e arrancará a Israel desta boa terra que tinha dado a seus pais, e o espalhará para além do rio; porquanto fizeram os seus ídolos, provocando o Senhor à ira.'),
('acf','1rs',14,16,'E entregará a Israel por causa dos pecados de Jeroboão, o qual pecou, e fez pecar a Israel.'),
('acf','1rs',14,17,'Então a mulher de Jeroboão se levantou, e foi, e chegou a Tirza; chegando ela ao limiar da porta, morreu o menino.'),
('acf','1rs',14,18,'E o sepultaram, e todo o Israel o pranteou, conforme a palavra do Senhor, a qual dissera pelo ministério de seu servo Aías, o profeta.'),
('acf','1rs',14,19,'Quanto ao mais dos atos de Jeroboão, como guerreou, e como reinou, eis que está escrito no livro das crônicas dos reis de Israel.'),
('acf','1rs',14,20,'E foram os dias que Jeroboão reinou vinte e dois anos; e dormiu com seus pais; e Nadabe, seu filho, reinou em seu lugar.'),
('acf','1rs',14,21,'E Roboão, filho de Salomão, reinava em Judá; de quarenta e um anos de idade era Roboão quando começou a reinar, e dezessete anos reinou em Jerusalém, na cidade que o Senhor escolhera de todas as tribos de Israel para pôr ali o seu nome; e era o nome de sua mãe Naamá, amonita.'),
('acf','1rs',14,22,'E fez Judá o que era mau aos olhos do Senhor; e com os seus pecados que cometeram, provocaram-no a zelos, mais do que todos os seus pais fizeram.'),
('acf','1rs',14,23,'Porque também eles edificaram altos, e estátuas, e imagens de Aserá sobre todo o alto outeiro e debaixo de toda a árvore verde.'),
('acf','1rs',14,24,'Havia também sodomitas na terra; fizeram conforme a todas as abominações dos povos que o Senhor tinha expulsado de diante dos filhos de Israel.'),
('acf','1rs',14,25,'Ora, sucedeu que, no quinto ano do rei Roboão, Sisaque, rei do Egito, subiu contra Jerusalém,'),
('acf','1rs',14,26,'E tomou os tesouros da casa do Senhor e os tesouros da casa do rei; e levou tudo. Também tomou todos os escudos de ouro que Salomão tinha feito.'),
('acf','1rs',14,27,'E em lugar deles fez o rei Roboão escudos de cobre, e os entregou nas mãos dos chefes da guarda que guardavam a porta da casa do rei.'),
('acf','1rs',14,28,'E todas as vezes que o rei entrava na casa do Senhor, os da guarda os levavam, e depois os tornavam à câmara da guarda.'),
('acf','1rs',14,29,'Quanto ao mais dos atos de Roboão, e a tudo quanto fez, porventura não está escrito no livro das crônicas dos reis de Judá?'),
('acf','1rs',14,30,'E houve guerra entre Roboão e Jeroboão todos os seus dias.'),
('acf','1rs',14,31,'E Roboão dormiu com seus pais, e foi sepultado com seus pais na cidade de Davi; e era o nome de sua mãe Naamá, amonita; e Abias, seu filho, reinou em seu lugar.'),
('acf','1rs',15,1,'E no décimo oitavo ano do rei Jeroboão, filho de Nebate, Abias começou a reinar sobre Judá.'),
('acf','1rs',15,2,'E reinou três anos em Jerusalém; e era o nome de sua mãe Maaca, filha de Absalão.'),
('acf','1rs',15,3,'E andou em todos os pecados que seu pai tinha cometido antes dele; e seu coração não foi perfeito para com o Senhor seu Deus como o coração de Davi, seu pai.'),
('acf','1rs',15,4,'Mas por amor de Davi o Senhor seu Deus lhe deu uma lâmpada em Jerusalém, levantando a seu filho depois dele, e confirmando a Jerusalém.'),
('acf','1rs',15,5,'Porquanto Davi tinha feito o que era reto aos olhos do Senhor, e não se tinha desviado de tudo quanto lhe ordenara em todos os dias da sua vida, senão só no negócio de Urias, o heteu.'),
('acf','1rs',15,6,'E houve guerra entre Roboão e Jeroboão todos os dias da sua vida.'),
('acf','1rs',15,7,'Quanto ao mais dos atos de Abias, e a tudo quanto fez, porventura não está escrito no livro das crônicas dos reis de Judá? Também houve guerra entre Abias e Jeroboão.'),
('acf','1rs',15,8,'E Abias dormiu com seus pais, e o sepultaram na cidade de Davi; e Asa, seu filho, reinou em seu lugar.'),
('acf','1rs',15,9,'E no vigésimo ano de Jeroboão, rei de Israel, começou Asa a reinar em Judá.'),
('acf','1rs',15,10,'E quarenta e um anos reinou em Jerusalém; e era o nome de sua mãe Maaca, filha de Absalão.'),
('acf','1rs',15,11,'E Asa fez o que era reto aos olhos do Senhor, como Davi seu pai.'),
('acf','1rs',15,12,'Porque tirou da terra os sodomitas, e removeu todos os ídolos que seus pais fizeram.'),
('acf','1rs',15,13,'E até a Maaca, sua mãe, removeu para que não fosse rainha, porquanto tinha feito um horrível ídolo a Aserá; também Asa desfez o seu ídolo horrível, e o queimou junto ao ribeiro de Cedrom.'),
('acf','1rs',15,14,'Os altos, porém, não foram tirados; todavia foi o coração de Asa reto para com o Senhor todos os seus dias.'),
('acf','1rs',15,15,'E à casa do Senhor trouxe as coisas consagradas por seu pai, e as coisas que ele mesmo consagrara; prata, ouro e vasos.'),
('acf','1rs',15,16,'E houve guerra entre Asa e Baasa, rei de Israel, todos os seus dias.'),
('acf','1rs',15,17,'Porque Baasa, rei de Israel, subiu contra Judá, e edificou a Ramá, para que a ninguém fosse permitido sair, nem entrar a ter com Asa, rei de Judá.'),
('acf','1rs',15,18,'Então Asa tomou toda a prata e ouro que ficaram nos tesouros da casa do Senhor, e os tesouros da casa do rei, e os entregou nas mãos de seus servos; e o rei Asa os enviou a Ben-Hadade, filho de Tabrimom, filho de Heziom, rei da Síria, que habitava em Damasco, dizendo:'),
('acf','1rs',15,19,'Haja acordo entre mim e ti, como houve entre meu pai e teu pai; eis que te mando um presente, prata e ouro; vai, e anula o teu acordo com Baasa, rei de Israel, para que se retire de sobre mim.'),
('acf','1rs',15,20,'E Ben-Hadade deu ouvidos ao rei Asa, e enviou os capitães dos seus exércitos contra as cidades de Israel; e feriu a Ijom, e a Dã, e a Abel-Bete-Maaca, e a toda a Quinerete, com toda a terra de Naftali.'),
('acf','1rs',15,21,'E sucedeu que, ouvindo-o Baasa, deixou de edificar a Ramá; e ficou em Tirza.'),
('acf','1rs',15,22,'Então o rei Asa fez apregoar por toda a Judá que todos, sem exceção, trouxessem as pedras de Ramá, e a sua madeira com que Baasa edificara; e com elas edificou o rei Asa a Geba de Benjamim e a Mizpá.'),
('acf','1rs',15,23,'Quanto ao mais de todos os atos de Asa, e a todo o seu poder, e a tudo quanto fez, e as cidades que edificou, porventura não está escrito no livro das crônicas dos reis de Judá? Porém, no tempo da sua velhice, padeceu dos pés.'),
('acf','1rs',15,24,'E Asa dormiu com seus pais, e foi sepultado com seus pais na cidade de Davi, seu pai; e Jeosafá, seu filho, reinou em seu lugar.'),
('acf','1rs',15,25,'E Nadabe, filho de Jeroboão, começou a reinar sobre Israel no ano segundo de Asa, rei de Judá; e reinou sobre Israel dois anos.'),
('acf','1rs',15,26,'E fez o que era mau aos olhos do Senhor; e andou nos caminhos de seu pai, e no seu pecado com que seu pai fizera pecar a Israel.'),
('acf','1rs',15,27,'E conspirou contra ele Baasa, filho de Aías, da casa de Issacar, e feriu-o Baasa em Gibetom, que era dos filisteus, quando Nadabe e todo o Israel cercavam a Gibetom.'),
('acf','1rs',15,28,'E matou-o, pois, Baasa no ano terceiro de Asa, rei de Judá, e reinou em seu lugar.'),
('acf','1rs',15,29,'Sucedeu que, reinando ele, feriu a toda a casa de Jeroboão; nada de Jeroboão deixou que tivesse fôlego, até o destruir, conforme à palavra do Senhor que dissera pelo ministério de seu servo Aías, o silonita.'),
('acf','1rs',15,30,'Por causa dos pecados que Jeroboão cometera, e fez pecar a Israel, e por causa da provocação com que irritara ao Senhor Deus de Israel.'),
('acf','1rs',15,31,'Quanto ao mais dos atos de Nadabe, e a tudo quanto fez, porventura não está escrito no livro das crônicas dos reis de Israel?'),
('acf','1rs',15,32,'E houve guerra entre Asa e Baasa, rei de Israel, todos os seus dias.'),
('acf','1rs',15,33,'No ano terceiro de Asa, rei de Judá, Baasa, filho de Aías, começou a reinar sobre todo o Israel em Tirza, e reinou vinte e quatro anos.'),
('acf','1rs',15,34,'E fez o que era mau aos olhos do Senhor; e andou no caminho de Jeroboão, e no pecado com que ele tinha feito Israel pecar.'),
('acf','1rs',16,1,'Então veio a palavra do SENHOR a Jeú, filho de Hanani, contra Baasa, dizendo:'),
('acf','1rs',16,2,'Porquanto te levantei do pó, e te pus por príncipe sobre o meu povo Israel, e tu tens andado no caminho de Jeroboão, e tens feito pecar a meu povo Israel, irritando-me com os seus pecados,'),
('acf','1rs',16,3,'Eis que tirarei os descendentes de Baasa, e os descendentes da sua casa, e farei a tua casa como a casa de Jeroboão, filho de Nebate.'),
('acf','1rs',16,4,'Quem morrer dos de Baasa, na cidade, os cães o comerão; e o que dele morrer no campo, as aves do céu o comerão.'),
('acf','1rs',16,5,'Quanto ao mais dos atos de Baasa, e ao que fez, e ao seu poder, porventura não está escrito no livro das crônicas dos reis de Israel?'),
('acf','1rs',16,6,'E Baasa dormiu com seus pais, e foi sepultado em Tirza; e Elá, seu filho, reinou em seu lugar.'),
('acf','1rs',16,7,'Assim veio também a palavra do Senhor, pelo ministério do profeta Jeú, filho de Hanani, contra Baasa e contra a sua casa; e isso por todo o mal que fizera aos olhos do Senhor, irritando-o com a obra de suas mãos, para ser como a casa de Jeroboão; e porque o havia ferido.'),
('acf','1rs',16,8,'No ano vinte e seis de Asa, rei de Judá, Elá, filho de Baasa, começou a reinar em Tirza sobre Israel; e reinou dois anos.'),
('acf','1rs',16,9,'E Zinri, seu servo, capitão de metade dos carros, conspirou contra ele, estando ele em Tirza, bebendo e embriagando-se em casa de Arsa, mordomo em Tirza.'),
('acf','1rs',16,10,'Entrou, pois, Zinri, e o feriu, e o matou, no ano vigésimo sétimo de Asa, rei de Judá; e reinou em seu lugar.'),
('acf','1rs',16,11,'E sucedeu que, reinando ele, e estando assentado no seu trono, feriu a toda a casa de Baasa; não lhe deixou homem algum, nem a seus parentes, nem a seus amigos.'),
('acf','1rs',16,12,'Assim destruiu Zinri toda a casa de Baasa, conforme à palavra do Senhor que, contra Baasa, ele falara pelo ministério do profeta Jeú,'),
('acf','1rs',16,13,'Por todos os pecados de Baasa, e os pecados de Elá, seu filho, que cometeram, e com que fizeram pecar a Israel, irritando ao Senhor Deus de Israel com as suas vaidades.'),
('acf','1rs',16,14,'Quanto ao mais dos atos de Elá, e a tudo quanto fez, não está escrito no livro das crônicas dos reis de Israel?'),
('acf','1rs',16,15,'No ano vigésimo sétimo de Asa, rei de Judá, reinou Zinri sete dias em Tirza; e o povo estava acampado contra Gibetom, que era dos filisteus.'),
('acf','1rs',16,16,'E o povo que estava acampado ouviu dizer: Zinri tem conspirado, e até matou o rei. Todo o Israel pois, no mesmo dia, no arraial, constituiu rei sobre Israel a Onri, capitão do exército.'),
('acf','1rs',16,17,'E subiu Onri, e todo o Israel com ele, de Gibetom, e cercaram a Tirza.'),
('acf','1rs',16,18,'E sucedeu que Zinri, vendo que a cidade era tomada, foi ao paço da casa do rei e queimou-a sobre si; e morreu,'),
('acf','1rs',16,19,'Por causa dos pecados que cometera, fazendo o que era mau aos olhos do Senhor, andando no caminho de Jeroboão, e no pecado que ele cometera, fazendo Israel pecar.'),
('acf','1rs',16,20,'Quanto ao mais dos atos de Zinri, e à conspiração que fez, porventura não está escrito no livro das crônicas dos reis de Israel?'),
('acf','1rs',16,21,'Então o povo de Israel se dividiu em dois partidos: metade do povo seguia a Tibni, filho de Ginate, para o fazer rei, e a outra metade seguia a Onri.'),
('acf','1rs',16,22,'Mas o povo que seguia a Onri foi mais forte do que o povo que seguia a Tibni, filho de Ginate; e Tibni morreu, e Onri reinou.'),
('acf','1rs',16,23,'No ano trinta e um de Asa, rei de Judá, Onri começou a reinar sobre Israel, e reinou doze anos; e em Tirza reinou seis anos.'),
('acf','1rs',16,24,'E de Semer comprou o monte de Samaria por dois talentos de prata, e edificou nele; e chamou a cidade que edificou Samaria, do nome de Semer, dono do monte.'),
('acf','1rs',16,25,'E fez Onri o que era mau aos olhos do Senhor; e fez pior do que todos quantos foram antes dele.'),
('acf','1rs',16,26,'E andou em todos os caminhos de Jeroboão, filho de Nebate, como também nos pecados com que ele tinha feito pecar a Israel, irritando ao Senhor Deus de Israel com as suas vaidades.'),
('acf','1rs',16,27,'Quanto ao mais dos atos de Onri, ao que fez, e ao poder que manifestou, porventura não está escrito no livro das crônicas dos reis de Israel?'),
('acf','1rs',16,28,'E Onri dormiu com seus pais, e foi sepultado em Samaria; e Acabe, seu filho, reinou em seu lugar.'),
('acf','1rs',16,29,'E Acabe, filho de Onri, começou a reinar sobre Israel no ano trigésimo oitavo de Asa, rei de Judá; e reinou Acabe, filho de Onri, sobre Israel, em Samaria, vinte e dois anos.'),
('acf','1rs',16,30,'E fez Acabe, filho de Onri, o que era mau aos olhos do Senhor, mais do que todos os que foram antes dele.'),
('acf','1rs',16,31,'E sucedeu que (como se fora pouco andar nos pecados de Jeroboão, filho de Nebate) ainda tomou por mulher a Jezabel, filha de Etbaal, rei dos sidônios; e foi e serviu a Baal, e o adorou.'),
('acf','1rs',16,32,'E levantou um altar a Baal, na casa de Baal que edificara em Samaria.'),
('acf','1rs',16,33,'Também Acabe fez um ídolo; de modo que Acabe fez muito mais para irritar ao Senhor Deus de Israel, do que todos os reis de Israel que foram antes dele.'),
('acf','1rs',16,34,'Em seus dias Hiel, o betelita, edificou a Jericó; em Abirão, seu primogênito, a fundou, e em Segube, seu filho menor, pôs as suas portas; conforme a palavra do Senhor, que falara pelo ministério de Josué, filho de Num.'),
('acf','1rs',17,1,'Então Elias, o tisbita, dos moradores de Gileade, disse a Acabe: Vive o SENHOR Deus de Israel, perante cuja face estou, que nestes anos nem orvalho nem chuva haverá, senão segundo a minha palavra.'),
('acf','1rs',17,2,'Depois veio a ele a palavra do Senhor, dizendo:'),
('acf','1rs',17,3,'Retira-te daqui, e vai para o oriente, e esconde-te junto ao ribeiro de Querite, que está diante do Jordão.'),
('acf','1rs',17,4,'E há de ser que beberás do ribeiro; e eu tenho ordenado aos corvos que ali te sustentem.'),
('acf','1rs',17,5,'Foi, pois, e fez conforme a palavra do Senhor; porque foi, e habitou junto ao ribeiro de Querite, que está diante do Jordão.'),
('acf','1rs',17,6,'E os corvos lhe traziam pão e carne pela manhã; como também pão e carne à noite; e bebia do ribeiro.'),
('acf','1rs',17,7,'E sucedeu que, passados dias, o ribeiro se secou, porque não tinha havido chuva na terra.'),
('acf','1rs',17,8,'Então veio a ele a palavra do Senhor, dizendo:'),
('acf','1rs',17,9,'Levanta-te, e vai para Sarepta, que é de Sidom, e habita ali; eis que eu ordenei ali a uma mulher viúva que te sustente.'),
('acf','1rs',17,10,'Então ele se levantou, e foi a Sarepta; e, chegando à porta da cidade, eis que estava ali uma mulher viúva apanhando lenha; e ele a chamou, e lhe disse: Traze-me, peço-te, num vaso um pouco de água que beba.'),
('acf','1rs',17,11,'E, indo ela a trazê-la, ele a chamou e lhe disse: Traze-me agora também um bocado de pão na tua mão.'),
('acf','1rs',17,12,'Porém ela disse: Vive o Senhor teu Deus, que nem um bolo tenho, senão somente um punhado de farinha numa panela, e um pouco de azeite numa botija; e vês aqui apanhei dois cavacos, e vou prepará-lo para mim e para o meu filho, para que o comamos, e morramos.'),
('acf','1rs',17,13,'E Elias lhe disse: Não temas; vai, faze conforme à tua palavra; porém faze dele primeiro para mim um bolo pequeno, e traze-mo aqui; depois farás para ti e para teu filho.'),
('acf','1rs',17,14,'Porque assim diz o Senhor Deus de Israel: A farinha da panela não se acabará, e o azeite da botija não faltará até ao dia em que o Senhor dê chuva sobre a terra.'),
('acf','1rs',17,15,'E ela foi e fez conforme a palavra de Elias; e assim comeu ela, e ele, e a sua casa muitos dias.'),
('acf','1rs',17,16,'Da panela a farinha não se acabou, e da botija o azeite não faltou; conforme a palavra do Senhor, que ele falara pelo ministério de Elias.'),
('acf','1rs',17,17,'E depois destas coisas sucedeu que adoeceu o filho desta mulher, dona da casa; e a sua doença se agravou muito, até que nele nenhum fôlego ficou.'),
('acf','1rs',17,18,'Então ela disse a Elias: Que tenho eu contigo, homem de Deus? vieste tu a mim para trazeres à memória a minha iniqüidade, e matares a meu filho?'),
('acf','1rs',17,19,'E ele disse: Dá-me o teu filho. E ele o tomou do seu regaço, e o levou para cima, ao quarto, onde ele mesmo habitava, e o deitou em sua cama,'),
('acf','1rs',17,20,'E clamou ao Senhor, e disse: Ó Senhor meu Deus, também até a esta viúva, com quem me hospedo, afligiste, matando-lhe o filho?'),
('acf','1rs',17,21,'Então se estendeu sobre o menino três vezes, e clamou ao Senhor, e disse: Ó Senhor meu Deus, rogo-te que a alma deste menino torne a entrar nele.'),
('acf','1rs',17,22,'E o Senhor ouviu a voz de Elias; e a alma do menino tornou a entrar nele, e reviveu.'),
('acf','1rs',17,23,'E Elias tomou o menino, e o trouxe do quarto à casa, e o deu à sua mãe; e disse Elias: Vês aí, teu filho vive.'),
('acf','1rs',17,24,'Então a mulher disse a Elias: Nisto conheço agora que tu és homem de Deus, e que a palavra do Senhor na tua boca é verdade.'),
('acf','1rs',18,1,'E sucedeu que, depois de muitos dias, a palavra do SENHOR veio a Elias, no terceiro ano, dizendo: Vai, apresenta-te a Acabe; porque darei chuva sobre a terra.'),
('acf','1rs',18,2,'E foi Elias apresentar-se a Acabe; e a fome era extrema em Samaria.'),
('acf','1rs',18,3,'E Acabe chamou a Obadias, o mordomo; e Obadias temia muito ao Senhor,'),
('acf','1rs',18,4,'Porque sucedeu que, destruindo Jezabel os profetas do Senhor, Obadias tomou cem profetas, e de cinqüenta em cinqüenta os escondeu numa cova, e os sustentou com pão e água.'),
('acf','1rs',18,5,'E disse Acabe a Obadias: Vai pela terra a todas as fontes de água, e a todos os rios; pode ser que achemos erva, para que em vida conservemos os cavalos e mulas, e não percamos todos os animais.'),
('acf','1rs',18,6,'E repartiram entre si a terra, para a percorrerem: Acabe foi à parte por um caminho, e Obadias também foi sozinho por outro caminho.'),
('acf','1rs',18,7,'Estando, pois, Obadias já em caminho, eis que Elias o encontrou; e Obadias, reconhecendo-o, prostrou-se sobre o seu rosto, e disse: És tu o meu senhor Elias?'),
('acf','1rs',18,8,'E disse-lhe ele: Eu sou; vai, e dize a teu senhor: Eis que Elias está aqui.'),
('acf','1rs',18,9,'Porém ele disse: Em que pequei, para que entregues a teu servo na mão de Acabe, para que me mate?'),
('acf','1rs',18,10,'Vive o SENHOR teu Deus, que não houve nação nem reino aonde o meu senhor não mandasse em busca de ti; e dizendo eles: Aqui não está, então fazia jurar os reinos e nações, que não te haviam achado.'),
('acf','1rs',18,11,'E agora dizes tu: Vai, dize a teu senhor: Eis que aqui está Elias.'),
('acf','1rs',18,12,'E poderia ser que, apartando-me eu de ti, o Espírito do Senhor te tomasse, não sei para onde, e, vindo eu a dar as novas a Acabe, e não te achando ele, me mataria; porém eu, teu servo, temo ao Senhor desde a minha mocidade.'),
('acf','1rs',18,13,'Porventura não disseram a meu senhor o que fiz, quando Jezabel matava os profetas do SENHOR? Como escondi a cem homens dos profetas do SENHOR, de cinqüenta em cinqüenta, numa cova, e os sustentei com pão e água?'),
('acf','1rs',18,14,'E agora dizes tu: Vai, dize a teu senhor: Eis que Elias está aqui; ele me mataria.'),
('acf','1rs',18,15,'E disse Elias: Vive o Senhor dos Exércitos, perante cuja face estou, que deveras hoje me apresentarei a ele.'),
('acf','1rs',18,16,'Então foi Obadias encontrar-se com Acabe, e lho anunciou; e foi Acabe encontrar-se com Elias.'),
('acf','1rs',18,17,'E sucedeu que, vendo Acabe a Elias, disse-lhe: És tu o perturbador de Israel?'),
('acf','1rs',18,18,'Então disse ele: Eu não tenho perturbado a Israel, mas tu e a casa de teu pai, porque deixastes os mandamentos do Senhor, e seguistes a Baalim.'),
('acf','1rs',18,19,'Agora, pois, manda reunir-se a mim todo o Israel no monte Carmelo; como também os quatrocentos e cinqüenta profetas de Baal, e os quatrocentos profetas de Aserá, que comem da mesa de Jezabel.'),
('acf','1rs',18,20,'Então Acabe convocou todos os filhos de Israel; e reuniu os profetas no monte Carmelo.'),
('acf','1rs',18,21,'Então Elias se chegou a todo o povo, e disse: Até quando coxeareis entre dois pensamentos? Se o Senhor é Deus, segui-o, e se Baal, segui-o. Porém o povo nada lhe respondeu.'),
('acf','1rs',18,22,'Então disse Elias ao povo: Só eu fiquei por profeta do Senhor, e os profetas de Baal são quatrocentos e cinqüenta homens.'),
('acf','1rs',18,23,'Dêem-se-nos, pois, dois bezerros, e eles escolham para si um dos bezerros, e o dividam em pedaços, e o ponham sobre a lenha, porém não lhe coloquem fogo, e eu prepararei o outro bezerro, e o porei sobre a lenha, e não lhe colocarei fogo.'),
('acf','1rs',18,24,'Então invocai o nome do vosso deus, e eu invocarei o nome do Senhor; e há de ser que o deus que responder por meio de fogo esse será Deus. E todo o povo respondeu, dizendo: É boa esta palavra.'),
('acf','1rs',18,25,'E disse Elias aos profetas de Baal: Escolhei para vós um dos bezerros, e preparai-o primeiro, porque sois muitos, e invocai o nome do vosso deus, e não lhe ponhais fogo.'),
('acf','1rs',18,26,'E tomaram o bezerro que lhes dera, e o prepararam; e invocaram o nome de Baal, desde a manhã até ao meio-dia, dizendo: Ah! Baal, responde-nos! Porém nem havia voz, nem quem respondesse; e saltavam sobre o altar que tinham feito.'),
('acf','1rs',18,27,'E sucedeu que ao meio-dia Elias zombava deles e dizia: Clamai em altas vozes, porque ele é um deus; pode ser que esteja falando, ou que tenha alguma coisa que fazer, ou que intente alguma viagem; talvez esteja dormindo, e despertará.'),
('acf','1rs',18,28,'E eles clamavam em altas vozes, e se retalhavam com facas e com lancetas, conforme ao seu costume, até derramarem sangue sobre si.'),
('acf','1rs',18,29,'E sucedeu que, passado o meio-dia, profetizaram eles, até a hora de se oferecer o sacrifício da tarde; porém não houve voz, nem resposta, nem atenção alguma.'),
('acf','1rs',18,30,'Então Elias disse a todo o povo: Chegai-vos a mim. E todo o povo se chegou a ele; e restaurou o altar do Senhor, que estava quebrado.'),
('acf','1rs',18,31,'E Elias tomou doze pedras, conforme ao número das tribos dos filhos de Jacó, ao qual veio a palavra do Senhor, dizendo: Israel será o teu nome.'),
('acf','1rs',18,32,'E com aquelas pedras edificou o altar em nome do Senhor; depois fez um rego em redor do altar, segundo a largura de duas medidas de semente.'),
('acf','1rs',18,33,'Então armou a lenha, e dividiu o bezerro em pedaços, e o pôs sobre a lenha.'),
('acf','1rs',18,34,'E disse: Enchei de água quatro cântaros, e derramai-a sobre o holocausto e sobre a lenha. E disse: Fazei-o segunda vez; e o fizeram segunda vez. Disse ainda: Fazei-o terceira vez; e o fizeram terceira vez;'),
('acf','1rs',18,35,'De maneira que a água corria ao redor do altar; e até o rego ele encheu de água.'),
('acf','1rs',18,36,'Sucedeu que, no momento de ser oferecido o sacrifício da tarde, o profeta Elias se aproximou, e disse: Ó Senhor Deus de Abraão, de Isaque e de Israel, manifeste-se hoje que tu és Deus em Israel, e que eu sou teu servo, e que conforme à tua palavra fiz todas estas coisas.'),
('acf','1rs',18,37,'Responde-me, Senhor, responde-me, para que este povo conheça que tu és o Senhor Deus, e que tu fizeste voltar o seu coração.'),
('acf','1rs',18,38,'Então caiu fogo do Senhor, e consumiu o holocausto, e a lenha, e as pedras, e o pó, e ainda lambeu a água que estava no rego.'),
('acf','1rs',18,39,'O que vendo todo o povo, caíram sobre os seus rostos, e disseram: Só o Senhor é Deus! Só o Senhor é Deus!'),
('acf','1rs',18,40,'E Elias lhes disse: Lançai mão dos profetas de Baal, que nenhum deles escape. E lançaram mão deles; e Elias os fez descer ao ribeiro de Quisom, e ali os matou.'),
('acf','1rs',18,41,'Então disse Elias a Acabe: Sobe, come e bebe, porque há ruído de uma abundante chuva.'),
('acf','1rs',18,42,'E Acabe subiu a comer e a beber; mas Elias subiu ao cume do Carmelo, e se inclinou por terra, e pôs o seu rosto entre os seus joelhos.'),
('acf','1rs',18,43,'E disse ao seu servo: Sobe agora, e olha para o lado do mar. E subiu, e olhou, e disse: Não há nada. Então disse ele: Volta lá sete vezes.'),
('acf','1rs',18,44,'E sucedeu que, à sétima vez, disse: Eis aqui uma pequena nuvem, como a mão de um homem, subindo do mar. Então disse ele: Sobe, e dize a Acabe: Aparelha o teu carro, e desce, para que a chuva não te impeça.'),
('acf','1rs',18,45,'E sucedeu que, entretanto, os céus se enegreceram com nuvens e vento, e veio uma grande chuva; e Acabe subiu ao carro, e foi para Jizreel.'),
('acf','1rs',18,46,'E a mão do Senhor estava sobre Elias, o qual cingiu os lombos, e veio correndo perante Acabe, até à entrada de Jizreel.'),
('acf','1rs',19,1,'E Acabe fez saber a Jezabel tudo quanto Elias havia feito, e como totalmente matara todos os profetas à espada.'),
('acf','1rs',19,2,'Então Jezabel mandou um mensageiro a Elias, a dizer-lhe: Assim me façam os deuses, e outro tanto, se de certo amanhã a estas horas não puser a tua vida como a de um deles.'),
('acf','1rs',19,3,'O que vendo ele, se levantou e, para escapar com vida, se foi, e chegando a Berseba, que é de Judá, deixou ali o seu servo.'),
('acf','1rs',19,4,'Ele, porém, foi ao deserto, caminho de um dia, e foi sentar-se debaixo de um zimbro; e pediu para si a morte, e disse: Já basta, ó Senhor; toma agora a minha vida, pois não sou melhor do que meus pais.'),
('acf','1rs',19,5,'E deitou-se, e dormiu debaixo do zimbro; e eis que então um anjo o tocou, e lhe disse: Levanta-te, come.'),
('acf','1rs',19,6,'E olhou, e eis que à sua cabeceira estava um pão cozido sobre as brasas, e uma botija de água; e comeu, e bebeu, e tornou a deitar-se.'),
('acf','1rs',19,7,'E o anjo do Senhor tornou segunda vez, e o tocou, e disse: Levanta-te e come, porque te será muito longo o caminho.'),
('acf','1rs',19,8,'Levantou-se, pois, e comeu e bebeu; e com a força daquela comida caminhou quarenta dias e quarenta noites até Horebe, o monte de Deus.'),
('acf','1rs',19,9,'E ali entrou numa caverna e passou ali a noite; e eis que a palavra do Senhor veio a ele, e lhe disse: Que fazes aqui Elias?'),
('acf','1rs',19,10,'E ele disse: Tenho sido muito zeloso pelo Senhor Deus dos Exércitos, porque os filhos de Israel deixaram a tua aliança, derrubaram os teus altares, e mataram os teus profetas à espada, e só eu fiquei, e buscam a minha vida para ma tirarem.'),
('acf','1rs',19,11,'E Deus lhe disse: Sai para fora, e põe-te neste monte perante o Senhor. E eis que passava o Senhor, como também um grande e forte vento que fendia os montes e quebrava as penhas diante do Senhor; porém o Senhor não estava no vento; e depois do vento um terremoto; também o Senhor não estava no terremoto;'),
('acf','1rs',19,12,'E depois do terremoto um fogo; porém também o Senhor não estava no fogo; e depois do fogo uma voz mansa e delicada.'),
('acf','1rs',19,13,'E sucedeu que, ouvindo-a Elias, envolveu o seu rosto na sua capa, e saiu para fora, e pôs-se à entrada da caverna; e eis que veio a ele uma voz, que dizia: Que fazes aqui, Elias?'),
('acf','1rs',19,14,'E ele disse: Eu tenho sido em extremo zeloso pelo Senhor Deus dos Exércitos, porque os filhos de Israel deixaram a tua aliança, derrubaram os teus altares, e mataram os teus profetas à espada, e só eu fiquei; e buscam a minha vida para ma tirarem.'),
('acf','1rs',19,15,'E o Senhor lhe disse: Vai, volta pelo teu caminho para o deserto de Damasco; e, chegando lá, unge a Hazael rei sobre a Síria.'),
('acf','1rs',19,16,'Também a Jeú, filho de Ninsi, ungirás rei de Israel; e também a Eliseu, filho de Safate de Abel-Meolá, ungirás profeta em teu lugar.'),
('acf','1rs',19,17,'E há de ser que o que escapar da espada de Hazael, matá-lo-á Jeú; e o que escapar da espada de Jeú, matá-lo-á Eliseu.'),
('acf','1rs',19,18,'Também deixei ficar em Israel sete mil: todos os joelhos que não se dobraram a Baal, e toda a boca que não o beijou.'),
('acf','1rs',19,19,'Partiu, pois, Elias dali, e achou a Eliseu, filho de Safate, que andava lavrando com doze juntas de bois adiante dele, e ele estava com a duodécima; e Elias passou por ele, e lançou a sua capa sobre ele.'),
('acf','1rs',19,20,'Então deixou ele os bois, e correu após Elias; e disse: Deixa-me beijar a meu pai e a minha mãe, e então te seguirei. E ele lhe disse: Vai, e volta; pois, que te fiz eu?'),
('acf','1rs',19,21,'Voltou, pois, de o seguir, e tomou a junta de bois, e os matou, e com os aparelhos dos bois cozeu as carnes, e as deu ao povo, e comeram; então se levantou e seguiu a Elias, e o servia.'),
('acf','1rs',20,1,'E Ben-Hadade, rei da Síria, ajuntou todo o seu exército; e havia com ele trinta e dois reis, e cavalos e carros; e subiu, e cercou a Samaria, e pelejou contra ela.'),
('acf','1rs',20,2,'E enviou à cidade mensageiros, a Acabe, rei de Israel,'),
('acf','1rs',20,3,'Que lhe disseram: Assim diz Ben-Hadade: A tua prata e o teu ouro são meus; e tuas mulheres e os melhores de teus filhos são meus.'),
('acf','1rs',20,4,'E respondeu o rei de Israel, e disse: Conforme a tua palavra, ó rei meu senhor, eu sou teu, e tudo quanto tenho.'),
('acf','1rs',20,5,'E tornaram a vir os mensageiros, e disseram: Assim diz Ben-Hadade: Enviei-te, na verdade, mensageiros que dissessem: Tu me hás de dar a tua prata, e o teu ouro, e as tuas mulheres e os teus filhos;'),
('acf','1rs',20,6,'Todavia amanhã a estas horas enviarei os meus servos a ti, e esquadrinharão a tua casa, e as casas dos teus servos; e há de ser que tudo o que de precioso tiveres, eles tomarão consigo, e o levarão.'),
('acf','1rs',20,7,'Então o rei de Israel chamou a todos os anciãos da terra, e disse: Notai agora, e vede como este homem procura o mal; pois mandou pedir-me as mulheres, os meus filhos, a minha prata e o meu ouro, e não lhos neguei.'),
('acf','1rs',20,8,'E todos os anciãos e todo o povo lhe disseram: Não lhe dês ouvidos, nem consintas.'),
('acf','1rs',20,9,'Por isso disse aos mensageiros de Ben-Hadade: Dizei ao rei, meu senhor: Tudo o que primeiro mandaste pedir a teu servo, farei, porém isto não posso fazer. E voltaram os mensageiros, e lhe levaram a resposta.'),
('acf','1rs',20,10,'E Ben-Hadade enviou a ele mensageiros dizendo: Assim me façam os deuses, e outro tanto, que o pó de Samaria não bastará para encher as mãos de todo o povo que me segue.'),
('acf','1rs',20,11,'Porém o rei de Israel respondeu: Dizei-lhe: Não se gabe quem se cinge das armas, como aquele que as descinge.'),
('acf','1rs',20,12,'E sucedeu que, ouvindo ele esta palavra, estando a beber com os reis nas tendas, disse aos seus servos: Ponde-vos em ordem contra a cidade.'),
('acf','1rs',20,13,'E eis que um profeta se chegou a Acabe rei de Israel, e lhe disse: Assim diz o Senhor: Viste toda esta grande multidão? Eis que hoje ta entregarei nas tuas mãos, para que saibas que eu sou o Senhor.'),
('acf','1rs',20,14,'E disse Acabe: Por quem? E ele disse: Assim diz o Senhor: Pelos moços dos príncipes das províncias. E disse: Quem começará a peleja? E disse: Tu.'),
('acf','1rs',20,15,'Então contou os moços dos príncipes das províncias, e foram duzentos e trinta e dois; e depois deles contou a todo o povo, todos os filhos de Israel, sete mil.'),
('acf','1rs',20,16,'E saíram ao meio-dia; e Ben-Hadade estava bebendo e embriagando-se nas tendas, ele e os reis, os trinta e dois reis, que o ajudavam.'),
('acf','1rs',20,17,'E os moços dos príncipes das províncias saíram primeiro; e Ben-Hadade enviou espias, que lhe deram avisos, dizendo: Saíram de Samaria uns homens.'),
('acf','1rs',20,18,'E ele disse: Ainda que para paz saíssem, tomai-os vivos; e ainda que à peleja saíssem, tomai-os vivos.'),
('acf','1rs',20,19,'Saíram, pois, da cidade os moços dos príncipes das províncias, e o exército que os seguia.'),
('acf','1rs',20,20,'E eles feriram cada um o seu adversário, e os sírios fugiram, e Israel os perseguiu; porém Ben-Hadade, rei da Síria, escapou a cavalo, com alguns cavaleiros.'),
('acf','1rs',20,21,'E saiu o rei de Israel, e feriu os cavalos e os carros; e feriu os sírios com grande estrago.'),
('acf','1rs',20,22,'Então o profeta chegou-se ao rei de Israel e lhe disse: Vai, esforça-te, e atenta, e olha o que hás de fazer; porque no decurso de um ano o rei da Síria subirá contra ti.'),
('acf','1rs',20,23,'Porque os servos do rei da Síria lhe disseram: Seus deuses são deuses dos montes, por isso foram mais fortes do que nós; mas pelejemos com eles em campo raso, e por certo veremos, se não somos mais fortes do que eles!'),
('acf','1rs',20,24,'Faze, pois, isto: tira os reis, cada um do seu lugar, e substitui-os por capitães;'),
('acf','1rs',20,25,'E forma outro exército, igual ao exército que perdeste, cavalo por cavalo, e carro por carro, e pelejemos com eles em campo raso, e veremos se não somos mais fortes do que eles! E deu ouvidos à sua voz, e assim fez.'),
('acf','1rs',20,26,'E sucedeu que, passado um ano, Ben-Hadade passou revista aos sírios, e subiu a Afeque, para pelejar contra Israel.'),
('acf','1rs',20,27,'Também aos filhos de Israel se passou revista, e providos de víveres marcharam contra eles; e os filhos de Israel acamparam-se defronte deles, como dois pequenos rebanhos de cabras; mas os sírios enchiam a terra.'),
('acf','1rs',20,28,'E chegou o homem de Deus, e falou ao rei de Israel, e disse: Assim diz o Senhor: Porquanto os sírios disseram: O Senhor é Deus dos montes, e não Deus dos vales; toda esta grande multidão entregarei nas tuas mãos; para que saibas que eu sou o Senhor.'),
('acf','1rs',20,29,'E sete dias estiveram acampados uns defronte dos outros; e sucedeu ao sétimo dia que a peleja começou, e os filhos de Israel feriram dos sírios cem mil homens de pé, num dia.'),
('acf','1rs',20,30,'E os restantes fugiram a Afeque, à cidade; e caiu o muro sobre vinte e sete mil homens, que restaram; Ben-Hadade, porém, fugiu, e veio à cidade, escondendo-se de câmara em câmara.'),
('acf','1rs',20,31,'Então lhe disseram os seus servos: Eis que já temos ouvido que os reis da casa de Israel são reis clementes; ponhamos, pois, sacos aos lombos, e cordas às cabeças, e saiamos ao rei de Israel; pode ser que ele te poupe a vida.'),
('acf','1rs',20,32,'Então cingiram sacos aos lombos e cordas às cabeças, e foram ao rei de Israel, e disseram: Diz o teu servo Ben-Hadade: Deixa-me viver. E disse Acabe: Pois ainda vive? É meu irmão.'),
('acf','1rs',20,33,'E aqueles homens tomaram isto por bom presságio, e apressaram-se em apanhar a sua palavra, e disseram: Teu irmão Ben-Hadade vive. E ele disse: Vinde, trazei-mo. Então Ben-Hadade foi a ele, e ele o fez subir ao carro.'),
('acf','1rs',20,34,'E disse ele: As cidades que meu pai tomou de teu pai tas restituirei, e faze para ti ruas em Damasco, como meu pai as fez em Samaria. E eu, respondeu Acabe, te deixarei ir com esta aliança. E fez com ele aliança e o deixou ir.'),
('acf','1rs',20,35,'Então um dos homens dos filhos dos profetas disse ao seu companheiro, pela palavra do Senhor: Ora fere-me. E o homem recusou feri-lo.'),
('acf','1rs',20,36,'E ele lhe disse: Porque não obedeceste à voz do Senhor, eis que, em te apartando de mim, um leão te ferirá. E como dele se apartou, um leão o encontrou e o feriu.'),
('acf','1rs',20,37,'Depois encontrou outro homem, e disse-lhe: Ora fere-me. E aquele homem deu-lhe um golpe, ferindo-o.'),
('acf','1rs',20,38,'Então foi o profeta, e pôs-se perante o rei no caminho; e disfarçou-se com cinza sobre os seus olhos.'),
('acf','1rs',20,39,'E sucedeu que, passando o rei, clamou ele ao rei, dizendo: Teu servo estava no meio da peleja, e eis que, desviando-se um homem, trouxe-me outro homem, e disse: Guarda-me este homem; se vier a faltar, será a tua vida em lugar da vida dele, ou pagarás um talento de prata.'),
('acf','1rs',20,40,'Sucedeu, pois, que, estando o teu servo ocupado de uma e de outra parte, eis que o homem desapareceu. Então o rei de Israel lhe disse: Esta é a tua sentença; tu mesmo a pronunciaste.'),
('acf','1rs',20,41,'Então ele se apressou, e tirou a cinza de sobre os seus olhos; e o rei de Israel o reconheceu, que era um dos profetas.'),
('acf','1rs',20,42,'E disse-lhe: Assim diz o Senhor: Porquanto soltaste da mão o homem que eu havia posto para destruição, a tua vida será em lugar da sua vida, e o teu povo em lugar do seu povo.'),
('acf','1rs',20,43,'E foi o rei de Israel para a sua casa, desgostoso e indignado; e chegou a Samaria.'),
('acf','1rs',21,1,'E sucedeu depois destas coisas que, Nabote, o jizreelita, tinha uma vinha em Jizreel junto ao palácio de Acabe, rei de Samaria.'),
('acf','1rs',21,2,'Então Acabe falou a Nabote, dizendo: Dá-me a tua vinha, para que me sirva de horta, pois está vizinha ao lado da minha casa; e te darei por ela outra vinha melhor: ou, se for do teu agrado, dar-te-ei o seu valor em dinheiro.'),
('acf','1rs',21,3,'Porém Nabote disse a Acabe: Guarde-me o Senhor de que eu te dê a herança de meus pais.'),
('acf','1rs',21,4,'Então Acabe veio desgostoso e indignado à sua casa, por causa da palavra que Nabote, o jizreelita, lhe falara, quando disse: Não te darei a herança de meus pais. E deitou-se na sua cama, e voltou o rosto, e não comeu pão.'),
('acf','1rs',21,5,'Porém, vindo a ele Jezabel, sua mulher, lhe disse: Que há, que está tão desgostoso o teu espírito, e não comes pão?'),
('acf','1rs',21,6,'E ele lhe disse: Porque falei a Nabote, o jizreelita, e lhe disse: Dá-me a tua vinha por dinheiro; ou, se te apraz, te darei outra vinha em seu lugar. Porém ele disse: Não te darei a minha vinha.'),
('acf','1rs',21,7,'Então Jezabel, sua mulher lhe disse: Governas tu agora no reino de Israel? Levanta-te, come pão, e alegre-se o teu coração; eu te darei a vinha de Nabote, o jizreelita.'),
('acf','1rs',21,8,'Então escreveu cartas em nome de Acabe, e as selou com o seu sinete; e mandou as cartas aos anciãos e aos nobres que havia na sua cidade e habitavam com Nabote.'),
('acf','1rs',21,9,'E escreveu nas cartas, dizendo: Apregoai um jejum, e ponde Nabote diante do povo.'),
('acf','1rs',21,10,'E ponde defronte dele dois filhos de Belial, que testemunhem contra ele, dizendo: Blasfemaste contra Deus e contra o rei; e trazei-o fora, e apedrejai-o para que morra.'),
('acf','1rs',21,11,'E os homens da sua cidade, os anciãos e os nobres que habitavam na sua cidade, fizeram como Jezabel lhes ordenara, conforme estava escrito nas cartas que lhes mandara.'),
('acf','1rs',21,12,'Apregoaram um jejum, e puseram a Nabote diante do povo.'),
('acf','1rs',21,13,'Então vieram dois homens, filhos de Belial, e puseram-se defronte dele; e os homens, filhos de Belial, testemunharam contra ele, contra Nabote, perante o povo, dizendo: Nabote blasfemou contra Deus e contra o rei. E o levaram para fora da cidade, e o apedrejaram, e morreu.'),
('acf','1rs',21,14,'Então mandaram dizer a Jezabel: Nabote foi apedrejado, e morreu.'),
('acf','1rs',21,15,'E sucedeu que, ouvindo Jezabel que já fora apedrejado Nabote, e morrera, disse a Acabe: Levanta-te, e possui a vinha de Nabote, o jizreelita, a qual te recusou dar por dinheiro; porque Nabote não vive, mas é morto.'),
('acf','1rs',21,16,'E sucedeu que, ouvindo Acabe, que Nabote já era morto, levantou-se para descer para a vinha de Nabote, o jizreelita, para tomar posse dela.'),
('acf','1rs',21,17,'Então veio a palavra do Senhor a Elias, o tisbita, dizendo:'),
('acf','1rs',21,18,'Levanta-te, desce para encontrar-te com Acabe, rei de Israel, que está em Samaria; eis que está na vinha de Nabote, aonde tem descido para possuí-la.'),
('acf','1rs',21,19,'E falar-lhe-ás, dizendo: Assim diz o Senhor: Porventura não mataste e tomaste a herança? Falar-lhe-ás mais, dizendo: Assim diz o Senhor: No lugar em que os cães lamberam o sangue de Nabote lamberão também o teu próprio sangue.'),
('acf','1rs',21,20,'E disse Acabe a Elias: Já me achaste, inimigo meu? E ele disse: Achei-te; porquanto já te vendeste para fazeres o que é mau aos olhos do Senhor.'),
('acf','1rs',21,21,'Eis que trarei mal sobre ti, e arrancarei a tua posteridade, e arrancarei de Acabe a todo o homem, tanto o escravo como o livre em Israel;'),
('acf','1rs',21,22,'E farei a tua casa como a casa de Jeroboão, filho de Nebate, e como a casa de Baasa, filho de Aías; por causa da provocação, com que me provocaste e fizeste pecar a Israel.'),
('acf','1rs',21,23,'E também acerca de Jezabel falou o Senhor, dizendo: Os cães comerão a Jezabel junto ao antemuro de Jizreel.'),
('acf','1rs',21,24,'Aquele que morrer dos de Acabe, na cidade, os cães o comerão; e o que morrer no campo as aves do céu o comerão.'),
('acf','1rs',21,25,'Porém ninguém fora como Acabe, que se vendera para fazer o que era mau aos olhos do Senhor; porque Jezabel, sua mulher, o incitava.'),
('acf','1rs',21,26,'E fez grandes abominações, seguindo os ídolos, conforme a tudo o que fizeram os amorreus, os quais o Senhor lançou fora da sua possessão, de diante dos filhos de Israel.'),
('acf','1rs',21,27,'Sucedeu, pois, que Acabe, ouvindo estas palavras, rasgou as suas vestes, e cobriu a sua carne de saco, e jejuou; e jazia em saco, e andava mansamente.'),
('acf','1rs',21,28,'Então veio a palavra do Senhor a Elias tisbita, dizendo:'),
('acf','1rs',21,29,'Não viste que Acabe se humilha perante mim? Por isso, porquanto se humilha perante mim, não trarei este mal nos seus dias, mas nos dias de seu filho o trarei sobre a sua casa.'),
('acf','1rs',22,1,'E estiveram quietos três anos, não havendo guerra entre a Síria e Israel.'),
('acf','1rs',22,2,'Porém no terceiro ano sucedeu que Jeosafá, rei de Judá, desceu para avistar-se com o rei de Israel.'),
('acf','1rs',22,3,'E o rei de Israel disse aos seus servos: Não sabeis vós que Ramote de Gileade é nossa, e nós estamos quietos, sem a tomar da mão do rei da Síria?'),
('acf','1rs',22,4,'Então perguntou a Jeosafá: Irás tu comigo à peleja a Ramote de Gileade? E disse Jeosafá ao rei de Israel: Serei como tu, e o meu povo como o teu povo, e os meus cavalos como os teus cavalos.'),
('acf','1rs',22,5,'Disse mais Jeosafá ao rei de Israel: Peço-te, consulta hoje a palavra do Senhor.'),
('acf','1rs',22,6,'Então o rei de Israel reuniu os profetas até quase quatrocentos homens, e disse-lhes: Irei à peleja contra Ramote de Gileade, ou deixarei de ir? E eles disseram: Sobe, porque o Senhor a entregará na mão do rei.'),
('acf','1rs',22,7,'Disse, porém, Jeosafá: Não há aqui ainda algum profeta do Senhor, ao qual possamos consultar?'),
('acf','1rs',22,8,'Então disse o rei de Israel a Jeosafá: Ainda há um homem por quem podemos consultar ao Senhor; porém eu o odeio, porque nunca profetiza de mim o que é bom, mas só o mal; este é Micaías, filho de Inlá. E disse Jeosafá: Não fale o rei assim.'),
('acf','1rs',22,9,'Então o rei de Israel chamou um oficial, e disse: Traze-me depressa a Micaías, filho de Inlá.'),
('acf','1rs',22,10,'E o rei de Israel e Jeosafá, rei de Judá, estavam assentados cada um no seu trono, vestidos de trajes reais, na praça, à entrada da porta de Samaria; e todos os profetas profetizavam na sua presença.'),
('acf','1rs',22,11,'E Zedequias, filho de Quenaaná, fez para si uns chifres de ferro, e disse: Assim diz o Senhor: Com estes ferirás aos sírios, até de todo os consumir.'),
('acf','1rs',22,12,'E todos os profetas profetizaram assim, dizendo: Sobe a Ramote de Gileade, e triunfarás, porque o Senhor a entregará na mão do rei.'),
('acf','1rs',22,13,'E o mensageiro que foi chamar a Micaías falou-lhe, dizendo: Vês aqui que as palavras dos profetas a uma voz predizem coisas boas para o rei; seja, pois, a tua palavra como a palavra de um deles, e fala bem.'),
('acf','1rs',22,14,'Porém Micaías disse: Vive o Senhor que o que o Senhor me disser isso falarei.'),
('acf','1rs',22,15,'E, vindo ele ao rei, o rei lhe disse: Micaías, iremos a Ramote de Gileade à peleja, ou deixaremos de ir? E ele lhe disse: Sobe, e serás bem sucedido; porque o Senhor a entregará na mão do rei.'),
('acf','1rs',22,16,'E o rei lhe disse: Até quantas vezes te conjurarei, que não me fales senão a verdade em nome do Senhor?'),
('acf','1rs',22,17,'Então disse ele: Vi a todo o Israel disperso pelos montes, como ovelhas que não tem pastor; e disse o Senhor: Estes não têm senhor; torne cada um em paz para sua casa.'),
('acf','1rs',22,18,'Então o rei de Israel disse a Jeosafá: Não te disse eu, que nunca profetizará de mim o que é bom, senão só o que é mal?'),
('acf','1rs',22,19,'Então ele disse: Ouve, pois, a palavra do Senhor: Vi ao Senhor assentado sobre o seu trono, e todo o exército do céu estava junto a ele, à sua mão direita e à sua esquerda.'),
('acf','1rs',22,20,'E disse o Senhor: Quem induzirá Acabe, para que suba, e caia em Ramote de Gileade? E um dizia desta maneira e outro de outra.'),
('acf','1rs',22,21,'Então saiu um espírito, e se apresentou diante do Senhor, e disse: Eu o induzirei. E o Senhor lhe disse: Com quê?'),
('acf','1rs',22,22,'E disse ele: Eu sairei, e serei um espírito de mentira na boca de todos os seus profetas. E ele disse: Tu o induzirás, e ainda prevalecerás; sai e faze assim.'),
('acf','1rs',22,23,'Agora, pois, eis que o Senhor pôs o espírito de mentira na boca de todos estes teus profetas, e o Senhor falou o mal contra ti.'),
('acf','1rs',22,24,'Então Zedequias, filho de Quenaaná, chegou, e feriu a Micaías no queixo, e disse: Por onde saiu de mim o Espírito do Senhor para falar a ti?'),
('acf','1rs',22,25,'E disse Micaías: Eis que o verás naquele mesmo dia, quando entrares de câmara em câmara para te esconderes.'),
('acf','1rs',22,26,'Então disse o rei de Israel: Tomai a Micaías, e tornai a levá-lo a Amom, o governador da cidade e a Joás filho do rei.'),
('acf','1rs',22,27,'E direis: Assim diz o rei: Colocai este homem na casa do cárcere, e sustentai-o com o pão de angústia, e com água de amargura, até que eu venha em paz.'),
('acf','1rs',22,28,'E disse Micaías: Se tu voltares em paz, o Senhor não tem falado por mim. Disse mais: Ouvi, povos todos!'),
('acf','1rs',22,29,'Assim o rei de Israel e Jeosafá, rei de Judá, subiram a Ramote de Gileade.'),
('acf','1rs',22,30,'E disse o rei de Israel a Jeosafá: Eu me disfarçarei, e entrarei na peleja; tu porém veste as tuas roupas. Disfarçou-se, pois o rei de Israel, e entrou na peleja.'),
('acf','1rs',22,31,'E o rei da Síria dera ordem aos capitães dos carros, que eram trinta e dois, dizendo: Não pelejareis nem contra pequeno nem contra grande, mas só contra o rei de Israel.'),
('acf','1rs',22,32,'Sucedeu que, vendo os capítães dos carros a Jeosafá, disseram eles: Certamente este é o rei de Israel. E chegaram-se a ele, para pelejar com ele; porém Jeosafá gritou.'),
('acf','1rs',22,33,'E sucedeu que, vendo os capitães dos carros que não era o rei de Israel, deixaram de segui-lo.'),
('acf','1rs',22,34,'Então um homem armou o arco, e atirou a esmo, e feriu o rei de Israel por entre as fivelas e as couraças; então ele disse ao seu carreteiro: Dá volta, e tira-me do exército, porque estou gravemente ferido.'),
('acf','1rs',22,35,'E a peleja foi crescendo nequele dia, e o rei foi sustentado no carro defronte dos sírios; porém ele morreu à tarde; e o sangue da ferida corria para o fundo do carro.'),
('acf','1rs',22,36,'E depois do sol posto passou um pregão pelo exército, dizendo: Cada um para a sua cidade, e cada um para a sua terra!'),
('acf','1rs',22,37,'E morreu o rei, e o levaram a Samaria; e sepultaram o rei em Samaria.'),
('acf','1rs',22,38,'E, lavando-se o carro no tanque de Samaria, os cães lamberam o seu sangue (ora as prostitutas se lavavam ali), conforme à palavra que o Senhor tinha falado.'),
('acf','1rs',22,39,'Quanto ao mais dos atos de Acabe, e a tudo quanto fez, e à casa de marfim que edificou, porventura não está escrito no livro das crônicas dos reis de Israel?'),
('acf','1rs',22,40,'Assim dormiu Acabe com seus pais; e Acazias, seu filho, reinou em seu lugar.'),
('acf','1rs',22,41,'E Jeosafá, filho de Asa, começou a reinar sobre Judá no quarto ano de Acabe, rei de Israel.'),
('acf','1rs',22,42,'E era Jeosafá da idade de trinta e cinco anos quando começou a reinar; e vinte e cinco anos reinou em Jerusalém; e era o nome de sua mãe Azuba, filha de Sili.'),
('acf','1rs',22,43,'E andou em todos os caminhos de seu pai Asa, não se desviou deles, fazendo o que era reto aos olhos do Senhor.'),
('acf','1rs',22,44,'Todavia os altos não se tiraram; ainda o povo sacrificava e queimava incenso nos altos.'),
('acf','1rs',22,45,'E Jeosafá esteve em paz com o rei de Israel.'),
('acf','1rs',22,46,'Quanto ao mais dos atos de Jeosafá, e ao poder que mostrou, e como guerreou, porventura não está escrito no livro das crônicas dos reis de Judá?'),
('acf','1rs',22,47,'Também expulsou da terra o restante dos sodomitas, que ficaram nos dias de seu pai Asa.'),
('acf','1rs',22,48,'Então não havia rei em Edom, porém um vice-rei.'),
('acf','1rs',22,49,'E fez Jeosafá navios de Társis, para irem a Ofir por causa do ouro; porém não foram, porque os navios se quebraram em Eziom-Geber.'),
('acf','1rs',22,50,'Então Acazias, filho de Acabe, disse a Jeosafá: Vão os meus servos com os teus servos nos navios. Porém Jeosafá não quis.'),
('acf','1rs',22,51,'E Jeosafá dormiu com seus pais, e foi sepultado junto a eles, na cidade de Davi, seu pai; e Jeorão, seu filho, reinou em seu lugar.'),
('acf','1rs',22,52,'E Acazias, filho de Acabe, começou a reinar sobre Israel, em Samaria, no ano dezessete de Jeosafá, rei de Judá; e reinou dois anos sobre Israel.'),
('acf','1rs',22,53,'E fez o que era mau aos olhos do Senhor; porque andou no caminho de seu pai, como também no caminho de sua mãe, e no caminho de Jeroboão, filho de Nebate, que fez pecar a Israel.'),
('acf','1rs',22,54,'E serviu a Baal, e adorou-o, e provocou a ira do Senhor Deus de Israel, conforme a tudo quanto fizera seu pai.')
